 {
  "id": "CPP-423",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 423",
  "titulo": "Nota de Redacción (Derogado por Ley 8498) — Procedimientos especiales · Proceso de menores",
  "tags": "423 nota de redaccion (derogado por ley 8498) procedimientos especiales proceso menores",
  "texto": "Nota de Redacción (Derogado por Ley 8498)"
 },
 {
  "id": "CPP-424",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 424",
  "titulo": "Derecho de querella — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "424 derecho de querella procedimientos especiales juicio por delito accion privada",
  "texto": "Toda persona que se pretenda ofendida por un delito de acción privada tendrá derecho a presentar querella ante los Tribunales y a ejercer conjuntamente la acción civil resarcitoria.\nIgual derecho tendrá el representante legal del incapaz por los delitos cometidos en perjuicio de éste y quien resulte víctima de un delito de acción pública y se encuentre habilitado para efectuar la conversión a acción privada, conforme lo dispuesto en este Código."
 },
 {
  "id": "CPP-425",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 425",
  "titulo": "Unidad de Representación — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "425 unidad de representacion procedimientos especiales juicio por delito accion privada",
  "texto": "Cuando los querellantes fueran varios, deberán actuar bajo una sola representación, la que se ordenará de oficio si ellos no se pusieran de acuerdo."
 },
 {
  "id": "CPP-426",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 426",
  "titulo": "Acumulación de Causas — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "426 acumulacion de causas procedimientos especiales juicio por delito accion privada",
  "texto": "La acumulación de causas por delitos de acción privada se regirá por las disposiciones comunes, pudiendo procederse así cuando se trate de calumnias o injurias recíprocas, pero ellas no se acumularán con las incoadas por delitos de acción pública."
 },
 {
  "id": "CPP-427",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 427",
  "titulo": "Forma y contenido de la querella — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "427 forma y contenido de la querella procedimientos especiales juicio por delito accion privada",
  "texto": "La querella será presentada por escrito, con patrocinio letrado, con una copia para cada querellado, personalmente o por mandatario especial y deberá expresar, bajo pena de inadmisibilidad:\n1) El nombre, apellido y domicilio del querellante y, en su caso, también los del mandatario;\n2) El nombre, apellido y domicilio del querellado o, si se ignorasen, cualquier descripción que sirva para identificarlo;\n3) Una relación clara, precisa y circunstanciada del hecho, con indicación de lugar, fecha y hora en que se ejecutó, si se supiere;\n4) Si se ejerciere la acción civil, la demanda para la reparación de los daños y perjuicios ocasionados;\n5) Las pruebas que se ofrezcan indicando, en su caso, los datos que permitan llevar adelante su producción. Si se trata de testigos o peritos, además de los datos personales y domicilio se indicarán los puntos sobre los que deberán ser examinados o requeridos.\nCuando la querella verse sobre calumnias o injurias, el documento que a criterio del accionante las contenga, si fuere posible presentarlo. En los supuestos de conversión de la acción pública en privada, la solicitud de que el Juez requiera al Fiscal el expediente con los actos procesales cumplidos que habiliten este procedimiento, y 6) La firma del querellante cuando se presentare personalmente o si no supiere firmar, la de otra persona a su ruego, quien deberá hacerlo ante el Secretario.\nDentro de los cinco (5) días de recibida la querella, el Juez decidirá su admisión o rechazo. Será rechazada por auto fundado en los casos previstos por el artículo 334 de este Código, o si faltara alguno de los requisitos establecidos en el presente artículo. En el último caso el escrito y demás elementos acompañados serán devueltos al pretenso querellante, si correspondiere, quien podrá reiterar su petición sólo si corrigiera sus defectos con mención del anterior rechazo. Si la querella se refiriera a un delito de acción pública, salvo en los casos de conversión de la acción, la misma será remitida al Fiscal de Instrucción."
 },
 {
  "id": "CPP-428",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 428",
  "titulo": "Responsabilidad del Querellante — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "428 responsabilidad del querellante procedimientos especiales juicio por delito de accion privada",
  "texto": "El querellante quedará sometido a la jurisdicción del Tribunal en todo lo referente al juicio por él promovido y a sus consecuencias legales."
 },
 {
  "id": "CPP-429",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 429",
  "titulo": "Renuncia expresa — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "429 renuncia expresa procedimientos especiales juicio por delito de accion privada",
  "texto": "El querellante podrá renunciar en cualquier estado del juicio pero quedará sujeto a responsabilidad por sus actos anteriores. La renuncia no podrá supeditarse a condiciones pero podrá hacerse expresa reserva de la acción civil si ésta no hubiera sido promovida juntamente con la penal."
 },
 {
  "id": "CPP-430",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 430",
  "titulo": "Renuncia tácita — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "430 renuncia tacita procedimientos especiales juicio por delito de accion privada",
  "texto": "Se tendrá por renunciada la acción penal:\n1) Si el procedimiento se paralizare durante veinte (20) días por inactividad del querellante o su mandatario y éstos no lo instaren dentro del tercer día de notificado el decreto, que se dictará aun de oficio, por el cual se les prevenga el significado de su silencio;\n2) Cuando el querellante o su mandatario no concurrieren a la audiencia de conciliación o del debate sin justa causa, la que deberán acreditar antes de su iniciación si fuere posible o, en caso contrario, dentro de las cuarenta y ocho (48) horas de la fecha fijada para aquella, o 3) Cuando acaecida la muerte o incapacidad del querellante no compareciere ninguno de sus herederos o representantes legales a proseguir la acción, dentro de los sesenta (60) días después de ocurrida la muerte o incapacidad."
 },
 {
  "id": "CPP-431",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 431",
  "titulo": "Efectos de la renuncia — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "431 efectos de la renuncia procedimientos especiales juicio por delito accion privada",
  "texto": "Cuando el Juez declare extinguida la pretensión penal por renuncia del querellante, sobreseerá en la causa y le impondrá las costas, salvo que las partes hubieran convenido a este respecto otra cosa.\nLa extinción de la acción penal favorecerá a todos los que hubieran participado en el juicio que la motivó.\nSECCÓN SEGUNDA PROCEDIMIENTO"
 },
 {
  "id": "CPP-432",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 432",
  "titulo": "Audiencia de conciliación — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "432 audiencia de conciliacion procedimientos especiales juicio por delito accion privada",
  "texto": "Admitida la querella, se convocará a las partes a una audiencia de conciliación dentro de los quince (15) días. Se remitirá al querellado una copia de aquélla intimándolo a que designe abogado defensor con anticipación de dos (2) días a la fecha en que fuera fijada la audiencia, bajo apercibimiento de nombrarle uno público.\nCuando no concurra el querellado el proceso seguirá su curso."
 },
 {
  "id": "CPP-433",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 433",
  "titulo": "Investigación preliminar — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "433 investigacion preliminar procedimientos especiales juicio por delito de accion privada",
  "texto": "Si no se hubiera logrado identificar o individualizar al querellado o determinar su domicilio o si para describir clara, precisa y circunstanciadamente el delito fuera imprescindible llevar a cabo diligencias que el querellante no pudiera realizar por sí mismo o deban agregarse al proceso documentos que no estén en su poder, requerirá en su presentación una investigación preliminar, indicando las medidas pertinentes.\nEl Juez prestará el auxilio, si corresponde, practicando las diligencias dentro de los cuarenta y cinco (45) días. Luego el querellante complementará su querella y, eventualmente su demanda, dentro de los diez (10) días de obtenida la información faltante."
 },
 {
  "id": "CPP-434",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 434",
  "titulo": "Conciliación y retractación — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "434 conciliacion y retractacion procedimientos especiales juicio por delito de accion privada",
  "texto": "Cuando las partes se concilien en la audiencia o en cualquier estado del juicio se sobreseerá en la causa y las costas serán por el orden causado, salvo que aquéllas convengan otra cosa.\nEn los delitos de injurias y calumnias si el querellado se retractare en la audiencia o al contestar la querella y el querellante lo aceptara, la causa será sobreseída y las costas quedarán a su cargo. Si el querellante no aceptare la retractación por considerarla insuficiente el Juez decidirá en la audiencia. La retractación será publicada a petición del querellante en la forma que el Tribunal estimare adecuada."
 },
 {
  "id": "CPP-435",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 435",
  "titulo": "Prisión y embargo — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "435 prision y embargo procedimientos especiales juicio por delito de accion privada",
  "texto": "El Juez podrá ordenar, a solicitud del querellante, la prisión preventiva del querellado, previo una información sumaria y su declaración, sólo cuando concurran los requisitos del artículo 281 de este Código.\nCuando el querellante ejerza la acción civil podrá pedir el embargo de los bienes del querellado, respecto de lo cual se aplicarán las disposiciones comunes."
 },
 {
  "id": "CPP-436",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 436",
  "titulo": "Citación a juicio — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "436 citacion a juicio procedimientos especiales por delito de accion privada",
  "texto": "Si el querellado no concurriere a la audiencia de conciliación o no se produjere ésta o la retractación, será citado para que en el término de diez (10) días comparezca a juicio y ofrezca prueba con arreglo al inciso 5) del artículo 427 de este Código, sin perjuicio de lo dispuesto en el artículo siguiente."
 },
 {
  "id": "CPP-437",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 437",
  "titulo": "Excepciones — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "437 excepciones procedimientos especiales juicio por delito de accion privada",
  "texto": "Durante el término prefijado, el querellado podrá oponer excepciones previas de conformidad al Título II, Capítulo 1, Sección Tercera del Libro Primero."
 },
 {
  "id": "CPP-438",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 438",
  "titulo": "Fijación de Audiencias — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "438 fijacion de audiencias procedimientos especiales juicio por delito accion privada",
  "texto": "Vencido el término previsto por el artículo 436 o resueltas las excepciones en el sentido de la prosecución del juicio, se fijará día y hora para el debate conforme al artículo 367 y el querellante adelantará en su caso los fondos a que se refiere el artículo 371."
 },
 {
  "id": "CPP-439",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 439",
  "titulo": "Debate — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "439 debate procedimientos especiales juicio por delito de accion privada",
  "texto": "El debate se efectuará de acuerdo con las disposiciones comunes. El querellante tendrá las facultades y obligaciones correspondientes al Ministerio Público; podrá ser interrogado, perso no se le requerirá juramento."
 },
 {
  "id": "CPP-440",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 440",
  "titulo": "Incomparecencia del Querellado — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "440 incomparecencia del querellado procedimientos especiales juicio por delito de accion privada",
  "texto": "Si el querellado o su representante no compareciere al debate, se procederá en la forma dispuesta por los artículos 375 y\n376."
 },
 {
  "id": "CPP-441",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 441",
  "titulo": "Ejecución — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "441 ejecucion procedimientos especiales juicio por delito de accion privada",
  "texto": "La sentencia será ejecutada con arreglo a las disposiciones comunes. En el juicio por calumnias o injurias podrá ordenarse, a petición de parte, la publicación de la sentencia a costa del vencido."
 },
 {
  "id": "CPP-442",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 442",
  "titulo": "Recursos — Procedimientos especiales · Juicio por delito de acción privada",
  "tags": "442 recursos procedimientos especiales juicio por delito de accion privada",
  "texto": "Con respecto a los recursos se aplicarán las normas comunes."
 },
 {
  "id": "CPP-443",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 443",
  "titulo": "Reglas Generales — Disposiciones generales",
  "tags": "443 reglas generales disposiciones",
  "texto": "Las resoluciones judiciales serán recurribles sólo por los medios y en los casos expresamente establecidos.\nEl derecho de recurrir corresponderá tan sólo a quien le sea expresamente acordado, siempre que tuviere un interés directo.\nCuando la ley no distinga entre las diversas partes, aquél pertenecerá a cualquiera de ellas."
 },
 {
  "id": "CPP-444",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 444",
  "titulo": "Recursos del Ministerio Público — Disposiciones generales",
  "tags": "444 recursos del ministerio publico disposiciones generales",
  "texto": "En los casos establecidos por la ley, el Ministerio Público podrá recurrir inciso a favor del imputado o en virtud de la decisión del superior jerárquico, no obstante el dictamen contrario que hubiere emitido antes."
 },
 {
  "id": "CPP-445",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 445",
  "titulo": "Recrusos del Imputado — Disposiciones generales",
  "tags": "445 recrusos del imputado disposiciones generales",
  "texto": "El imputado podrá impugnar la sentencia de sobreseimiento o la absolutoria cuando le impongan una medida de seguridad; o solamente de las disposiciones que contenga la sentencia sobre la restitución o el resarcimiento de los daños.\nLos recursos a favor del imputado podrán ser deducidos por él o su defensor, y si fuere menor edad, también por sus padres o tutor aunque éstos no tengan derecho a que se les notifique la resolución."
 },
 {
  "id": "CPP-446",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 446",
  "titulo": "Recursos del Querellante Particular — Disposiciones generales",
  "tags": "446 recursos del querellante particular disposiciones generales",
  "texto": "El querellante particular sólo podrá recurrir de las resoluciones jurisdiccionales cuando lo hiciera el Ministerio Público, salvo que se le acuerde expresamente tal derecho."
 },
 {
  "id": "CPP-447",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 447",
  "titulo": "Recursos del Actor Civil — Disposiciones generales",
  "tags": "447 recursos del actor civil disposiciones generales",
  "texto": "El actor civil podrá recurrir de las resoluciones jurisdiccionales sólo en lo concerniente a la acción por él interpuesta."
 },
 {
  "id": "CPP-448",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 448",
  "titulo": "Recursos del Demandado Civil — Disposiciones generales",
  "tags": "448 recursos del demandado civil disposiciones generales",
  "texto": "El demandado civil podrá recurrir de la sentencia que declare su responsabilidad."
 },
 {
  "id": "CPP-449",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 449",
  "titulo": "Condiciones de Interposición — Disposiciones generales",
  "tags": "449 condiciones de interposicion disposiciones generales",
  "texto": "Los recursos deberán interponerse, bajo pena de inadmisibilidad, en las condiciones de tiempo y forma que se determinan, con específica indicación de los puntos de la decisión que fueren impugnados."
 },
 {
  "id": "CPP-450",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 450",
  "titulo": "Adhesión — Disposiciones generales",
  "tags": "450 adhesion disposiciones generales",
  "texto": "El que tenga derecho a recurrir podrá adherir, dentro del término de emplazamiento, al recurso concedido a otro, siempre que exprese, bajo pena de inadmisibilidad, los motivos en que se funda."
 },
 {
  "id": "CPP-451",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 451",
  "titulo": "Recursos durante el Juicio — Disposiciones generales",
  "tags": "451 recursos durante el juicio disposiciones generales",
  "texto": "Durante el juicio sólo se podrá deducir reposición, la que será resuelta: en la etapa preliminar, sin trámite; en el debate, sin suspenderlo.\nLos demás recursos podrán deducirse solamente junto con la impugnación de la sentencia, siempre que se hubiere hecho expresa reserva inmediatamente después del proveído.\nCuando la sentencia sea irrecurrible, también lo será la resolución impugnada."
 },
 {
  "id": "CPP-452",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 452",
  "titulo": "Efecto Extensivo — Disposiciones generales",
  "tags": "452 efecto extensivo disposiciones generales",
  "texto": "Cuando el delito que se juzgue apareciere cometido por varios computados, el recurso interpuesto en favor de uno de ellos favorecerá también a los demás, a menos que se base en motivos exclusivamente personales.\nEn casos de acumulación de causas por delitos diversos, el recurso deducido por un imputado favorecerá a todos, siempre que se base en la inobservancia de normas procesales que les afecte y no en motivos exclusivamente personales.\nTambién favorecerá al imputado el recurso del demandado civil, toda vez que éste alegue la inexistencia del hecho, niegue que aquél lo cometió o que constituya delito, sostenga que se ha extinguido la pretensión represiva o que la acción penal no pudo iniciarse o no puede proseguir."
 },
 {
  "id": "CPP-453",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 453",
  "titulo": "Efecto Suspensivo — Disposiciones generales",
  "tags": "453 efecto suspensivo disposiciones generales",
  "texto": "La resolución no será ejecutada durante el término para recurrir y mientras se tramite el recurso, salvo disposición en contrario."
 },
 {
  "id": "CPP-454",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 454",
  "titulo": "Desistimiento — Disposiciones generales",
  "tags": "454 desistimiento disposiciones generales",
  "texto": "El Ministerio Público podrá desistir de sus recursos, en dictamen funadado, aún si lo hubiera interpuesto un representante de grado inferior.\nTambién podrán desistir las partes de los recursos deducidos por ellas o sus defensores, sin perjuiciar a los demás recurrentes o adherentes, pero cargarán con las costas.\nPara desistir de un recurso, el defensor deberá tener mandato especial de su representado."
 },
 {
  "id": "CPP-455",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 455",
  "titulo": "Inadmisibilidad o Rechazo — Disposiciones generales",
  "tags": "455 inadmisibilidad o rechazo disposiciones generales",
  "texto": "El recurso no será concedido por el Tribunal que dictó la resolución impugnada, cuando ésta fuere irrecurrible, o aquél no fuere interpuesto en tiempo, por quien tenga derecho.\nSi el recurso fuere inadmisible el Tribunal de Alzada deberá declararlo así sin pronunciarse sobre el fondo. También deberá rechazar el recurso cuando fuere evidente que es sustancialmente improcedente."
 },
 {
  "id": "CPP-456",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 456",
  "titulo": "Competencia del Tribunal de Alzada — Disposiciones generales",
  "tags": "456 competencia del tribunal de alzada disposiciones generales",
  "texto": "El recurso atribuirá al Tribunal de Alzada el conocimiento del proceso sólo en cuanto a los puntos de la resolución a que se refieran los agravios.\nLos recursos interpuestos por el Ministerio Público permitirán modificar o revocar la resolución aún a favor del imputado.\nCuando hubiere sido recurrida solamente por el imputado o a su favor, la resolución no podrá ser modificada en su perjuicio, en cuanto a la especie o cantidad de la pena ni a los beneficios acordados."
 },
 {
  "id": "CPP-457",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 457",
  "titulo": "Objeto — Reposición",
  "tags": "457 objeto reposicion",
  "texto": "El recurso de reposición procederá contra los autos que resuelvan sin sustanciación un incidente o artículo del proceso, a fin de que el mismo Tribunal que los dictó los revoque o modifique por contrario imperio."
 },
 {
  "id": "CPP-458",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 458",
  "titulo": "Trámite — Reposición",
  "tags": "458 tramite reposicion",
  "texto": "Este recurso se interpondrá dentro del tercer día, por escrito que lo fundamente. El Juez lo resolverá por auto en el término de cinco días, previa vista a los interesados."
 },
 {
  "id": "CPP-459",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 459",
  "titulo": "Efectos — Reposición",
  "tags": "459 efectos reposicion",
  "texto": "La resolución que recaiga hará ejecutoria, a menos que el recurso hubiera sido deducido junto con el de apelación en subsidio, y éste fuere procedente.\nEste recurso tendrá efecto suspensivo sólo cuando la resolución recurrida fuere apelable con ese efecto."
 },
 {
  "id": "CPP-460",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 460",
  "titulo": "Resoluciones Apelables — Apelación",
  "tags": "460 resoluciones apelables apelacion",
  "texto": "El recurso de apelación procederá tan sólo contra las resoluciones de los Jueces de Control, siempre que expresamente sean declaradas apelables o causen gravamen irreparable."
 },
 {
  "id": "CPP-461",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 461",
  "titulo": "Interposición — Apelación",
  "tags": "461 interposicion apelacion",
  "texto": "Este recurso deberá interponerse por escrito o diligencia dentro del término de tres días y ante el mismo Tribunal que dictó la resolución.\nEl Ministerio Público y el querellante particular podrán recurrir, pero el primero deberá hacerlo fundadamente.\nEn esta oportunidad, el apelante deberá manifestar si informará oralmente.\nCuando el Tribunal de Alzada resida en otra ciudad, la parte deberá fijar nuevo domicilio, bajo pena de inadmisibilidad.\nEl Tribunal deberá expedirse sobre la concesión del recurso dentro del término de tres días."
 },
 {
  "id": "CPP-462",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 462",
  "titulo": "Emplazamiento — Apelación",
  "tags": "462 emplazamiento apelacion",
  "texto": "Concedido el recurso, se emplazará a los interesados para que comparezcan ante el Tribunal de Alzada en el plazo de cinco días, a contar desde que las actuaciones tuvieron entrada en el mismo o desde que se haya pronunciado el Fiscal de conformidad al artículo 464, lo que se les hará saber. El plazo será de ocho días cuando ese Tribunal tenga su sede en otra ciudad."
 },
 {
  "id": "CPP-463",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 463",
  "titulo": "Elevación de Actuaciones — Apelación",
  "tags": "463 elevacion de actuaciones apelacion",
  "texto": "Cuando se impugnare la sentencia de sobreseimiento, el expediente será elevado inmediatamente después de la última notificación. Si la apelación se produjere en un incidente, se elevarán sus actuaciones.\nEn los demás casos, sólo se remitirán copias de los actos pertinentes.\nNo obstante, el Tribunal de Alzada podrá requerir el expediente principal, por un plazo no mayor de cinco días."
 },
 {
  "id": "CPP-464",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 464",
  "titulo": "Dictamen Fiscal — Apelación",
  "tags": "464 dictamen fiscal apelacion",
  "texto": "Cuando el recurso haya sido interpuesto por el Ministerio Público, se correrá vista al Fiscal de Cámara en cuanto se reciban las actuaciones para que, en el término perentorio de cinco días, exprese si lo mantiene o no. Su silencio implicará desistimiento.\nCuando el Fiscal desista y no haya otro apelante o adherente, las actuaciones serán devueltas enseguida por decreto."
 },
 {
  "id": "CPP-465",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 465",
  "titulo": "Fundamentación — Apelación",
  "tags": "465 fundamentacion apelacion",
  "texto": "Durante el término de emplazamiento, las partes podrán examinar las actuaciones y deberán presentar informe por escrito sobre sus pretensiones, el que será agregado a los autos al vencimiento del plazo.\nLa falta de presentación de informes implicará el desistimiento de recurso."
 },
 {
  "id": "CPP-466",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 466",
  "titulo": "Audiencia — Apelación",
  "tags": "466 audiencia apelacion",
  "texto": "Cuando el apelante (461 segundo párrafo) o el Fiscal de Cámara (464) lo hubiese solicitado, el Presidente de la Cámara de Acusación fijará audiencia para que las partes informen oralmente, en cuya oportunidad no se admitirá la incorporación de memoriales o escritos por parte del recurrente.\nLos demás interesados podrán presentar el informe por escrito pero en este caso no podrán hacer uso de la palabra.\nLa audiencia deberá llevarse a cabo dentro de los tres días posteriores al vencimiento del término del emplazamiento (462).\nRegirá lo dispuesto en el último párrafo del artículo anterior."
 },
 {
  "id": "CPP-467",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 467",
  "titulo": "Resolución — Apelación",
  "tags": "467 resolucion apelacion",
  "texto": "El Tribunal se pronunciará dentro del término de tres días si el recurso versare sobre la libertad del imputado, y de diez en toda otra materia; y devolverá enseguida las actuaciones a los fines, en su caso, de la ejecución.\nEl término se contará desde la audiencia (466) o del vencimiento del emplazamiento\n(462)."
 },
 {
  "id": "CPP-467-bis",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 467 bis",
  "titulo": "Trámite especial — Apelación",
  "tags": "467 bis tramite especial apelacion",
  "texto": "Cuando el recurso de apelación versare sobre la libertad del imputado regirá el trámite previsto en este artículo.\nLa impugnación se tramitará y resolverá en audiencia oral y reservada que se celebrará con un intervalo no menor de cinco (5) días ni mayor de treinta (30) a partir de la recepción de las actuaciones, garantizando los principios de contradicción, inmediación y celeridad.\nEn la audiencia deberán informar oralmente el Fiscal de Instrucción y eldefensor del imputado. La incomparecencia, el silencio o la falta de fundamentación de una de las partes implicará el consentimiento de la pretensión contraria. El Tribunal podrá formular preguntas aclaratorias sobre las cuestiones planteadas y resolverá exclusivamente en función de lo alegado en la audiencia. Finalizada la misma se dictará resolución en forma inmediata o dentro de los tres (3) días cuando las circunstancias del caso así lo justifiquen."
 },
 {
  "id": "CPP-468",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 468",
  "titulo": "- Motivos — Casación · Procedencia",
  "tags": "468 - motivos casacion procedencia",
  "texto": "El recurso de casación podrá ser interpuesto por los siguientes motivos:\n1) Inobservancia o errónea aplicación de la Ley sustantiva, o 2) Inobservancia de las normas que este Código establece bajo pena de inadmisibilidad, caducidad o nulidad, siempre que, con excepción de los casos de nulidad absoluta previstos en el artículo 186 segunda parte de este Código, el recurrente hubiera reclamado oportunamente la subsanación del defecto -si era posible- o hubiera hecho protesta de recurrir en casación.\nSi se tratase del recurso del imputado contra la sentencia condenatoria conforme al inciso 1) del artículo 472 del presente Código, también podrá ser interpuesto por vicios en la fundamentación probatoria, sea en la selección, valoración o asignación de mérito convictivo de pruebas de carácter decisivo o cuando las pruebas no acreditaren indudablemente la existencia del hecho y la participación culpable del condenado en el mismo."
 },
 {
  "id": "CPP-469",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 469",
  "titulo": "Resoluciones Recurribles — Casación · Procedencia",
  "tags": "469 resoluciones recurribles casacion procedencia",
  "texto": "Además de los casos especialmente previstos por la ley y con las limitaciones establecidas en los artículos siguientes, sólo podrá deducirse este recurso contra las sentencias definitivas o los autos que pongan fin a la pena, o hagan imposible que continúen, o que denieguen la extinción, conmutación o suspensión de la pena."
 },
 {
  "id": "CPP-470",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 470",
  "titulo": "Recursos del Ministerio Público — Casación · Procedencia",
  "tags": "470 recursos del ministerio publico casacion procedencia",
  "texto": "El Ministerio Público podrá impugnar:\n1) Las sentencias de sobreseimiento confirmada o dictada por las Cámaras, si el delito imputado estuviere reprimido con pena mayor a tres años de reclusión o prisión o cinco años de inhabilitación.\n2) La sentencia absolutoria de la Cámara en lo Criminal, cuando hubiera requerido la imposición de una pena que exceda dicho límite, o si fuera del Juez Correccional o del juez de Menores, cuando la pena pedida sea superior a seis meses de prisión o un año de inhabilitación.\n3) La sentencia condenatoria, cuando la diferencia entre la pena impuesta y la reuqerida sea mayor a la prevista en el inciso anterior.\n4) Los autos mencionados en el artículo 469."
 },
 {
  "id": "CPP-471",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 471",
  "titulo": "Recursos del Querellante Particular.- El querellante particular podrá impugnar las sentencias mencionadas en los incisos 1 y 2 del artículo anterior. Regirá el trámite del artículo 464 ante el Fiscal General — Casación · Procedencia",
  "tags": "471 recursos del querellante particular.- el particular podra impugnar las sentencias mencionadas en los incisos 1 y 2 articulo anterior. regira tramite 464 ante fiscal general casacion procedencia",
  "texto": "Recursos del Querellante Particular.- El querellante particular podrá impugnar las sentencias mencionadas en los incisos 1 y 2 del artículo anterior. Regirá el trámite del artículo 464 ante el Fiscal General."
 },
 {
  "id": "CPP-472",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 472",
  "titulo": "Recursos del Imputado — Casación · Procedencia",
  "tags": "472 recursos del imputado casacion procedencia",
  "texto": "El imputado podrá impugnar:\n1) La sentencia de la Cámara en lo Criminal que lo condene a más de tres años de reclusión o prisión o cinco años de inhabilitación, y aún bajo el aspecto penal, cuando se le imponga restitución o indemnización por un valor total superior a treinta Unidades Económicas (30 U.E - Ley N° 8226).\n2) La sentencia del Juez Correccional o de Menores que lo condene a más de seis meses de prisión o un año de inhabilitación, y aún bajo el aspecto penal, cuando se le imponga restitución o indemnización por un valor superior a veinte Unidades Económicas (20 U.E. - Ley 8226) 3) La sentencia de sobreseimiento o absolutoria que le imponga una medida de seguridad por tiempo indeterminado.\n4) Los autos que denieguen la extinción, conmutación o suspensión de la pena."
 },
 {
  "id": "CPP-473",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 473",
  "titulo": "Recursos del Actor y del Demandado Civil — Casación · Procedencia",
  "tags": "473 recursos del actor y demandado civil casacion procedencia",
  "texto": "El actor civil podrá impugnar la sentencia de la Cámara en lo Criminal o del Juez Correccional de acuerdo con el Artículo 447, siempre que su agravio fuere superior a treinta Unidades Económicas (30 U.E.) y veinte Unidades Económicas (20 U.E.) respectivamente (Ley\n8226).\nPara determinar el agravio se tendrá en cuenta el monto de la demanda y la sentencia; pero cuando la primera aparezca manifiestamente exagerada con el propósito de hacer admisible el recurso, éste podrá ser desestimado por el Tribunal Superior sin pronunciarse sobre el fondo.\nEl demandado civil podrá recurrir en casación de acuerdo con el Artículo 448, cuando pueda hacerlo el imputado."
 },
 {
  "id": "CPP-474",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 474",
  "titulo": "Interposición — Casación · Procedimiento",
  "tags": "474 interposicion casacion procedimiento",
  "texto": "El recurso de casación será interpuesto ante el Tribunal que dictó la resolución en el plazo de quince días de notificada y por escrito con firma de letrado, en el cual se citarán concretamente las disposiciones legales que se consideren violadas o erróneamente aplicadas y se expresará cuál es la aplicación que se pretende.\nDeberá indicarse separadamente cada motivo con sus fundamentos. Fuera de esta oportunidad no podrá aducirse ningún otro motivo.\nEl recurrente deberá manifestar si informará oralmente.\nA excepción del plazo previsto en el primer párrafo del presente artículo, si se tratase del recurso del imputado contra la sentencia condenatoria según lo establecido en el inciso\n1) del artículo 472 de este Código, la inobservancia de las restantes exigencias formales no causará inadmisibilidad."
 },
 {
  "id": "CPP-475",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 475",
  "titulo": "Proveido — Casación · Procedimiento",
  "tags": "475 proveido casacion procedimiento",
  "texto": "El Tribunal proveerá lo que corresponda, en el término de tres días, de acuerdo con el artículo 455.\nCuando el recurso sea concedido, se procederá conforme a los artículos 462 y 463, elevándose el expediente al Tribunal Superior."
 },
 {
  "id": "CPP-476",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 476",
  "titulo": "Trámite — Casación · Procedimiento",
  "tags": "476 tramite casacion procedimiento",
  "texto": "En cuanto al trámite ante el Tribunal Superior se aplicarán los artículos 455 segunda parte, 464, 465 primera parte y 466, más en término fijado por el último, será de diez días."
 },
 {
  "id": "CPP-477",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 477",
  "titulo": "Debate — Casación · Procedimiento",
  "tags": "477 debate casacion procedimiento",
  "texto": "Cuando fuere el caso, el debate se efectuará el día fijado y en el momento oportuno, con asistencia de todos los miembros del Tribunal Superior que deban dictar sentencia, y del Fiscal.\nNo será necesario que asitan y hablen todos los abogados de las partes.\nLa palabra será concedida primero al defensor del recurrente.\nCuando también hubiera recurrido el Ministerio Público, su representante hablará en primer término.\nNo se admitirán réplicas, pero los abogados de las partes, podrán presentar, antes de la deliberación, breves notas escritas.\nEn cuanto fueren aplicables, regirán los artículos 372, 373, 377, 378 y 381."
 },
 {
  "id": "CPP-478",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 478",
  "titulo": "Deliberación — Casación · Procedimiento",
  "tags": "478 deliberacion casacion procedimiento",
  "texto": "Después de la audiencia, los jueces se reunirán a deliberar conforme al artículo 405, y en cuanto fuere aplicable, se observará el 406.\nSin embargo, por la importancia de las cuestiones a resolver o por lo avanzado de la hora, la deliberación podrá ser diferida para otra fecha.\nEl Presidente podrá señalar el tiempo de estudio para cada miembro del Tribunal.\nLa sentencia se dictará dentro de un plazo de veinta días conforme, en lo pertinente, con los artículos 408 y 409, excepto la segunda parte del último."
 },
 {
  "id": "CPP-479",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 479",
  "titulo": "Casación por la Violación de la Ley — Casación · Procedimiento",
  "tags": "479 casacion por la violacion de ley procedimiento",
  "texto": "Si la resolución impugnada hubiere violado o aplicado erróneamente la ley sustantiva, el Tribunal la casará y resolverá el caso de acuerdo con la ley y la doctrina aplicable; pero procederá de acuerdo con el artículo siguiente, aún de oficio, cuando no se hubiera observado el inciso 3 del artículo\n408."
 },
 {
  "id": "CPP-480",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 480",
  "titulo": "Anulación Total o Parcial — Casación · Procedimiento",
  "tags": "480 anulacion total o parcial casacion procedimiento",
  "texto": "En el caso del artículo 468 inciso 2, el Tribunal anulará la resolución impugnada y procederá conforme a los artículos 190 y 191."
 },
 {
  "id": "CPP-481",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 481",
  "titulo": "Rectificación — Casación · Procedimiento",
  "tags": "481 rectificacion casacion procedimiento",
  "texto": "Los errores de derecho en la fundamentación de la sentencia impugnada, que no hayan influido en la parte resolutiva, no la anularán, pero deberán ser corregidos.\nTambién lo serán los errores materiales en la designación o el cómputo de las penas."
 },
 {
  "id": "CPP-482",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 482",
  "titulo": "Libertad del Imputado, Cuando por efecto de la sentencia deba cesar la detención del imputado, el Tribunal Superior ordenará directamente la libertad — Casación · Procedimiento",
  "tags": "482 libertad del imputado, cuando por efecto de la sentencia deba cesar detencion el tribunal superior ordenara directamente casacion procedimiento",
  "texto": "Libertad del Imputado, Cuando por efecto de la sentencia deba cesar la detención del imputado, el Tribunal Superior ordenará directamente la libertad."
 },
 {
  "id": "CPP-483",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 483",
  "titulo": "Procedencia — Incostitucionalidad",
  "tags": "483 procedencia incostitucionalidad",
  "texto": "El recurso de inconstitucionalidad podrá interponerse contra las sentencias definitivas o autos mencionados en el artículo 469, cuando se cuestione la constitucionalidad de una ley, por la Constitución de la Provincia, y la sentencia o el auto fuere contrario a las pretensiones del recurrente."
 },
 {
  "id": "CPP-484",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 484",
  "titulo": "Procedimiento — Incostitucionalidad",
  "tags": "484 procedimiento incostitucionalidad",
  "texto": "Serán aplicables a este recurso las disposiciones del capítulo anterior relativas al procedimiento y forma de dictar sentencia."
 },
 {
  "id": "CPP-485",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 485",
  "titulo": "Porcedencia — Queja",
  "tags": "485 porcedencia queja",
  "texto": "Cuando sea denegado indebidamente un recurso que procediere ante otro Tribunal, el recurrente podrá presentare en queja ante éste, a fin de que lo declare mal denegado."
 },
 {
  "id": "CPP-486",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 486",
  "titulo": "Trámite — Queja",
  "tags": "486 tramite queja",
  "texto": "La queja se interpondrá por escrito en el término de dos o cuatro días -según que los Tribunales actuantes residan o no en la misma ciudaddesde que la resolución denegatoria fue notificada.\nCuando sea necesario, el Tribunal de Alzada podrá requerir el expediente, que devolverá sin tardanza."
 },
 {
  "id": "CPP-487",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 487",
  "titulo": "Resolución — Queja",
  "tags": "487 resolucion queja",
  "texto": "El Tribunal se pronunciará por auto en un plazo no mayor de cinco días, a contar desde la interposición o de la recepción del expediente."
 },
 {
  "id": "CPP-488",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 488",
  "titulo": "Efectos — Queja",
  "tags": "488 efectos queja",
  "texto": "Si la queja fuere deshechada, las actuaciones serán devueltas sin más trámite el Tribunal de origen.\nEn caso contrario se concederá el recurso y se requerirán las actuaciones a fin de emplazar a las partes y proceder según corresponda."
 },
 {
  "id": "CPP-489",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 489",
  "titulo": "Motivos — Revisión",
  "tags": "489 motivos revision",
  "texto": "El recuros de revisión procederá en todo tiempo y en favor del condenado, contra la sentencia firme:\n1) Si los hechos establecidos como fundamento de la condena fueren inconciliables con los fijados por otra sentencia penal irrevocable.\n2) Cuando el sentencia impugnada se hubiera fundado en prueba documental o testifical, cuya falsedad se hubiere declarado en fallo posterior irrevocable.\n3) Si la sentencia condenatoria hubiera sido pronunciada a consecuencia de prevaricato, cohecho, violencia u otra maquinación fraudulenta, cuya existencia se hubiese declarado en fallo posterior irrevocable.\n4) Cuando después de la condena sobrevengan nuevos hechos o elementos de prueba, que solos o unidos a los ya examinados en el proceso, hagan evidente que el hecho no existió, que el condenado no lo cometió, o que el hecho cometido encuadra en una norma penal más favorable.\n5) Si la sentencia se funda en una interpretación de la ley que sea más gravosa que la sostenida por el Tribunal Superior, al momento de la interposición del recurso.\n6) Si el consentimiento exigido por los Artículos 365 y 415, no hubiese sido libremente prestado por el condenado."
 },
 {
  "id": "CPP-490",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 490",
  "titulo": "Límite — Revisión",
  "tags": "490 limite revision",
  "texto": "El recurso deberá tender siempre a demostrar la inexistencia del hecho, que el condenado no lo cometió, o que falta totalmente la prueba en que se basó la condena, salvo que se funde en el inciso 4 último o en el inciso 5 del artículo anterior."
 },
 {
  "id": "CPP-491",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 491",
  "titulo": "QUIENES PODRÁN DEDUCIRLO: Podrán deducir el recurso de revisión:\n1) El condenado; si fuere incapaz, sus representantes legales; si hubiera fallecido o estuviera ausente con presunción de fallecimiento; su cónyuge, ascendientes, descendientes o hermanos.\n2) El Ministerio público — Revisión",
  "tags": "491 quienes podran deducirlo: deducir el recurso de revision: 1) condenado; si fuere incapaz, sus representantes legales; hubiera fallecido o estuviera ausente con presuncion fallecimiento; su conyuge, ascendientes, descendientes hermanos. 2) ministerio publico revision",
  "texto": "QUIENES PODRÁN DEDUCIRLO: Podrán deducir el recurso de revisión:\n1) El condenado; si fuere incapaz, sus representantes legales; si hubiera fallecido o estuviera ausente con presunción de fallecimiento; su cónyuge, ascendientes, descendientes o hermanos.\n2) El Ministerio público."
 },
 {
  "id": "CPP-492",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 492",
  "titulo": "INTERPOSICIÓN — Revisión",
  "tags": "492 interposicion revision",
  "texto": "El recurso de revisión será interpuesto conforme a las causales previstas en los incisos 1, 2, 3 y 5 del artículo 489 de este Código."
 },
 {
  "id": "CPP-493",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 493",
  "titulo": "Procedimiento — Revisión",
  "tags": "493 procedimiento revision",
  "texto": "En el trámite del recurso de revisión se observarán las reglas establecidas para el de casación, en cuanto sea aplicables.\nEl Tribunal podrá disponer todas las indagaciones y diligencias que crea útiles, y delegar su ejecución en alguno de sus miembros."
 },
 {
  "id": "CPP-494",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 494",
  "titulo": "Efecto Suspensivo — Revisión",
  "tags": "494 efecto suspensivo revision",
  "texto": "Durante la tramitación del recurso, el Tribunal podrá suspender la ejecución de la sentencia recurrida y disponer la libertad del imputado, con caución o sin ella."
 },
 {
  "id": "CPP-495",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 495",
  "titulo": "Sentecia — Revisión",
  "tags": "495 sentecia revision",
  "texto": "Al pronunciarse en el recurso, el Tribunal Superior podrá anular la sentencia y remitir a nuevo juicio cuando el caso lo requiera, o dictar directamente la sentencia definitiva."
 },
 {
  "id": "CPP-496",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 496",
  "titulo": "Nuevo Juicio — Revisión",
  "tags": "496 nuevo juicio revision",
  "texto": "Si se remitiere un hecho a nuevo juicio, en éste no intervendrá ninguno de los magistrados que conocieron del anterior.\nEn el nuevo juicio no se podrá absolver por efecto de una nueva apreciación de los mismos hechos del primer proceso, con prescindencia de los motivos que hicieron admisible la revisión."
 },
 {
  "id": "CPP-497",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 497",
  "titulo": "Efectos Civiles — Revisión",
  "tags": "497 efectos civiles revision",
  "texto": "Si la sentencia fuere absolutoria, podrá ordenarse la restitución de la suma pagada en concepto de pena y de indemnización; de esta última, sólo cuando haya sido citado el actor civil."
 },
 {
  "id": "CPP-498",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 498",
  "titulo": "Reparación — Revisión",
  "tags": "498 reparacion revision",
  "texto": "La sentencia de la que resulte la inocencia de un condenado podrá decidir, a instancia de parte, sobre los daños y perjuicios causados por la condena. Estos serán reparados por el Estado siempre que aquél no haya contribuido con su dolo o culpa al error judicial. La reparación sólo podrá acordarse al condenado, o por su muerte, a sus herederos forzosos."
 },
 {
  "id": "CPP-499",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 499",
  "titulo": "Revisión Desestimada — Revisión",
  "tags": "499 revision desestimada",
  "texto": "El rechazo de un recurso de revisión no perjudicará el derecho de presentar nuevos pedidos fundados en elementos diversos.\nLas costas de un recurso desechado serán siempre a cargo de la parte que lo interponga."
 },
 {
  "id": "CPP-500",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 500",
  "titulo": "Competencia — Disposiciones generales",
  "tags": "500 competencia disposiciones generales",
  "texto": "Las sentencias condenatorias que impongan penas privativas de libertad, serán ejecutadas por la autoridad administrativa competente y conforme a la Ley Penitenciaria Nacional.\nEl Tribunal que las impuso será el Juez de la causa a que dicha ley se refiere.\nLas demás resoluciones judiciales no comprendidas en el párrafo anterior, serán ejecutadas, salvo las excepciones expresas de la ley, por el Tribunal que las dictó.\nDurante la ejecución el Tribunal tendrá competencia para resolver todas las cuestiones o incidentes que se susciten, y hará las comunicaciones que por ley corresponda."
 },
 {
  "id": "CPP-501",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 501",
  "titulo": "Delegación — Disposiciones generales",
  "tags": "501 delegacion disposiciones generales",
  "texto": "El Tribunal de ejecución podrá comisionar a un Juez para que practique alguna diligencia necesaria."
 },
 {
  "id": "CPP-502",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 502",
  "titulo": "INCIDENTE DE EJECUCIÓN — Disposiciones generales",
  "tags": "502 incidente de ejecucion disposiciones generales",
  "texto": "Los incidentes que se susciten durante la ejecución de la pena podrán ser planteados por el condenado, por su defensor o por el Ministerio Público Fiscal.\nLa víctima deberá ser notificada y podrá formular observaciones por escrito únicamente en aquellos incidentes cuya resolución pudiere afectar de modo directo su seguridad, su integridad o las medidas de protección dispuestas a su favor, conforme lo establezca este Código. Dicha presentación será considerada por el Juez de Ejecución al valorar los riesgos y condiciones de cumplimiento.\nLos incidentes serán resueltos por el Juez de Ejecución, previa vista al Ministerio Público Fiscal y a la defensa del condenado y, cuando correspondiere, en los términos del segundo párrafo, con intervención de la víctima, dentro del término de cinco (5) días. Se proveerá en todos los casos a la defensa técnica del condenado conforme a lo dispuesto en el artículo 121 de este Código.\nContra el auto que resuelva el incidente sólo procederá el recurso de casación, el que no suspenderá el trámite de la ejecución, salvo que así lo disponga el Tribunal.\nIgual trámite se seguirá en los demás supuestos previstos en este Código."
 },
 {
  "id": "CPP-503",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 503",
  "titulo": "Sentencia Absolutoria — Disposiciones generales",
  "tags": "503 sentencia absolutoria disposiciones generales",
  "texto": "Cuando la sentencia sea absolutoria, el Tribunal dispondrá inmediatamente la libertad del imputado que estuviere preso y la cesación de las restricciones cautelares impuestas, aunque aquélla fuere recurrible."
 },
 {
  "id": "CPP-504",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 504",
  "titulo": "Computos — Ejecución penal · Penas",
  "tags": "504 computos ejecucion penal penas",
  "texto": "El Juez o el Presidente del Tribunal practicará el computo de la pena, fijando la fecha de su vencimiento o su monto. Se notifica el decreto respectivo al condenado y a su defensor, y al Ministerio Público, quienes podrán observarlo dentro de los tres días.\nSi no se dedujera oposición en término, el cómputo quedará aprobado y la sentencia será ejecutada inmediatamente. En caso contrario se procederá conforme a lo dispuesto por el artículo 502.\nEl mismo trámite se seguirá cuando el cómputo deba ser rectificado."
 },
 {
  "id": "CPP-505",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 505",
  "titulo": "Pena Privativa de la Libertad — Ejecución penal · Penas",
  "tags": "505 pena privativa de la libertad ejecucion penal penas",
  "texto": "Cuando el condenado a pena privativa de la libertad no estuviere preso, el Tribunal que le impusto la condena ordenará su captura, salvo que aquélla no exceda de seis meses de prisión y no exista sospecha de fuga.\nEn esta caso, se notificará al condenado para que se constituya detenido dentro de los cinco días.\nSi el condenado estuviere privado, de su libertad, en el plazo de veinte días a partir de que queda firme la sentencia condenatoria, el Tribunal comunicará la resolución a la autoridad administrativa competente a cuyo fin remitirá testimonio de aquélla, además del cómputo de la pena. En el plazo de diez días a partir de la recepción de la comunicación y sus recaudos, la referida autoridad efectuará el traslado del condenado al establecimiento penitenciario que ella determine para el cumplimineto de la pena, conforme al régimen de ejecución previsto por la Ley Penitenciaria Nacional."
 },
 {
  "id": "CPP-506",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 506",
  "titulo": "Suspensión — Ejecución penal · Penas",
  "tags": "506 suspension ejecucion penal penas",
  "texto": "La ejecución de una pena privativa de la libertad podrá ser diferida en los siguientes casos:\n1) Cuando deba cumplirla una mujer embarazada o que tenga un hijo menor de seis meses.\n2) Si el condenado se encontrare gravemente enfermo y la inmediata ejecución pusiera en peligro su vida, según el dictamen de peritos designados de oficio.\nCuando cesen estas condiciones, la sentencia se ejecutará de inmediato."
 },
 {
  "id": "CPP-507",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 507",
  "titulo": "Enfermos — Ejecución penal · Penas",
  "tags": "507 enfermos ejecucion penal penas",
  "texto": "Si durante la ejecución de la pena privativa de la libertad, el condenado sufriere enfermedad que no pudiere ser atendida en la cárcel, el Tribunal dispondrá, previos los informes médicos necesarios, la internación del enfermo en un establecimiento adecuado, salvo que ésto importare grave peligro de fuga."
 },
 {
  "id": "CPP-508",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 508",
  "titulo": "Inhabilitación Accesoria — Ejecución penal · Penas",
  "tags": "508 inhabilitacion accesoria ejecucion penal penas",
  "texto": "Cuando la pena privativa de la libertad importe la accesoria que establece el artículo 12 del Código Penal, el Tribunal ordenará las inscripciones y anotaciones que correspondan."
 },
 {
  "id": "CPP-509",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 509",
  "titulo": "Inhabilitación Absoluta — Ejecución penal · Penas",
  "tags": "509 inhabilitacion absoluta ejecucion penal penas",
  "texto": "La parte resolutiva de la sentencia que condene a inhabilitación absoluta se hará publicar en el Boletín Oficial, y se cursarán las comunicaciones a la Junta Electoral y a las Reparticiones o Poderes que correspondan, según el caso."
 },
 {
  "id": "CPP-510",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 510",
  "titulo": "Inhabilitación Especial — Ejecución penal · Penas",
  "tags": "510 inhabilitacion especial ejecucion penal penas",
  "texto": "Cuando la sentencia imponga inhabilitación especial, se harán las comunicaciones pertinentes."
 },
 {
  "id": "CPP-511",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 511",
  "titulo": "Pena de Multa — Ejecución penal · Penas",
  "tags": "511 pena de multa ejecucion penal penas",
  "texto": "La multa será abonada en papel sellado dentro de los diez días desde que la sentencia quede firme.\nVencido este término, el Tribunal procederá con arreglo a los artículos 21 y 22 del Código Penal.\nLa sentencia se ejecutará a iniciativa del Ministerio Público, por el procedimiento que a ese fin establece el Código de Procedimiento Civil y Comercial."
 },
 {
  "id": "CPP-512",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 512",
  "titulo": "PRISIÓN DOMICILIARIA — Ejecución penal · Penas",
  "tags": "512 prision domiciliaria ejecucion penal penas",
  "texto": "La prisión domiciliaria se cumplirá bajo la vigilancia de la autoridad penitenciaria provincial, a la que se impartirán las órdenes necesarias.\nAntes de disponerse la prisión domiciliaria de un condenado, el Juez de Ejecución deberá notificar a la víctima del delito acerca de la solicitud o de la posibilidad de concesión del beneficio.\nLa víctima podrá, dentro del plazo de cinco (5) días, formular observaciones respecto de la procedencia del beneficio.\nEn caso de concederse la prisión domiciliaria, el Juez de Ejecución deberá considerar la imposición de condiciones y medidas de resguardo adecuadas para asegurar que el penado no perturbe ni amenace a la víctima, tales como prohibiciones de acercamiento, vigilancia electrónica, restricción de comunicaciones u otras que resulten pertinentes.\nDel mismo modo se procederá en el caso previsto en el artículo 286 de este Código.\nSi el detenido quebrantare la medida, el Tribunal ordenará su captura para su cumplimiento en el establecimiento que corresponda."
 },
 {
  "id": "CPP-513",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 513",
  "titulo": "Revocación de Condena Condicional — Ejecución penal · Penas",
  "tags": "513 revocacion de condena condicional ejecucion penal penas",
  "texto": "La revocación de la condena de ejecución condicional será dispuesta por el Tribunal que la impuso, salvo que proceda la acumulación de penas; en este caso, podrá ordenarla el que determine la pena única."
 },
 {
  "id": "CPP-514",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 514",
  "titulo": "Modificación de la Pena Impuesta — Ejecución penal · Penas",
  "tags": "514 modificacion de la pena impuesta ejecucion penal penas",
  "texto": "Cuando deba quedar sin efecto o modificarse la pena impuesta, o las condiciones de su cumplimiento por haber entrado en vigencia una ley más benigna o en virtud de otra razón legal, el Tribunal de la ejecución aplicará dicha ley de oficio, a solicitud del interesado o del Ministerio Público.\nEl incidente se tramitará conforme al artículo 502 aunque la cuestión fuere provocada de oficio."
 },
 {
  "id": "CPP-515",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 515",
  "titulo": "SOLICITUD DE LIBERTAD CONDICIONAL — Ejecución penal · Libertad condicional",
  "tags": "515 solicitud de libertad condicional ejecucion penal",
  "texto": "La solicitud de libertad condicional formulada por el condenado será cursada por intermedio del organismo administrativo competente. El condenado podrá elegir un defensor.\nPresentada la solicitud, el Juez de Ejecución deberá notificar a la víctima del delito acerca del pedido formulado.\nLa víctima podrá, dentro del plazo de cinco (5) días, expresar observaciones respecto de la procedencia del beneficio solicitado, las que serán ponderadas por el Juez junto con los restantes elementos jurídicamente relevantes del caso, en particular al momento de fijar reglas de conducta y medidas de protección.\nEl Juez de Ejecución podrá, de oficio o a petición de la víctima, convocar a una audiencia con su participación antes de resolver, cuando lo estime necesario para una adecuada valoración del caso.\nEn caso de concederse la libertad condicional, el Juez de Ejecución fijará las reglas de conducta y demás condiciones previstas en la ley, pudiendo disponer además medidas específicas de protección hacia la víctima que resulten razonables.\nLa resolución que conceda o deniegue la libertad condicional será notificada a la víctima en forma inmediata."
 },
 {
  "id": "CPP-516",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 516",
  "titulo": "Cómputo y Antecedentes — Ejecución penal · Libertad condicional",
  "tags": "516 computo y antecedentes ejecucion penal libertad condicional",
  "texto": "Presentada la instancia, el Juez o el Presidente del Tribunal requerirán informe del Secretario sobre el tiempo de condena complido por el solicitante y sus antecedentes. En caso necesario se librará oficio al Registro Nacional de Reincidencia y los exhorto pertinentes."
 },
 {
  "id": "CPP-517",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 517",
  "titulo": "Informe y Dictamen — Ejecución penal · Libertad condicional",
  "tags": "517 informe y dictamen ejecucion penal libertad condicional",
  "texto": "La solicitud de libertad condicional deberá ser acompañada de un informe sobre el tiempo cumplido de condena y lo previsto por el artículo 13 de Código Penal, y del dictamen sobre la calificación de concepto (artículo 53, Ley Penitenciaria Nacional), producido por el organismo administrativo competente. En caso de omisión de esto recaudos, el Tribunal deberá requerirlos antes de resolver respecto a la solicitud. A tal efecto fijará un plazo de hasta cinco días."
 },
 {
  "id": "CPP-518",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 518",
  "titulo": "Informe y Dictamen — Ejecución penal · Libertad condicional",
  "tags": "518 informe y dictamen ejecucion penal libertad condicional",
  "texto": "La solicitud de libertad condicional deberá ser acompañada de un informe sobre el tiempo cumplido de condena y lo previsto por el artículo 13 de Código Penal, y del dictamen sobre la calificación de concepto (artículo 53, Ley Penitenciaria Nacional), producido por el organismo administrativo competente. En caso de omisión de esto recaudos, el Tribunal deberá requerirlos antes de resolver respecto a la solicitud. A tal efecto fijará un plazo de hasta cinco días."
 },
 {
  "id": "CPP-519",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 519",
  "titulo": "Patronato — Ejecución penal · Libertad condicional",
  "tags": "519 patronato ejecucion penal libertad condicional",
  "texto": "Durante la libertad condicional el liberado estará sometido al cuidado del instituto respectivo, al que se le comunicará la libertad y se le remitirá copia del auto que la ordenó."
 },
 {
  "id": "CPP-520",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 520",
  "titulo": "Incumplimiento — Ejecución penal · Libertad condicional",
  "tags": "520 incumplimiento ejecucion penal libertad condicional",
  "texto": "La revocatoria de la libertad condicional (C.P. 15) podrá efectuarse de oficio o a solicitud del Ministerio Público o del Patronato.\nEn todo caso, el libertado será oído y se le admitirán pruebas, procediéndose en la forma prescripta por el artículo 502.\nSi el Tribunal lo estimare necesario, el liberado será detenido preventivamente hasta que se resuelva la incidencia."
 },
 {
  "id": "CPP-521",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 521",
  "titulo": "Vigilancia — Ejecución penal · Medidas de seguridad y tutelares",
  "tags": "521 vigilancia ejecucion penal medidas de seguridad y tutelares",
  "texto": "La ejecución provisional o definitiva de una medida de seguridad será vigilada por el Tribunal que la dictó, cuyas decisiones serán obedecidas por las autoridades del establecimiento en que la misma se cumpla."
 },
 {
  "id": "CPP-522",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 522",
  "titulo": "Instrucciones — Ejecución penal · Medidas de seguridad y tutelares",
  "tags": "522 instrucciones ejecucion penal medidas de seguridad y tutelares",
  "texto": "Cuando disponga la ejecución de una medida de seguridad, el Tribunal impartirá las instrucciones necesarias a la autoridad o al encargado de ejecutarla y fijará los plazos en que deberá informársele acerca del estado de la persona sometida a la medida o sobre cualquier otra circunstancia de interés.\nDichas instrucciones podrán ser modificadas en el curso de la ejecución, según sea necesario, incluso a requerimiento de la autoridad administrativa.\nContra estas resoluciones no habrá recurso alguno."
 },
 {
  "id": "CPP-523",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 523",
  "titulo": "Internación de Anormales — Ejecución penal · Medidas de seguridad y tutelares",
  "tags": "523 internacion de anormales ejecucion penal medidas seguridad y tutelares",
  "texto": "El Tribunal ordenará especialmente la observación psiquiátrica del sujeto, cuando disponga la aplicación de la medida que prevé el artículo 34 inciso 1 del Código Penal."
 },
 {
  "id": "CPP-524",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 524",
  "titulo": "Colocación de Menores — Ejecución penal · Medidas de seguridad y tutelares",
  "tags": "524 colocacion de menores ejecucion penal medidas seguridad y tutelares",
  "texto": "Cuando se hubiere dispuesto la colocación privada de un menor, el encargado de su cuidado o la autoridad del establecimiento en que se encuentre, tendrá la obligación de facilitar la vigilancia dispuesta por el Consejo Provincial de Protección al Menor.\nEl incumplimiento de este deber podrá ser corregido a pedido del Consejo, con multa de hasta 50 jus (Ley Pcial. 7.269) o arresto de hasta cinco días."
 },
 {
  "id": "CPP-525",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 525",
  "titulo": "Colocación de Menores — Ejecución penal · Medidas de seguridad y tutelares",
  "tags": "525 colocacion de menores ejecucion penal medidas seguridad y tutelares",
  "texto": "Cuando se hubiere dispuesto la colocación privada de un menor, el encargado de su cuidado o la autoridad del establecimiento en que se encuentre, tendrá la obligación de facilitar la vigilancia dispuesta por el Consejo Provincial de Protección al Menor.\nEl incumplimiento de este deber podrá ser corregido a pedido del Consejo, con multa de hasta 50 jus (Ley Pcial. 7.269) o arresto de hasta cinco días."
 },
 {
  "id": "CPP-526",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 526",
  "titulo": "Solicitud y Competencia — Ejecución penal · Restitución y rehabilitación",
  "tags": "526 solicitud y competencia ejecucion penal restitucion rehabilitacion",
  "texto": "Cuando se cumplan las condiciones prescriptas por el artículo 20 ter del Código Penal, el condenado a inhabilitación absoluta o relativa podrá solicitar al Tribunal que la ejecutó, personalmente o mediante un abogado defensor, que se lo restituya en el uso y goce de los derechos y capacidades de que fue privado, o su rehabilitación.\nCon el escrito deberá presentar copia auténtica de la sentencia respectiva y ofrecer una prueba de dichas condiciones, bajo pena de inadmisibilidad."
 },
 {
  "id": "CPP-527",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 527",
  "titulo": "Prueba e Instrucción — Ejecución penal · Restitución y rehabilitación",
  "tags": "527 prueba e instruccion ejecucion penal restitucion y rehabilitacion",
  "texto": "Además de ordenar la inmediata recepción de la prueba ofrecida, el Tribunal podrá ordenar la instrucción que estime oportuna. A tales fines podrá actuar un Vocal de la Cámara, librarse las comunicaciones necesarias o encomendarse información a la Policía Judicial."
 },
 {
  "id": "CPP-528",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 528",
  "titulo": "Vista y Decisión — Ejecución penal · Restitución y rehabilitación",
  "tags": "528 vista y decision ejecucion penal restitucion rehabilitacion",
  "texto": "Practicada la investigación y previa vista al Ministerio Público y al interesado, el Tribunal resolverá por auto. Contra éste sólo procederá de casación."
 },
 {
  "id": "CPP-529",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 529",
  "titulo": "Efectos — Ejecución penal · Restitución y rehabilitación",
  "tags": "529 efectos ejecucion penal restitucion y rehabilitacion",
  "texto": "Si la restitución de la rehabilitación fuere concedida, se harán las anotaciones y comunicaciones necesarias para dejar sin efecto la sanción."
 },
 {
  "id": "CPP-530",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 530",
  "titulo": "Competencia — Ejecución civil · Condenas pecuniarias",
  "tags": "530 competencia ejecucion civil condenas pecuniarias",
  "texto": "La sentencia que condene a restitución, indemización o reparación de daños, o al pago de costas, cuando no sea inmediatamente ejecutada o no pueda serlo por simple orden del Tribunal que la dictó, se ejecutará por el interesado ante el Juez Civil que corresponda con arreglo al Código de Procedimiento Civil y Comercial."
 },
 {
  "id": "CPP-531",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 531",
  "titulo": "Sanciones Disciplinarias — Ejecución civil · Condenas pecuniarias",
  "tags": "531 sanciones disciplinarias ejecucion civil condenas pecuniarias",
  "texto": "El Procurador del Tesoro ejecutará las penas pecuniarias de carácter disciplinario, a favor del Fisco, en la forma establecida por el artículo anterior."
 },
 {
  "id": "CPP-532",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 532",
  "titulo": "Embargo o Inhibición de Oficio — Ejecución civil · Garantías",
  "tags": "532 embargo o inhibicion de oficio ejecucion civil garantias",
  "texto": "El Tribunal, de oficio o a pedido del Ministerio Fiscal, podrá ordenar el embargo de bienes del imputado en cantidad suficiente para garantizar la pena pecuniaria, las costas y la indemnización civil.\nSi el imputado no tuviere bienes o lo embargado fuere insuficiente, se podrá disponer la inhibición."
 },
 {
  "id": "CPP-533",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 533",
  "titulo": "Embargo a Pedido de Parte — Ejecución civil · Garantías",
  "tags": "533 embargo a pedido de parte ejecucion civil garantias",
  "texto": "El actor civil podrá pedir el embargo de bienes del imputado y del demandado civil, a fin de garantizar el pago de la indemnización que pudiera ordenarse."
 },
 {
  "id": "CPP-534",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 534",
  "titulo": "Otras Medidas Cautelares — Ejecución civil · Garantías",
  "tags": "534 otras medidas cautelares ejecucion civil garantias",
  "texto": "El Tribunal, de oficio o a pedido del Ministerio Fiscal o del actor civil, podrá ordenar cualquier otra medida cautelar."
 },
 {
  "id": "CPP-535",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 535",
  "titulo": "Remisión — Ejecución civil · Garantías",
  "tags": "535 remision ejecucion civil garantias",
  "texto": "Serán de aplicación las normas del Código de Procedimiento Civil y Comercial, en todo lo referente a embargos y otras medidas cautelares, salvo lo dispuesto en este Capítulo."
 },
 {
  "id": "CPP-536",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 536",
  "titulo": "Depósito — Ejecución civil · Garantías",
  "tags": "536 deposito ejecucion civil garantias",
  "texto": "Para la conservación, seguridad y custodia de los bienes embargados, el Tribunal designará depositario, quien los recibirá bajo inventario y firmará la diligencia de constitución del depósito; en ella se hará constar que se le hizo saber la responsabilidad que contrae.\nLos fondos públicos, los títulos de crédito, el dinero y las alhajas se depositarán en un Banco Oficial."
 },
 {
  "id": "CPP-537",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 537",
  "titulo": "Administración — Ejecución civil · Garantías",
  "tags": "537 administracion ejecucion civil garantias",
  "texto": "Si la naturaleza de los bienes embargados lo hiciere necesario se dispondrá la forma de su administración y la intervención que en ella tendrá el embargo.\nPodrá nombrarse interventor o administrador."
 },
 {
  "id": "CPP-538",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 538",
  "titulo": "Honorarios — Ejecución civil · Garantías",
  "tags": "538 honorarios ejecucion civil garantias",
  "texto": "El depositario, el interventor y el administrador tendrán derecho a cobrar honorarios, que regulará el Tribunal."
 },
 {
  "id": "CPP-539",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 539",
  "titulo": "Variación del Embargo — Ejecución civil · Garantías",
  "tags": "539 variacion del embargo ejecucion civil garantias",
  "texto": "Durante el curso de proceso el embargo podrá ser levantado, reducido o ampliado."
 },
 {
  "id": "CPP-540",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 540",
  "titulo": "Actuaciones — Ejecución civil · Garantías",
  "tags": "540 actuaciones ejecucion civil garantias",
  "texto": "Las diligencias sobre embargos y fianzas se tramitarán por cuerda separada."
 },
 {
  "id": "CPP-541",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 541",
  "titulo": "Tercerías — Ejecución civil · Garantías",
  "tags": "541 tercerias ejecucion civil garantias",
  "texto": "Las tercerías serán sustanciadas en la forma establecida por el Código de Procedimiento Civil y Comercial."
 },
 {
  "id": "CPP-542",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 542",
  "titulo": "Objetos Confiscados — Ejecución civil · Restitución de objetos secuestrados",
  "tags": "542 objetos confiscados ejecucion civil restitucion de secuestrados",
  "texto": "Cuando la sentencia importe confiscación de algún objeto, a éste se le dará el destino que corresponda según su naturaleza."
 },
 {
  "id": "CPP-543",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 543",
  "titulo": "Cosas Secuestradas — Ejecución civil · Restitución de objetos secuestrados",
  "tags": "543 cosas secuestradas ejecucion civil restitucion de objetos secuestrados",
  "texto": "Restitución y Retención. Las cosas secuestradas que no estuvieren sujetas a confiscación, restitución o embargo serán devueltas a quien se le secuestraron.\nSi hubieran sido entregadas en depósito antes de la sentencia, se notificará al depositario la entrega definitiva.\nLas cosas secuestradas de propiedad del condenado podrán ser retenidas en garantía de las costas del proceso y de la responsabilidad pecuniaria impuesta."
 },
 {
  "id": "CPP-544",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 544",
  "titulo": "Controversia — Ejecución civil · Restitución de objetos secuestrados",
  "tags": "544 controversia ejecucion civil restitucion de objetos secuestrados",
  "texto": "Si se suscitare controversia sobre la restitución o la forma de ella, se dispondrá que los interesados ocurran a la jurisdicción civil."
 },
 {
  "id": "CPP-545",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 545",
  "titulo": "Objetos no reclamados y/o decomisados — Ejecución civil · Restitución de objetos secuestrados",
  "tags": "545 objetos no reclamados y/o decomisados ejecucion civil restitucion de secuestrados",
  "texto": "Cuando después de un (1) año de concluido el proceso nadie acreditare tener derecho a la restitución de cosas que no se secuestraron de poder de persona determinada o en aquellos bienes que ya contaren con sentencia de decomiso firme -artículo 23 del Código Penal-, se procederá en la forma establecida en la Ley Nº 7972 y sus modificatorias, salvo en el caso que se disponga su subasta la que se hará por intermedio del Tribunal Superior de Justicia y en la forma que éste establezca."
 },
 {
  "id": "CPP-546",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 546",
  "titulo": "Rectificación — Ejecución civil · Sentencia declarativa de responsabilidad",
  "tags": "546 rectificacion ejecucion civil sentencia declarativa de responsabilidad",
  "texto": "Cuando una sentencia declare falso un instrumento público, el Tribunal que la dictó ordenará que el acto sea reconstituido, suprimido o reformado."
 },
 {
  "id": "CPP-547",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 547",
  "titulo": "Documento Archivado — Ejecución civil · Sentencia declarativa de responsabilidad",
  "tags": "547 documento archivado ejecucion civil sentencia declarativa de responsabilidad",
  "texto": "Si el instrumento hubiera sido extraído de un archiva, será restituido a él, con nota marginal en cada página, y se agregará copia de la sentencia que hubiese establecido la falsedad total o parcial."
 },
 {
  "id": "CPP-548",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 548",
  "titulo": "Documento Protocolizado — Ejecución civil · Sentencia declarativa de responsabilidad",
  "tags": "548 documento protocolizado ejecucion civil sentencia declarativa de responsabilidad",
  "texto": "Si se tratare de un documento protocolizado, la declaración hecha en la sentencia se anotará al margen de la matriz, en los testimonios que se hubieren preguntado y en el registro respectivos."
 },
 {
  "id": "CPP-549",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 549",
  "titulo": "Anticipación — Costas",
  "tags": "549 anticipacion costas",
  "texto": "En todo proceso, el Estado anticipará los gastos con relación al imputado y a las demás partes que gozaren del beneficio de probreza."
 },
 {
  "id": "CPP-550",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 550",
  "titulo": "Resolución Necesaria — Costas",
  "tags": "550 resolucion necesaria costas",
  "texto": "Toda resolución que ponga término a la causa o a un incidente, deberá resolver sobre el pago de las costas procesales y a cargo de quien corresponder."
 },
 {
  "id": "CPP-551",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 551",
  "titulo": "IMPOSICION — Costas",
  "tags": "551 imposicion costas",
  "texto": "Las costas serán a cargo del condenado pero el Tribunal podrá eximirlo total o parcialmente, cuando hubiera tenido razón plausible para litigar. En materia civil las costas se regirán por lo dispuesto en los Artículos 130, 132, 133 y 134 del Código de Procedimiento Civil y Comercial."
 },
 {
  "id": "CPP-552",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 552",
  "titulo": "Personas Exentas — Costas",
  "tags": "552 personas exentas costas",
  "texto": "Los representantes del Ministerio Público, los abongados y mandatarios que intervengan en el proceso, no podrán ser condenados en costas, salvo los casos en que especialmente se disponga lo contrario y sin perjuicio de la responsabilidad penal o disciplinaria en que incurran."
 },
 {
  "id": "CPP-553",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 553",
  "titulo": "Contenido — Costas",
  "tags": "553 contenido costas",
  "texto": "Las costas consistirán:\n1) En la reposición del papel sellado o reintegro del empleado en el expediente.\n2) En el pago de los demás impuestos que correspondan, de los honorarios devengados en el proceso y de los otros gastos que se hubieran originado durante su tramitación."
 },
 {
  "id": "CPP-554",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 554",
  "titulo": "Distribución de Costas — Costas",
  "tags": "554 distribucion de costas",
  "texto": "Cuando sean varios los condenados al pago de costas, el Tribunal fijará la parte proporcional que corresponda a cada uno, sin perjuicio de la solidaridad que establezca la ley civil.\nDISPOSICIONES TRANSITORIAS"
 },
 {
  "id": "CPP-555",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 555",
  "titulo": "Vigencia — Costas",
  "tags": "555 vigencia costas",
  "texto": "Esta ley empezará a regir a los seis meses de su publicación.\nEl Tribunal Superior de Justicia podrá ampliar este plazo por igual término si fuera indispensable."
 },
 {
  "id": "CPP-556",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 556",
  "titulo": "PROCESOS PENDIENTES — Costas",
  "tags": "556 procesos pendientes costas",
  "texto": "1) Los procesos que al entrar en vigencia este Código estuvieren radicados en los Juzgados de Instrucción, continuarán sustanciándose ante esos órganos de acuerdo a la reglamentación efectuada por el Tribunal Superior en ejercicio de la atribución conferida por el Artículo 12, inciso 24 de la Ley Orgánica del Poder Judicial, con arreglo a las disposiciones previstas para la investigación jurisdiccional, con excepción del Artículo 347 respecto del cual se mantiene la vigencia del texto suministrado por el Artículo de la ley 8452.\nLas mismas reglas se aplicarán para los sumarios de prevención radicados ante la Policía Judicial, siempre que los hechos hayan sido comunicados a los Jueces de Instrucción hasta la fecha de entrada en vigencia y se trate de delitos reprimidos con pena privativa de libertad mayor a tres años.\nRegirá para estos procesos la excepción para la acumulación prevista por el Artículo 49, inclusive para el supuesto previsto en el inciso 2 del Artículo 47.\nEn los centros judiciales en los que hubiere Fiscales Correccionales, el Fiscal General de la Provincia podrá disponer, con la conformidad del Tribunal Superior de Justicia, que actúen ante los Jueces de Instrucción en los procesos pendientes, con las atribuciones que el Código le confiere a los Fiscales de Instrucción.\nEsta disposición transitoria para procesos pendientes en los Juzgados de Instrucción tendrá vigencia hasta el día 1° de Abril de 2001. El Tribunal Superior de Justicia podrá ampliarlo fundadamente por un año más. Si al fenecimiento del plazo subsistieran procesos pendientes, por los cuales no corresponda la investigación jurisdiccional\n(Artículo 15), serán distribuidos por sorteo entre las Fiscalías de Instrucción y proseguirá con la investigación según su estado.\n2) Los procesos que estuvieren radicados en las Fiscalías de Instrucción, continuarán sustanciándose según su estado con arreglo a las disposiciones de la presente ley.\n3) Los juicios por delitos de acción privada, en los que se hubiere celebrado la audiencia de conciliación y los juicios por delitos culposos, en los que se hubiere fijado la audiencia de debate continuarán tramitándose en las Cámaras del Crimen en las que estuvieren radicados.\nEn los demás casos los procesos se distribuirán inmediatamente por sorteo entre los Juzgados Correccionales.\nEl Juez Correccional dictará decreto de avocamiento que será notificado a las partes y continuará con la substanciación del proceso según su estado."
 },
 {
  "id": "CPP-557",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 557",
  "titulo": "Validez de los Actos Anteriores — Costas",
  "tags": "557 validez de los actos anteriores costas",
  "texto": "Los actos cumplidos antes de la vigencia de este Código, de acuerdo con las normas del abrogado, conservarán plena validez."
 },
 {
  "id": "CPP-558",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 558",
  "titulo": "Jurados — Costas",
  "tags": "558 jurados costas",
  "texto": "Hasta tanto se modifique la Ley Orgánica del Poder Judicial la integración de los Tribunales con Jurados se regirá por las siguientes reglas:\n1) Para ser jurado se requiere mayoría de edad; ciudadanía en ejercicio, capacidad civil y ciclo básico completo.\n2) El Tribunal Superior de Justicia confeccionará anualmente una lista de jurados mediante sorteo realizado en audiencia pública, entre los electores inscriptos en el padrón electoral correspondiente a cada circunscripción judicial, y dictará la reglamentación respectiva, antes de la entrada en vigencia de esta Ley.\n3) Deberán inhibierse y podrán ser recusados por las mismas causales establecidas para los jueces.\n4) Serán removidos por el Tribunal Superior de Justicia por el procedimiento establecido para los Jueces de Paz, si incurrieren en algunas de las causales previstas por el artículo 154 de la Constitución Provincial, excepto el desconocimiento inexcusable del derecho.\n5) Percibirán por su intervención en el juicio el arancel que determine el Tribunal Superior de Justicia.\n6) Prestarán juramento en la forma que el Tribunal Superior de Justicia determine."
 },
 {
  "id": "CPP-559",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 559",
  "titulo": "Derogación — Costas",
  "tags": "559 derogacion costas",
  "texto": "Derogase el decreto - ley N. 5.154, ratificado por la ley 5.606; las modificaciones introducidas por las leyes 5.303, 5.859, 5.949, 5.989, 6.221, 6.504, 6.659,\n6.676, 6752, 7.139, 7.624, 7.662, 7.690, 7.904, 8.054 y toda disposición que se oponga a la presente."
 },
 {
  "id": "CPP-560",
  "cuerpo": "CPP",
  "etiqueta": "CPP Córdoba (Ley 8.123) · Art. 560",
  "titulo": "Comuníquese al Poder Ejecutivo — Costas",
  "tags": "560 comuniquese al poder ejecutivo costas",
  "texto": "Luppi - Cendoya - Cafferata Nores - Pérez. Titular del Poder Ejecutivo: Angeloz Decreto de Promulgación N. 4.502/91."
 },
 {
  "id": "LEYES-ESP-23737-24270",
  "cuerpo": "CP",
  "etiqueta": "Leyes Especiales · Ley 23.737 (Estupefacientes) y Ley 24.270 (Impedimento de contacto)",
  "titulo": "Estupefacientes (Narcomenudeo Córdoba) e Impedimento de contacto de menores",
  "tags": "23737 24270 estupefacientes drogas marihuana cocaina narcomenudeo impedimento contacto instancia privada",
  "texto": "Ley 23.737: tenencia y comercialización de estupefacientes (en Córdoba actúa FPA / Fiscalía de Lucha contra el Narcotráfico en narcomenudeo). Ley 24.270: impedir u obstruir el contacto de hijos menores con padres no convivientes (delito dependiente de instancia privada conforme Art. 72 inc. 3 CP)."
 },
 {
  "id": "CP-1",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 1",
  "titulo": "Código Penal",
  "tags": "1",
  "texto": "Este código se aplicará:\n1º.- Por delitos cometidos o cuyos efectos deban producirse en el territorio de la Nación Argentina, o en los lugares sometidos a su jurisdicción;\n2º.- Por delitos cometidos en el extranjero por agentes o empleados de autoridades argentinas en desempeño de su cargo."
 },
 {
  "id": "CP-2",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 2",
  "titulo": "Código Penal",
  "tags": "2",
  "texto": "Si la ley vigente al tiempo de cometerse el delito fuere distinta de la que exista al pronunciarse el fallo o en el tiempo intermedio, se aplicará siempre la más benigna.\nSi durante la condena se dictare una ley más benigna, la pena se limitará a la establecida por esa ley. En todos los casos del presente artículo, los efectos de la nueva ley se operarán de pleno derecho."
 },
 {
  "id": "CP-3",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 3",
  "titulo": "Código Penal",
  "tags": "3",
  "texto": "En el cómputo de la prisión preventiva se observará separadamente la ley más favorable al procesado."
 },
 {
  "id": "CP-4",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 4",
  "titulo": "Código Penal",
  "tags": "4",
  "texto": "Las disposiciones generales del presente código se aplicarán a todos los delitos previstos por leyes especiales, en cuanto éstas no dispusieran lo contrario."
 },
 {
  "id": "CP-5",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 5",
  "titulo": "De las penas",
  "tags": "5 de las penas",
  "texto": "Las penas que este Código establece son las siguientes: reclusión, prisión, multa e inhabilitación."
 },
 {
  "id": "CP-6",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 6",
  "titulo": "De las penas",
  "tags": "6 de las penas",
  "texto": "La pena de reclusión, perpetua o temporal, se cumplirá con trabajo obligatorio en los establecimientos destinados al efecto. Los recluidos podrán ser empleados en obras públicas de cualquier clase con tal que no fueren contratadas por particulares."
 },
 {
  "id": "CP-7",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 7",
  "titulo": "De las penas",
  "tags": "7 de las penas",
  "texto": "Los hombres débiles o enfermos y los mayores de sesenta años que merecieren reclusión, sufrirán la condena en prisión, no debiendo ser sometidos sino a la clase de trabajo especial que determine la dirección del establecimiento."
 },
 {
  "id": "CP-8",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 8",
  "titulo": "De las penas",
  "tags": "8 de las penas",
  "texto": "Los menores de edad y las mujeres sufrirán las condenas en establecimientos especiales."
 },
 {
  "id": "CP-9",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 9",
  "titulo": "De las penas",
  "tags": "9 de las penas",
  "texto": "La pena de prisión, perpetua o temporal, se cumplirá con trabajo obligatorio, en establecimientos distintos de los destinados a los recluidos."
 },
 {
  "id": "CP-10",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 10",
  "titulo": "De las penas",
  "tags": "10 de las penas",
  "texto": "Podrán, a criterio del juez competente, cumplir la pena de reclusión o prisión en detención domiciliaria:\na) El interno enfermo cuando la privación de la libertad en el establecimiento carcelario le impide recuperarse o tratar adecuadamente su dolencia y no correspondiere su alojamiento en un establecimiento hospitalario;\nb) El interno que padezca una enfermedad incurable en período terminal;\nc) El interno díscapacitado cuando la privación de la libertad en el establecimiento carcelario es inadecuada por su condición implicándole un trato indigno, inhumano o cruel;\nd) El interno mayor de setenta (70) años;\ne) La mujer embarazada;\nf) La madre de un niño menor de cinco (5) años o de una persona con discapacidad a su cargo.\n(Artículo sustituido por art. 4° de la Ley N° 26.472, B.O. 20/1/2009)"
 },
 {
  "id": "CP-11",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 11",
  "titulo": "De las penas",
  "tags": "11 de las penas",
  "texto": "El producto del trabajo del condenado a reclusión o prisión se aplicará simultáneamente:\n1º. A indemnizar los daños y perjuicios causados por el delito que no satisfaciera con otros recursos;\n2º. A la prestación de alimentos según el Código Civil;\n3º. A costear los gastos que causare en el establecimiento;\n4º. A formar un fondo propio, que se le entregará a su salida."
 },
 {
  "id": "CP-12",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 12",
  "titulo": "De las penas",
  "tags": "12 de las penas",
  "texto": "La reclusión y la prisión por más de tres años llevan como inherente la inhabilitación absoluta, por el tiempo de la condena, la que podrá durar hasta tres años más, si así lo resuelve el tribunal, de acuerdo con la índole del delito. Importan además la privación, mientras dure la pena, de la patria potestad, de la administración de los bienes y del derecho de disponer de ellos por actos entre vivos. El penado quedará sujeto a la curatela establecida por el Código Civil para los incapaces."
 },
 {
  "id": "CP-13",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 13",
  "titulo": "De las penas",
  "tags": "13 de las penas",
  "texto": "El condenado a reclusión o prisión perpetua que hubiere cumplido treinta y cinco (35) años de condena, el condenado a reclusión o a prisión por más de tres (3) años que hubiere cumplido los dos tercios, y el condenado a reclusión o prisión, por tres (3) años o menos, que hubiere cumplido un (1) año de reclusión u ocho (8) meses de prisión, observando con regularidad los reglamentos carcelarios, podrán obtener la libertad por resolución judicial, previo informe de la dirección del establecimiento e informe de peritos que pronostique en forma individualizada y favorable su reinserción social, bajo las siguientes condiciones:\n1º.- Residir en el lugar que determine el auto de soltura;\n2º.- Observar las reglas de inspección que fije el mismo auto, especialmente la obligación de abstenerse de consumir bebidas alcohólicas o utilizar sustancias estupefacientes;\n3º.- Adoptar en el plazo que el auto determine, oficio, arte, industria o profesión, si no tuviere medios propios de subsistencia;\n4º.- No cometer nuevos delitos;\n5º.- Someterse al cuidado de un patronato, indicado por las autoridades competentes;\n6º.- Someterse a tratamiento médico, psiquiátrico o psicológico, que acrediten su necesidad y eficacia de acuerdo al consejo de peritos.\nEstas condiciones, a las que el juez podrá añadir cualquiera de las reglas de conducta contempladas en el artículo 27 bis, regirán hasta el vencimiento de los términos de las penas temporales y hasta diez (10) años más en las perpetuas, a contar desde el día del otorgamiento de la libertad condicional.\n(Artículo sustituido por art. 1° de la Ley N° 25.892 B.O.26/5/2004)"
 },
 {
  "id": "CP-14",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 14",
  "titulo": "De las penas",
  "tags": "14 de las penas",
  "texto": "La libertad condicional no se concederá a los reincidentes. Tampoco se concederá en los casos previstos en los artículos 80 inciso 7º, 124, 142 bis, anteúltimo párrafo, 165 y 170, anteúltimo párrafo.\n(Artículo sustituido por art. 2° de la Ley N° 25.892 B.O.26/5/2004)"
 },
 {
  "id": "CP-15",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 15",
  "titulo": "De las penas",
  "tags": "15 de las penas",
  "texto": "La libertad condicional será revocada cuando el penado cometiere un nuevo delito o violare la obligación de residencia. En estos casos no se computará, en el término de la pena, el tiempo que haya durado la libertad.\nEn los casos de los incisos 2º, 3º, 5º y 6º del artículo 13, el Tribunal podrá disponer que no se compute en el término de la condena todo o parte del tiempo que hubiere durado la libertad, hasta que el condenado cumpliese con lo dispuesto en dichos incisos. (Párrafo sustituido por art. 3° de la Ley N° 25.892 B.O.26/5/2004)"
 },
 {
  "id": "CP-16",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 16",
  "titulo": "De las penas",
  "tags": "16 de las penas",
  "texto": "Transcurrido el término de la condena, o el plazo de cinco años señalado en el artículo 13 sin que la libertad condicional haya sido revocada, la pena quedará extinguida, lo mismo que la inhabilitación absoluta del artículo 12."
 },
 {
  "id": "CP-17",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 17",
  "titulo": "De las penas",
  "tags": "17 de las penas",
  "texto": "Ningún penado cuya libertad condicional haya sido revocada, podrá obtenerla nuevamente."
 },
 {
  "id": "CP-18",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 18",
  "titulo": "De las penas",
  "tags": "18 de las penas",
  "texto": "Los condenados por tribunales provinciales a reclusión o prisión por más de cinco años serán admitidos en los respectivos establecimientos nacionales. Las provincias podrán mandarlos siempre que no tuvieren establecimientos adecuados."
 },
 {
  "id": "CP-19",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 19",
  "titulo": "De las penas",
  "tags": "19 de las penas",
  "texto": "La inhabilitación absoluta importa:\n1º. La privación del empleo o cargo público que ejercía el penado aunque provenga de elección popular;\n2º. La privación del derecho electoral;\n3º. La incapacidad para obtener cargos, empleos y comisiones públicas;\n4º. La suspensión del goce de toda jubilación, pensión o retiro, civil o militar, cuyo importe será percibido por los parientes que tengan derecho a pensión.\nEl tribunal podrá disponer, por razones de carácter asistencial, que la víctima o los deudos que estaban a su cargo concurran hasta la mitad de dicho importe, o que lo perciban en su totalidad, cuando el penado no tuviere parientes con derecho a pensión, en ambos casos hasta integrar el monto de las indemnizaciones fijadas."
 },
 {
  "id": "CP-20",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 20",
  "titulo": "De las penas",
  "tags": "20 de las penas",
  "texto": "La inhabilitación especial producirá la privación del empleo, cargo, profesión o derecho sobre que recayere y la incapacidad para obtener otro del mismo género durante la condena. La inhabilitación especial para derechos políticos producirá la incapacidad de ejercer durante la condena aquellos sobre que recayere."
 },
 {
  "id": "CP-20-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 20 bis",
  "titulo": "De las penas",
  "tags": "20 bis de las penas",
  "texto": "Podrá imponerse inhabilitación especial de seis meses a diez años, aunque esa pena no esté expresamente prevista, cuando el delito cometido importe:\n1º. Incompetencia o abuso en el ejercicio de un empleo o cargo público;\n2º. Abuso en el ejercicio de la patria potestad, adopción, tutela o curatela;\n3º. Incompetencia o abuso en el desempeño de una profesión o actividad cuyo ejercicio dependa de una autorización, licencia o habilitación del poder público."
 },
 {
  "id": "CP-20-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 20 ter",
  "titulo": "De las penas",
  "tags": "20 ter de las penas",
  "texto": "El condenado a inhabilitación absoluta puede ser restituido al uso y goce de los derechos y capacidades de que fue privado, si se ha comportado correctamente durante la mitad del plazo de aquélla, o durante diez años cuando la pena fuera perpetua, y ha reparado los daños en la medida de lo posible.\nEl condenado a inhabilitación especial puede ser rehabilitado, transcurrida la mitad del plazo de ella, o cinco años cuando la pena fuere perpetua, si se ha comportado correctamente, ha remediado su incompetencia o no es de temer que incurra en nuevos abusos y, además, ha reparado los daños en la medida de lo posible.\nCuando la inhabilitación importó la pérdida de un cargo público o de una tutela o curatela, la rehabilitación no comportará la reposición en los mismos cargos.\nPara todos los efectos, en los plazos de inhabilitación no se computará el tiempo en que el inhabilitado haya estado prófugo, internado o privado de su libertad."
 },
 {
  "id": "CP-21",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 21",
  "titulo": "De las penas",
  "tags": "21 de las penas",
  "texto": "La multa obligará al reo a pagar la cantidad de dinero que determinare la sentencia, teniendo en cuenta además de las causas generales del artículo 40, la situación económica del penado.\nSi el reo no pagare la multa en el término que fije la sentencia, sufrirá prisión que no excederá de año y medio.\nEl tribunal, antes de transformar la multa en la prisión correspondiente, procurará la satisfacción de la primera, haciéndola efectiva sobre los bienes, sueldos u otras entradas del condenado. Podrá autorizarse al condenado a amortizar la pena pecuniaria, mediante el trabajo libre, siempre que se presente ocasión para ello.\nTambién se podrá autorizar al condenado a pagar la multa por cuotas. El tribunal fijará el monto y la fecha de los pagos, según la condición económica del condenado."
 },
 {
  "id": "CP-22",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 22",
  "titulo": "De las penas",
  "tags": "22 de las penas",
  "texto": "En cualquier tiempo que se satisfaciera la multa, el reo quedará en libertad.\nDel importe se descontará, de acuerdo con las reglas establecidas para el cómputo de la prisión preventiva, la parte proporcional al tiempo de detención que hubiere sufrido."
 },
 {
  "id": "CP-22-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 22 bis",
  "titulo": "De las penas",
  "tags": "22 bis de las penas",
  "texto": "Si el hecho ha sido cometido con ánimo de lucro, podrá agregarse a la pena privativa de libertad una multa, aun cuando no esté especialmente prevista o lo esté sólo en forma alternativa con aquélla. Cuando no esté prevista, la multa no podrá exceder de noventa mil pesos.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-23",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 23",
  "titulo": "De las penas",
  "tags": "23 de las penas",
  "texto": "En todos los casos en que recayese condena por delitos previstos en este Código o en leyes penales especiales, la misma decidirá el decomiso de las cosas que han servido para cometer el hecho y de las cosas o ganancias que son el producto o el provecho del delito, en favor del Estado nacional, de las provincias o de los municipios, salvo los derechos de restitución o indemnización del damnificado y de terceros.\nSi las cosas son peligrosas para la seguridad común, el comiso puede ordenarse aunque afecte a terceros, salvo el derecho de éstos, si fueren de buena fe, a ser indemnizados.\nCuando el autor o los partícipes han actuado como mandatarios de alguien o como órganos, miembros o administradores de una persona de existencia ideal, y el producto o el provecho del delito ha beneficiado al mandante o a la persona de existencia ideal, el comiso se pronunciará contra éstos.\nCuando con el producto o el provecho del delito se hubiese beneficiado un tercero a título gratuito, el comiso se pronunciará contra éste.\nSi el bien decomisado tuviere valor de uso o cultural para algún establecimiento oficial o de bien público, la autoridad nacional, provincial o municipal respectiva podrá disponer su entrega a esas entidades. Si así no fuere y tuviera valor comercial, aquélla dispondrá su enajenación. Si no tuviera valor lícito alguno, se lo destruirá.\nEn el caso de condena impuesta por alguno de los delitos previstos por los artículos 142 bis o 170 de este Código, queda comprendido entre los bienes a decomisar la cosa mueble o inmueble donde se mantuviera a la víctima privada de su libertad. Los bienes decomisados con motivo de tales delitos, según los términos del presente artículo, y el producido de las multas que se impongan, serán afectados a programas de asistencia a la víctima.\nEl juez podrá adoptar desde el inicio de las actuaciones judiciales las medidas cautelares suficientes para asegurar el decomiso del o de los inmuebles, fondos de comercio, depósitos, transportes, elementos informáticos, técnicos y de comunicación, y todo otro bien o derecho patrimonial sobre los que, por tratarse de instrumentos o efectos relacionados con el o los delitos que se investigan, el decomiso presumiblemente pueda recaer.\nEl mismo alcance podrán tener las medidas cautelares destinadas a hacer cesar la comisión del delito o sus efectos, o a evitar que se consolide su provecho o a obtaculizar la impunidad de sus partícipes. En todos los casos se deberá dejar a salvo los derechos de restitución o indemnización del damnificado y de terceros\n(Artículo sustituido por art. 1° de la Ley N° 25.815 B.O.1/12/2003)"
 },
 {
  "id": "CP-24",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 24",
  "titulo": "De las penas",
  "tags": "24 de las penas",
  "texto": "La prisión preventiva se computará así: por dos días de prisión preventiva, uno de reclusión; por un día de prisión preventiva, uno de prisión o dos de inhabilitación o la cantidad de multa que el tribunal fijase entre pesos treinta y cinco y pesos ciento setenta y cinco.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-25",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 25",
  "titulo": "De las penas",
  "tags": "25 de las penas",
  "texto": "Si durante la condena el penado se volviere loco, el tiempo de la locura se computará para el cumplimiento de la pena, sin que ello obste a lo dispuesto en el apartado tercero del inciso 1º del artículo 34."
 },
 {
  "id": "CP-26",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 26",
  "titulo": "Condenacion condicional",
  "tags": "26 condenacion condicional",
  "texto": "En los casos de primera condena a pena de prisión que no exceda de tres años, será facultad de los tribunales disponer en el mismo pronunciamiento que se deje en suspenso el cumplimiento de la pena. Esta decisión deberá ser fundada, bajo sanción de nulidad, en la personalidad moral del condenado, su actitud posterior al delito, los motivos que lo impulsaron a delinquir, la naturaleza del hecho y las demás circunstancias que demuestren la inconveniencia de aplicar efectivamente la privación de libertad. El tribunal requerirá las informaciones pertinentes para formar criterio, pudiendo las partes aportar también la prueba útil a tal efecto.\nIgual facultad tendrán los tribunales en los casos de concurso de delitos si la pena impuesta al reo no excediese los tres años de prisión.\nNo procederá la condenación condicional respecto de las penas de multa o inhabilitación."
 },
 {
  "id": "CP-27",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 27",
  "titulo": "Condenacion condicional",
  "tags": "27 condenacion condicional",
  "texto": "La condenación se tendrá como no pronunciada si dentro del término de cuatro años, contados a partir de la fecha de la sentencia firme, el condenado no cometiere un nuevo delito. Si cometiere un nuevo delito, sufrirá la pena impuesta en la primera condenación y la que le correspondiere por el segundo delito, conforme con lo dispuesto sobre acumulación de penas.\nLa suspensión podrá ser acordada por segunda vez si el nuevo delito ha sido cometido después de haber transcurrido ocho años a partir de la fecha de la primera condena firme.\nEste plazo se elevará a diez años, si ambos delitos fueran dolosos.\nEn los casos de sentencias recurridas y confirmadas, en cuanto al carácter condicional de la condena, los plazos se computarán desde la fecha del pronunciamiento originario."
 },
 {
  "id": "CP-27-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 27 bis",
  "titulo": "Condenacion condicional",
  "tags": "27 bis condenacion condicional",
  "texto": "Al suspender condicionalmente la ejecución de la pena, el Tribunal deberá disponer que, durante un plazo que fijará entre dos y cuatro años según la gravedad del delito, el condenado cumpla todas o alguna de las siguientes reglas de conducta, en tanto resulten adecuadas para prevenir la comisión de nuevos delitos:\n1. Fijar residencia y someterse al cuidado de un patronato.\n2. Abstenerse de concurrir a determinados lugares o de relacionarse con determinadas personas.\n3. Abstenerse de usar estupefacientes o de abusar de bebidas alcohólicas.\n4. Asistir a la escolaridad primaria, si no la tuviere cumplida.\n5. Realizar estudios o prácticas necesarios para su capacitación laboral o profesional.\n6. Someterse a un tratamiento médico o psicológico, previo informe que acredite su necesidad y eficacia.\n7. Adoptar oficio, arte, industria o profesión, adecuado a su capacidad.\n8. Realizar trabajos no remunerados en favor del estado o de instituciones de bien público, fuera de sus horarios habituales de trabajo.\nLas reglas podrán ser modificadas por el Tribunal según resulte conveniente al caso.\nSi el condenado no cumpliere con alguna regla, el Tribunal podrá disponer que no se compute como plazo de cumplimiento todo o parte del tiempo transcurrido hasta ese momento. Si el condenado persistiere o reiterare el incumplimiento, el Tribunal podrá revocar la condicionalidad de la condena. El condenado deberá entonces cumplir la totalidad de la pena de prisión impuesta en la sentencia.\n(Artículo incorporado por art. 1° de la Ley N° 24.316 B.O. 19/5/1994)"
 },
 {
  "id": "CP-28",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 28",
  "titulo": "Condenacion condicional",
  "tags": "28 condenacion condicional",
  "texto": "La suspensión de la pena no comprenderá la reparación de los daños causados por el delito y el pago de los gastos del juicio."
 },
 {
  "id": "CP-29",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 29",
  "titulo": "Reparacion de perjuicios",
  "tags": "29 reparacion de perjuicios",
  "texto": "La sentencia condenatoria podrá ordenar:\n1. La reposición al estado anterior a la comisión del delito, en cuanto sea posible, disponiendo a ese fin las restituciones y demás medidas necesarias.\n2. La indemnización del daño material y moral causado a la víctima, a su familia o a un tercero, fijándose el monto prudencialmente por el juez en defecto de plena prueba.\n3. El pago de las costas.\n(Artículo sustituido por art. 27 de la Ley N° 25.188 B.O. 1/11/1999.)"
 },
 {
  "id": "CP-30",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 30",
  "titulo": "Reparacion de perjuicios",
  "tags": "30 reparacion de perjuicios",
  "texto": "La obligación de indemnizar es preferente a todas las que contrajere el responsable después de cometido el delito, a la ejecución de la pena de decomiso del producto o el provecho del delito y al pago de la multa. Si los bienes del condenado no fueren suficientes para cubrir todas sus responsabilidades pecuniarias, éstas se satisfarán en el orden siguiente:\n1. La indemnización de los daños y perjuicios.\n2. El resarcimiento de los gastos del juicio.\n3. El decomiso del producto o el provecho del delito.\n4. El pago de la multa.\n(Artículo sustituido por art. 28 de la Ley N° 25.188 B.O. 1/11/1999.)"
 },
 {
  "id": "CP-31",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 31",
  "titulo": "Reparacion de perjuicios",
  "tags": "31 reparacion de perjuicios",
  "texto": "La obligación de reparar el daño es solidaria entre todos los responsables del delito."
 },
 {
  "id": "CP-32",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 32",
  "titulo": "Reparacion de perjuicios",
  "tags": "32 reparacion de perjuicios",
  "texto": "El que por título lucrativo participare de los efectos de un delito, estará obligado a la reparación hasta la cuantía en que hubiere participado."
 },
 {
  "id": "CP-33",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 33",
  "titulo": "Reparacion de perjuicios",
  "tags": "33 reparacion de perjuicios",
  "texto": "En caso de insolvencia total o parcial, se observarán las reglas siguientes:\n1º. Tratándose de condenados a reclusión o prisión, la reparación se hará en la forma determinada en el artículo 11;\n2º. Tratándose de condenados a otras penas, el tribunal señalará la parte de sus entradas o emolumentos que deban depositar periódicamente hasta el pago total."
 },
 {
  "id": "CP-34",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 34",
  "titulo": "Imputabilidad",
  "tags": "34 imputabilidad",
  "texto": "No son punibles:\n1º. El que no haya podido en el momento del hecho, ya sea por insuficiencia de sus facultades, por alteraciones morbosas de las mismas o por su estado de inconciencia, error o ignorancia de hecho no imputables, comprender la criminalidad del acto o dirigir sus acciones.\nEn caso de enajenación, el tribunal podrá ordenar la reclusión del agente en un manicomio, del que no saldrá sino por resolución judicial, con audiencia del ministerio público y previo dictamen de peritos que declaren desaparecido el peligro de que el enfermo se dañe a sí mismo o a los demás.\nEn los demás casos en que se absolviere a un procesado por las causales del presente inciso, el tribunal ordenará la reclusión del mismo en un establecimiento adecuado hasta que se comprobase la desaparición de las condiciones que le hicieren peligroso;\n2º. El que obrare violentado por fuerza física irresistible o amenazas de sufrir un mal grave e inminente;\n3º. El que causare un mal por evitar otro mayor inminente a que ha sido extraño;\n4º. El que obrare en cumplimiento de un deber o en el legítimo ejercicio de su derecho, autoridad o cargo;\n5º. El que obrare en virtud de obediencia debida;\n6º. El que obrare en defensa propia o de sus derechos, siempre que concurrieren las siguientes circunstancias:\na) Agresión ilegítima;\nb) Necesidad racional del medio empleado para impedirla o repelerla;\nc) Falta de provocación suficiente por parte del que se defiende.\nSe entenderá que concurren estas circunstancias respecto de aquel que durante la noche rechazare el escalamiento o fractura de los cercados, paredes o entradas de su casa, o departamento habitado o de sus dependencias, cualquiera que sea el daño ocasionado al agresor.\nIgualmente respecto de aquél que encontrare a un extraño dentro de su hogar, siempre que haya resistencia;\n7º. El que obrare en defensa de la persona o derechos de otro, siempre que concurran las circunstancias a) y b) del inciso anterior y caso de haber precedido provocación suficiente por parte del agredido, la de que no haya participado en ella el tercero defensor."
 },
 {
  "id": "CP-35",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 35",
  "titulo": "Imputabilidad",
  "tags": "35 imputabilidad",
  "texto": "El que hubiere excedido los límites impuestos por la Ley, por la autoridad o por la necesidad, será castigado con la pena fijada para el delito por culpa o imprudencia."
 },
 {
  "id": "CP-36",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 36",
  "titulo": "Imputabilidad",
  "tags": "36 imputabilidad",
  "texto": "Derogado."
 },
 {
  "id": "CP-37",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 37",
  "titulo": "Imputabilidad",
  "tags": "37 imputabilidad",
  "texto": "Derogado."
 },
 {
  "id": "CP-38",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 38",
  "titulo": "Imputabilidad",
  "tags": "38 imputabilidad",
  "texto": "Derogado."
 },
 {
  "id": "CP-39",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 39",
  "titulo": "Imputabilidad",
  "tags": "39 imputabilidad",
  "texto": "Derogado."
 },
 {
  "id": "CP-40",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 40",
  "titulo": "Imputabilidad",
  "tags": "40 imputabilidad",
  "texto": "En las penas divisibles por razón de tiempo o de cantidad, los tribunales fijarán la condenación de acuerdo con las circunstancias atenuantes o agravantes particulares a cada caso y de conformidad a las reglas del artículo siguiente."
 },
 {
  "id": "CP-41",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 41",
  "titulo": "Imputabilidad",
  "tags": "41 imputabilidad",
  "texto": "A los efectos del artículo anterior, se tendrá en cuenta:\n1º. La naturaleza de la acción y de los medios empleados para ejecutarla y la extensión del daño y del peligro causados;\n2º. La edad, la educación, las costumbres y la conducta precedente del sujeto, la calidad de los motivos que lo determinaron a delinquir, especialmente la miseria o la dificultad de ganarse el sustento propio necesario y el de los suyos, la participación que haya tomado en el hecho, las reincidencias en que hubiera incurrido y los demás antecedentes y condiciones personales, así como los vínculos personales, la calidad de las personas y las circunstancias de tiempo, lugar, modo y ocasión que demuestren su mayor o menor peligrosidad. El juez deberá tomar conocimiento directo y de visu del sujeto, de la víctima y de las circunstancias del hecho en la medida requerida para cada caso."
 },
 {
  "id": "CP-41-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 41 bis",
  "titulo": "Imputabilidad",
  "tags": "41 bis imputabilidad",
  "texto": "Cuando alguno de los delitos previstos en este Código se cometiera con violencia o intimidación contra las personas mediante el empleo de un arma de fuego la escala penal prevista para el delito de que se trate se elevará en un tercio en su mínimo y en su máximo, sin que ésta pueda exceder el máximo legal de la especie de pena que corresponda.\nEste agravante no será aplicable cuando la circunstancia mencionada en ella ya se encuentre contemplada como elemento constitutivo o calificante del delito de que se trate.\n(Artículo incorporado por art. 1° de la Ley N° 25.297 B.O. 22/9/2000)"
 },
 {
  "id": "CP-41-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 41 ter",
  "titulo": "Imputabilidad",
  "tags": "41 ter imputabilidad",
  "texto": "Las escalas penales previstas en los artículos 142 bis, 145 bis, 145 ter y 170 de este Código podrán reducirse en un tercio del máximo y en la mitad del mínimo respecto de los partícipes o encubridores que, durante la sustanciación del proceso o antes de su iniciación, proporcionen información que permita conocer el lugar donde la víctima se encuentra privada de su libertad, o la identidad de otros partícipes o encubridores del hecho, o cualquier otro dato que posibilite su esclarecimiento.\nEn caso de corresponder prisión o reclusión perpetua, podrá aplicarse prisión o reclusión de OCHO (8) a QUINCE (15) años.\nSólo podrán gozar de este beneficio quienes tengan una responsabilidad penal inferior a la de las personas a quienes identificasen.\n(Artículo sustituido por art. 12 de la Ley N° 26.364, B.O. 30/4/2008)"
 },
 {
  "id": "CP-41-quater",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 41 quater",
  "titulo": "Imputabilidad",
  "tags": "41 quater imputabilidad",
  "texto": "Cuando alguno de los delitos previstos en este Código sea cometido con la intervención de menores de dieciocho años de edad, la escala penal correspondiente se incrementará en un tercio del mínimo y del máximo, respecto de los mayores que hubieren participado en el mismo.\n(Artículo incorporado por art. 1° de la Ley N° 25.767 B.O. 1/9/2003)"
 },
 {
  "id": "CP-42",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 42",
  "titulo": "Tentativa",
  "tags": "42 tentativa",
  "texto": "El que con el fin de cometer un delito determinado comienza su ejecución, pero no lo consuma por circunstancias ajenas a su voluntad, sufrirá las penas determinadas en el artículo 44."
 },
 {
  "id": "CP-43",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 43",
  "titulo": "Tentativa",
  "tags": "43 tentativa",
  "texto": "El autor de tentativa no estará sujeto a pena cuando desistiere voluntariamente del delito."
 },
 {
  "id": "CP-44",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 44",
  "titulo": "Tentativa",
  "tags": "44 tentativa",
  "texto": "La pena que correspondería al agente, si hubiere consumado el delito, se disminuirá de un tercio a la mitad.\nSi la pena fuere de reclusión perpetua, la pena de la tentativa será reclusión de quince a veinte años. Si la pena fuese de prisión perpetua, la de tentativa será prisión de diez a quince años.\nSi el delito fuera imposible, la pena se disminuirá en la mitad y podrá reducírsela al mínimo legal o eximirse de ella, según el grado de peligrosidad revelada por el delincuente."
 },
 {
  "id": "CP-45",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 45",
  "titulo": "Participacion criminal",
  "tags": "45 participacion criminal",
  "texto": "Los que tomasen parte en la ejecución del hecho o prestasen al autor o autores un auxilio o cooperación sin los cuales no habría podido cometerse, tendrán la pena establecida para el delito. En la misma pena incurrirán los que hubiesen determinado directamente a otro a cometerlo."
 },
 {
  "id": "CP-46",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 46",
  "titulo": "Participacion criminal",
  "tags": "46 participacion criminal",
  "texto": "Los que cooperen de cualquier otro modo a la ejecución del hecho y los que presten una ayuda posterior cumpliendo promesas anteriores al mismo, serán reprimidos con la pena correspondiente al delito, disminuida de un tercio a la mitad. Si la pena fuere de reclusión perpetua, se aplicará reclusión de quince a veinte años y si fuere de prisión perpetua, se aplicará prisión de diez a quince años."
 },
 {
  "id": "CP-47",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 47",
  "titulo": "Participacion criminal",
  "tags": "47 participacion criminal",
  "texto": "Si de las circunstancias particulares de la causa resultare que el acusado de complicidad no quiso cooperar sino en un hecho menos grave que el cometido por el autor, la pena será aplicada al cómplice solamente en razón del hecho que prometió ejecutar.\nSi el hecho no se consumase, la pena del cómplice se determinará conforme a los preceptos de este artículo y a los del título de la tentativa."
 },
 {
  "id": "CP-48",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 48",
  "titulo": "Participacion criminal",
  "tags": "48 participacion criminal",
  "texto": "Las relaciones, circunstancias y calidades personales, cuyo efecto sea disminuir o excluir la penalidad, no tendrán influencia sino respecto al autor o cómplice a quienes correspondan. Tampoco tendrán influencia aquéllas cuyo efecto sea agravar la penalidad, salvo el caso en que fueren conocidas por el partícipe."
 },
 {
  "id": "CP-49",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 49",
  "titulo": "Participacion criminal",
  "tags": "49 participacion criminal",
  "texto": "No se considerarán partícipes de los delitos cometidos por la prensa a las personas que solamente prestaren al autor del escrito o grabado la cooperación material necesaria para su publicación, difusión o venta."
 },
 {
  "id": "CP-50",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 50",
  "titulo": "Reincidencia",
  "tags": "50 reincidencia",
  "texto": "Habrá reincidencia siempre que quien hubiera cumplido, total o parcialmente, pena privativa de libertad impuesta por un tribunal del país cometiere un nuevo delito punible también con esa clase de pena.\nLa condena sufrida en el extranjero se tendrá en cuenta para la reincidencia si ha sido pronunciada por razón de un delito que pueda, según la ley argentina, dar lugar a extradición.\nNo dará lugar a reincidencia la pena cumplida por delitos políticos, los previstos exclusivamente en el Código de Justicia Militar, los amnistiados o los cometidos por menores de dieciocho años de edad. La pena sufrida no se tendrá en cuenta a los efectos de la reincidencia cuando desde su cumplimiento hubiera transcurrido un término igual a aquél por la que fuera impuesta, que nunca excederá de diez ni será inferior a cinco años."
 },
 {
  "id": "CP-51",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 51",
  "titulo": "Reincidencia",
  "tags": "51 reincidencia",
  "texto": "Todo ente oficial que lleve registros penales se abstendrá de informar sobre datos de un proceso terminado por sobreseimiento o sentencia absolutoria. En ningún caso se informará la existencia de detenciones que no provengan de la formación de causa, salvo que los informes se requieran para resolver un hábeas corpus o en causas por delitos de que haya sido víctima el detenido.\nEl registro de las sentencias condenatorias caducará a todos sus efectos:\n1. Después de transcurridos diez años desde la sentencia (art. 27) para las condenas condicionales;\n2. Después de transcurridos diez años desde su extinción para las demás condenas a penas privativas de la libertad;\n3. Después de transcurridos cinco años desde su extinción para las condenas a pena de multa o inhabilitación.\nEn todos los casos se deberá brindar la información cuando mediare expreso consentimiento del interesado. Asimismo, los jueces podrán requerir la información, excepcionalmente, por resolución que sólo podrá fundarse en la necesidad concreta del antecedente como elemento de prueba de los hechos en un proceso judicial.\nLos tribunales deberán comunicar a los organismos de registro la fecha de caducidad:\n1. Cuando se extingan las penas perpetuas;\n2. Cuando se lleve a cabo el cómputo de las penas temporales, sean condicionales o de cumplimiento efectivo;\n3. Cuando se cumpla totalmente la pena de multa o, en caso de su sustitución por prisión (art. 21, párr. 2º), al efectuar el cómputo de la prisión impuesta;\n4. Cuando declaren la extinción de las penas en los casos previstos por los artículos 65, 68 y\n69.\nLa violación de la prohibición de informar será considerada como violación de secreto en los términos del artículo 157, si el hecho no constituyere un delito más severamente penado."
 },
 {
  "id": "CP-52",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 52",
  "titulo": "Reincidencia",
  "tags": "52 reincidencia",
  "texto": "Se impondrá reclusión por tiempo indeterminado como accesoria de la última condena, cuando la reincidencia fuere múltiple en forma tal que mediaren las siguientes penas anteriores:\n1. Cuatro penas privativas de libertad, siendo una de ellas mayor de tres años;\n2. Cinco penas privativas de libertad, de tres años o menores.\nLos tribunales podrán, por una única vez, dejar en suspenso la aplicación de esta medida accesoria, fundando expresamente su decisión en la forma prevista en el artículo 26."
 },
 {
  "id": "CP-53",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 53",
  "titulo": "Reincidencia",
  "tags": "53 reincidencia",
  "texto": "En los casos del artículo anterior, transcurridos cinco años del cumplimiento de la reclusión accesoria, el tribunal que hubiera dictado la última condena o impuesto la pena única estará facultado para otorgarle la libertad condicional, previo informe de la autoridad penitenciaria, en las condiciones compromisorias previstas en el artículo 13, y siempre que el condenado hubiera mantenido buena conducta, demostrando aptitud y hábito para el trabajo, y demás actitudes que permitan suponer verosímilmente que no constituirá un peligro para la sociedad. Transcurridos cinco años de obtenida la libertad condicional el condenado podrá solicitar su libertad definitiva al tribunal que la concedió, el que decidirá según sea el resultado obtenido en el período de prueba y previo informe del patronato, institución o persona digna de confianza, a cuyo cargo haya estado el control de la actividad del liberado. Los condenados con la reclusión accesoria por tiempo indeterminado deberán cumplirla en establecimientos federales.\nLa violación por parte del liberado de cualquiera de las condiciones establecidas en el artículo 13 podrá determinar la revocatoria del beneficio acordado y su reintegro al régimen carcelario anterior. Después de transcurridos cinco años de su reintegro al régimen carcelario podrá en los casos de los incisos 1º, 2º, 3º y 5º del artículo 13, solicitar nuevamente su libertad condicional."
 },
 {
  "id": "CP-54",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 54",
  "titulo": "Concurso de delitos",
  "tags": "54 concurso de delitos",
  "texto": "Cuando un hecho cayere bajo más de una sanción penal, se aplicará solamente la que fijare pena mayor."
 },
 {
  "id": "CP-55",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 55",
  "titulo": "Concurso de delitos",
  "tags": "55 concurso de delitos",
  "texto": "Cuando concurrieren varios hechos independientes reprimidos con una misma especie de pena, la pena aplicable al reo tendrá como mínimo, el mínimo mayor y como máximo, la suma aritmética de las penas máximas correspondientes a los diversos hechos.\nSin embargo, esta suma no podrá exceder de (50) cincuenta años de reclusión o prisión.\n(Artículo sustituido por art. 1° de la Ley N° 25.928 B.O. 10/9/2004)"
 },
 {
  "id": "CP-56",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 56",
  "titulo": "Concurso de delitos",
  "tags": "56 concurso de delitos",
  "texto": "Cuando concurrieren varios hechos independientes reprimidos con penas divisibles de reclusión o prisión se aplicará la pena más grave, teniendo en cuenta los delitos de pena menor.\nSi alguna de las penas no fuere divisible, se aplicará ésta únicamente, salvo el caso en que concurrieren la de prisión perpetua y la de reclusión temporal, en que se aplicará reclusión perpetua. La inhabilitación y la multa se aplicarán siempre, sin sujeción a lo dispuesto en el párrafo primero."
 },
 {
  "id": "CP-57",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 57",
  "titulo": "Concurso de delitos",
  "tags": "57 concurso de delitos",
  "texto": "A los efectos del artículo anterior, la gravedad relativa de las penas de diferente naturaleza se determinará por el orden en que se hallan enumeradas en el artículo\n5º."
 },
 {
  "id": "CP-58",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 58",
  "titulo": "Concurso de delitos",
  "tags": "58 concurso de delitos",
  "texto": "Las reglas precedentes se aplicarán también en el caso en que después de una condena pronunciada por sentencia firme se deba juzgar a la misma persona que esté cumpliendo pena por otro hecho distinto; o cuando se hubieren dictado dos o más sentencias firmes con violación de dichas reglas. Corresponderá al juez que haya aplicado la pena mayor dictar, a pedido de parte, su única sentencia, sin alterar las declaraciones de hechos contenidas en las otras.\nCuando por cualquier causa la justicia federal, en autos en que ella haya intervenido, no pueda aplicar esta regla, lo hará la justicia ordinaria nacional o provincial que conoció de la infracción penal, según sea el caso."
 },
 {
  "id": "CP-59",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 59",
  "titulo": "Extincion de acciones y de penas",
  "tags": "59 extincion de acciones y penas",
  "texto": "La acción penal se extinguirá:\n1º. Por la muerte del imputado.\n2º. Por la amnistía.\n3º. Por la prescripción.\n4º. Por la renuncia del agraviado, respecto de los delitos de acción privada."
 },
 {
  "id": "CP-60",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 60",
  "titulo": "Extincion de acciones y de penas",
  "tags": "60 extincion de acciones y penas",
  "texto": "La renuncia de la persona ofendida al ejercicio de la acción penal sólo perjudicará al renunciante y a sus herederos."
 },
 {
  "id": "CP-61",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 61",
  "titulo": "Extincion de acciones y de penas",
  "tags": "61 extincion de acciones y penas",
  "texto": "La amnistía extinguirá la acción penal y hará cesar la condena y todos sus efectos, con excepción de las indemnizaciones debidas a particulares."
 },
 {
  "id": "CP-62",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 62",
  "titulo": "Extincion de acciones y de penas",
  "tags": "62 extincion de acciones y penas",
  "texto": "La acción penal se prescribirá durante el tiempo fijado a continuación:\n1º. A los quince años, cuando se tratare de delitos cuya pena fuere la de reclusión o prisión perpetua;\n2º. Después de transcurrido el máximo de duración de la pena señalada para el delito, si se tratare de hechos reprimidos con reclusión o prisión, no pudiendo, en ningún caso, el término de la prescripción exceder de doce años ni bajar de dos años;\n3º. A los cinco años, cuando se tratare de un hecho reprimido únicamente con inhabilitación perpetua;\n4º. Al año, cuando se tratare de un hecho reprimido únicamente con inhabilitación temporal;\n5º. A los dos años, cuando se tratare de hechos reprimidos con multa."
 },
 {
  "id": "CP-63",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 63",
  "titulo": "Extincion de acciones y de penas",
  "tags": "63 extincion de acciones y penas",
  "texto": "La prescripción de la acción empezará a correr desde la medianoche del día en que se cometió el delito o, si éste fuese continuo, en que cesó de cometerse."
 },
 {
  "id": "CP-64",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 64",
  "titulo": "Extincion de acciones y de penas",
  "tags": "64 extincion de acciones y penas",
  "texto": "La acción penal por delito reprimido con multa se extinguirá en cualquier estado de la instrucción y mientras no se haya iniciado el juicio, por el pago voluntario del mínimo de la multa correspondiente y la reparación de los daños causados por el delito.\nSi se hubiese iniciado el juicio deberá pagarse el máximo de la multa correspondiente, además de repararse los daños causados por el delito.\nEn ambos casos el imputado deberá abandonar en favor del estado, los objetos que presumiblemente resultarían decomisados en caso que recayera condena.\nEl modo de extinción de la acción penal previsto en este artículo podrá ser admitido por segunda vez si el nuevo delito ha sido cometido después de haber transcurrido ocho años a partir de la fecha de la resolución que hubiese declarado la extinción de la acción penal en la causa anterior.\n(Artículo sustituido por art. 6° de la Ley Nº 24.316 B.O. 19/5/1994)"
 },
 {
  "id": "CP-65",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 65",
  "titulo": "Extincion de acciones y de penas",
  "tags": "65 extincion de acciones y penas",
  "texto": "Las penas se prescriben en los términos siguientes:\n1º. La de reclusión perpetua, a los veinte años;\n2º. La de prisión perpetua, a los veinte años;\n3º. La de reclusión o prisión temporal, en un tiempo igual al de la condena;\n4º. La de multa, a los dos años."
 },
 {
  "id": "CP-66",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 66",
  "titulo": "Extincion de acciones y de penas",
  "tags": "66 extincion de acciones y penas",
  "texto": "La prescripción de la pena empezará a correr desde la medianoche del día en que se notificare al reo la sentencia firme o desde el quebrantamiento de la condena, si ésta hubiese empezado a cumplirse."
 },
 {
  "id": "CP-67",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 67",
  "titulo": "Extincion de acciones y de penas",
  "tags": "67 extincion de acciones y penas",
  "texto": "La prescripción se suspende en los casos de los delitos para cuyo juzgamiento sea necesaria la resolución de cuestiones previas o prejudiciales, que deban ser resueltas en otro juicio. Terminada la causa de la suspensión, la prescripción sigue su curso.\nLa prescripción también se suspende en los casos de delitos cometidos en el ejercicio de la función pública, para todos los que hubiesen participado, mientras cualquiera de ellos se encuentre desempeñando un cargo público.\nEl curso de la prescripción de la acción penal correspondiente a los delitos previstos en los artículos 226 y 227 bis, se suspenderá hasta el restablecimiento del orden constitucional.\nLa prescripción se interrumpe solamente por:\na) La comisión de otro delito;\nb) El primer llamado efectuado a una persona, en el marco de un proceso judicial, con el objeto de recibirle declaración indagatoria por el delito investigado;\nc) El requerimiento acusatorio de apertura o elevación a juicio, efectuado en la forma que lo establezca la legislación procesal correspondiente;\nd) El auto de citación a juicio o acto procesal equivalente; y\ne) El dictado de sentencia condenatoria, aunque la misma no se encuentre firme. (Párrafo sustituido por art. 1° de la Ley N° 25.990 B.O. 11/1/2005).\nLa prescripción corre, se suspende o se interrumpe separadamente para cada delito y para cada uno de sus partícipes, con la excepción prevista en el segundo párrafo de este artículo.\n(Párrafo sustituido por art. 1° de la Ley N° 25.990 B.O. 11/1/2005).\n(Artículo sustituido por art. 29 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a partir de los ocho días desde su publicación.)"
 },
 {
  "id": "CP-68",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 68",
  "titulo": "Extincion de acciones y de penas",
  "tags": "68 extincion de acciones y penas",
  "texto": "El indulto del reo extinguirá la pena y sus efectos, con excepción de las indemnizaciones debidas a particulares."
 },
 {
  "id": "CP-69",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 69",
  "titulo": "Extincion de acciones y de penas",
  "tags": "69 extincion de acciones y penas",
  "texto": "El perdón de la parte ofendida extinguirá la pena impuesta por delito de los enumerados en el artículo 73.\nSi hubiere varios partícipes, el perdón en favor de uno de ellos aprovechará a los demás."
 },
 {
  "id": "CP-70",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 70",
  "titulo": "Extincion de acciones y de penas",
  "tags": "70 extincion de acciones y penas",
  "texto": "Las indemnizaciones pecuniarias inherentes a las penas, podrán hacerse efectivas sobre los bienes propios del condenado, aun después de muerto."
 },
 {
  "id": "CP-71",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 71",
  "titulo": "Del ejercicio de las acciones",
  "tags": "71 del ejercicio de las acciones",
  "texto": "Deberán iniciarse de oficio todas las acciones penales, con excepción de las siguientes:\n1º. Las que dependieren de instancia privada;\n2º. Las acciones privadas."
 },
 {
  "id": "CP-72",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 72",
  "titulo": "Del ejercicio de las acciones",
  "tags": "72 del ejercicio de las acciones",
  "texto": "Son acciones dependientes de instancia privada las que nacen de los siguientes delitos:\n1º) Los previstos en los artículos 119, 120 y 130 del Código Penal cuando no resultare la muerte de la persona ofendida o lesiones de las mencionadas en el artículo 91.\n2º) Lesiones leves, sean dolosas o culposas.\nSin embargo, en los casos de este inciso se procederá de oficio cuando mediaren razones de seguridad o interés público.\n3º) Impedimento de contacto de los hijos menores con sus padres no convivientes.\nEn los casos de este artículo, no se procederá a formar causa sino por acusación o denuncia del agraviado, de su tutor, guardador o representantes legales. Sin embargo, se procederá de oficio cuando el delito fuere cometido contra un menor que no tenga padres, tutor ni guardador, o que lo fuere por uno de sus ascendientes, tutor o guardador.\nCuando existieren intereses gravemente contrapuestos entre algunos de éstos y el menor, el Fiscal podrá actuar de oficio cuando así resultare más conveniente para el interés superior de aquél.\n(Artículo sustituido por art. 14 de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-73",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 73",
  "titulo": "Del ejercicio de las acciones",
  "tags": "73 del ejercicio de las acciones",
  "texto": "Son acciones privadas las que nacen de los siguientes delitos:\n1. Calumnias e injurias;\n2. Violación de secretos, salvo en los casos de los artículos 154 y 157;\n3. Concurrencia desleal, prevista en el artículo 159;\n4. Incumplimiento de los deberes de asistencia familiar, cuando la víctima fuere el cónyuge.\n(Artículo sustituido por art. 1° de la Ley N°24.453 B.O. 7/3/1995)"
 },
 {
  "id": "CP-74",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 74",
  "titulo": "Del ejercicio de las acciones",
  "tags": "74 del ejercicio de las acciones",
  "texto": "(Artículo derogado por art. 2° de la Ley N°24.453 B.O. 7/3/1995)"
 },
 {
  "id": "CP-75",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 75",
  "titulo": "Del ejercicio de las acciones",
  "tags": "75 del ejercicio de las acciones",
  "texto": "La acción por calumnia o injuria podrá ser ejercitada sólo por el ofendido y después de su muerte por el cónyuge, hijos, nietos o padres sobrevivientes."
 },
 {
  "id": "CP-76",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 76",
  "titulo": "Del ejercicio de las acciones",
  "tags": "76 del ejercicio de las acciones",
  "texto": "En los demás casos del artículo 73, se procederá únicamente por querella o denuncia del agraviado o de sus guardadores o representantes legales."
 },
 {
  "id": "CP-76-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 76 bis",
  "titulo": "(título incorporado por art. 3° de la ley n°24.316 b.o. 19/5/1994) de la suspensión del juicio a prueba",
  "tags": "76 bis (titulo incorporado por art. 3 de la ley n24.316 b.o. 19/5/1994) suspension del juicio a prueba",
  "texto": "El imputado de un delito de acción pública reprimido con pena de reclusión o prisión cuyo máximo no exceda de tres años, podrá solicitar la suspensión del juicio a prueba.\nEn casos de concurso de delitos, el imputado también podrá solicitar la suspensión del juicio a prueba si el máximo de la pena de reclusión o prisión aplicable no excediese de tres años.\nAl presentar la solicitud, el imputado deberá ofrecer hacerse cargo de la reparación del daño en la medida de lo posible, sin que ello implique confesión ni reconcimiento de la responsabilidad civil correspondiente. El juez decidirá sobre la razonabilidad del ofrecimiento en resolución fundada. La parte damnificada podrá aceptar o no la reparación ofrecida, y en este último caso, si la realización del juicio se suspendiere, tendrá habilitada la acción civil correspondiente.\nSi las circunstancias del caso permitieran dejar en suspenso el cumplimiento de la condena aplicable, y hubiese consentimiento del fiscal, el Tribunal podrá suspender la realización del juicio.\nSi el delito o alguno de los delitos que integran el concurso estuviera reprimido con pena de multa aplicable en forma conjunta o alternativa con la de prisión, será condición, además, que se pague el mínimo de la multa correspondiente.\nEl imputado deberá abandonar en favor del estado, los bienes que presumiblemente resultarían decomisados en caso que recayera condena.\nNo procederá la suspensión del juicio cuando un funcionario público, en el ejercicio de sus funciones, hubiese participado en el delito.\nTampoco procederá la suspensión del juicio a prueba respecto de los delitos reprimidos con pena de inhabilitación.\n(Artículo incorporado por art. 3° de la Ley N° 24.316 B.O. 19/5/1994)"
 },
 {
  "id": "CP-76-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 76 ter",
  "titulo": "(título incorporado por art. 3° de la ley n°24.316 b.o. 19/5/1994) de la suspensión del juicio a prueba",
  "tags": "76 ter (titulo incorporado por art. 3 de la ley n24.316 b.o. 19/5/1994) suspension del juicio a prueba",
  "texto": "El tiempo de la suspensión del juicio será fijado por el Tribunal entre uno y tres años, según la gravedad del delito.\nEl Tribunal establecerá las reglas de conducta que deberá cumplir el imputado, conforme las previsiones del artículo 27 Bis.\nDurante ese tiempo se suspenderá la prescripción de la acción penal.\nLa suspensión del juicio será dejada sin efecto si con posterioridad se conocieran circunstancias que modifiquen el máximo de la pena aplicable o la estimación acerca de la condicionalidad de la ejecución de la posible condena.\nSi durante el tiempo fijado por el Tribunal el imputado no comete un delito, repara los daños en la medida ofrecida y cumple con las reglas de conducta establecidas, se extinguirá la acción penal. En caso contrario, se llevará a cabo el juicio y si el imputado fuere absuelto se le devolverán los bienes abandonados en favor del estado y la multa pagada, pero no podrá pretender el reintegro de las reparaciones cumplidas.\nLa suspensión de un juicio a prueba podrá ser concedida por segunda vez si el nuevo delito ha sido cometido después de haber transcurrido ocho años a partir de la fecha de expiración del plazo por el cual hubiera sido suspendido el juicio en el proceso anterior.\nNo se admitirá una nueva suspensión de juicio respecto de quien hubiese incumplido las reglas impuestas en una suspensión anterior.\n(Artículo incorporado por art. 4° de la Ley N° 24.316 B.O. 19/5/1994)"
 },
 {
  "id": "CP-76-quater",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 76 quater",
  "titulo": "(título incorporado por art. 3° de la ley n°24.316 b.o. 19/5/1994) de la suspensión del juicio a prueba",
  "tags": "76 quater (titulo incorporado por art. 3 de la ley n24.316 b.o. 19/5/1994) suspension del juicio a prueba",
  "texto": "La suspensión del juicio a prueba hará inaplicables al caso las reglas de prejudicialidad de los artículos 1101 y 1102 del Código Civil, y no obstará a la aplicación de las sanciones contravencionales, disciplinarias o administrativas que pudieran corresponder.\n(Artículo incorporado por art. 5° de la Ley N° 24.316 B.O. 19/5/1994)"
 },
 {
  "id": "CP-77",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 77",
  "titulo": "(numeración del capítulo sustituida por art. 2° de la ley n° 24.316 b.o. 19/5/1994) significacion de conceptos empleados en el codigo",
  "tags": "77 (numeracion del capitulo sustituida por art. 2 de la ley n 24.316 b.o. 19/5/1994) significacion conceptos empleados en el codigo",
  "texto": "Para la inteligencia del texto de este código, se tendrá presente las siguientes reglas:\nLos plazos a que este código se refiere serán contados con arreglo a las disposiciones del Código Civil. Sin embargo, la liberación de los condenados a penas privativas de libertad se efectuará al mediodía del día correspondiente.\nLa expresión \"reglamentos\" u \"ordenanzas\", comprende todas las disposiciones de carácter general dictadas por la autoridad competente en la materia de que traten.\nPor los términos \"funcionario público\" y \"empleado público\", usados en este código, se designa a todo el que participa accidental o permanentemente del ejercicio de funciones públicas, sea por elección popular o por nombramiento de autoridad competente.\nPor el término militar se designa a toda persona que revista estado militar en el momento del hecho conforme la ley orgánica para el personal militar. Los funcionarios públicos civiles que integran la cadena de mando se encuentran asimilados al personal militar con relación a los delitos que cometan en su carácter de tales, cuando produzcan actos o impartan órdenes o instrucciones como integrantes de la cadena de mando si las mismas implican comisión de delito o participación en el mismo. (Párrafo incorporado por art. 1° del Anexo I de la Ley N°\n26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación) Con la palabra \"mercadería\", se designa toda clase de efectos susceptibles de expendio.\nEl término \"capitán\", comprende a todo comandante de embarcación o al que le sustituye.\nEl término \"tripulación\", comprende a todos los que se hallan a bordo como oficiales o marineros.\nEl término \"estupefacientes\", comprende los estupefacientes, psicotrópicos y demás substancias susceptibles de producir dependencia física o psíquica, que se incluyan en las listas que se elaboren y actualicen periódicamente por decreto del Poder Ejecutivo Nacional.\n(Párrafo sustituido por art. 40 de la Ley N° 23.737 B.O.11/10/1989) El término \"establecimiento rural\" comprende todo inmueble que se destine a la cría, mejora o engorde del ganado, actividades de tambo, granja o cultivo de la tierra, a la avicultura u otras crianzas, fomento o aprovechamiento semejante. (Párrafo incorporado por art. 1° de la Ley N°\n25.890 B.O.21/5/2004) El término \"documento\" comprende toda representación de actos o hechos, con independencia del soporte utilizado para su fijación, almacenamiento, archivo o transmisión. (Párrafo incorporado por art. 1° de la Ley N° 26.388, B.O. 25/6/2008) Los términos \"firma\" y \"suscripción\" comprenden la firma digital, la creación de una firma digital o firmar digitalmente. (Párrafo incorporado por art. 1° de la Ley N° 26.388, B.O. 25/6/2008) Los términos \"instrumento privado\" y \"certificado\" comprenden el documento digital firmado digitalmente. (Párrafo incorporado por art. 1° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-78",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 78",
  "titulo": "(numeración del capítulo sustituida por art. 2° de la ley n° 24.316 b.o. 19/5/1994) significacion de conceptos empleados en el codigo",
  "tags": "78 (numeracion del capitulo sustituida por art. 2 de la ley n 24.316 b.o. 19/5/1994) significacion conceptos empleados en el codigo",
  "texto": "Queda comprendido en el concepto de \"violencia\", el uso de medios hipnóticos o narcóticos."
 },
 {
  "id": "CP-78-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 78 bis",
  "titulo": "(numeración del capítulo sustituida por art. 2° de la ley n° 24.316 b.o. 19/5/1994) significacion de conceptos empleados en el codigo",
  "tags": "78 bis (numeracion del capitulo sustituida por art. 2 de la ley n 24.316 b.o. 19/5/1994) significacion conceptos empleados en el codigo",
  "texto": "(Artículo derogado por art. 14 de la Ley N° 26.388, B.O. 25/6/2008) LIBRO SEGUNDO DE LOS DELITOS"
 },
 {
  "id": "CP-79",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 79",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "79 delitos contra las personas la vida",
  "texto": "Se aplicará reclusión o prisión de ocho a veinticinco años, al que matare a otro siempre que en este código no se estableciere otra pena."
 },
 {
  "id": "CP-80",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 80",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "80 delitos contra las personas la vida",
  "texto": "Se impondrá reclusión perpetua o prisión perpetua, pudiendo aplicarse lo dispuesto en el artículo 52, al que matare:\n1º A su ascendiente, descendiente o cónyuge, sabiendo que lo son.\n2º Con ensañamiento, alevosía, veneno u otro procedimiento insidioso.\n3º Por precio o promesa remuneratoria.\n4º Por placer, codicia, odio racial o religioso.\n5º Por un medio idóneo para crear un peligro común.\n6º Con el concurso premeditado de dos o más personas.\n7º Para preparar, facilitar, consumar u ocultar otro delito o para asegurar sus resultados o procurar la impunidad para sí o para otro o por no haber logrado el fin propuesto al intentar otro delito.\n8° A un miembro de las fuerzas de seguridad pública, policiales o penitenciarias, por su función, cargo o condición. (Inciso incorporado por art. 1° de la Ley N° 25.601 B.O.11/6/2002)\n9° Abusando de su función o cargo, cuando fuere miembro integrante de las fuerzas de seguridad, policiales o del servicio penitenciario. (Inciso incorporado por art. 1° de la Ley N°\n25.816 B.O.9/12/2003) 10 A su superior militar frente a enemigo o tropa formada con armas. (Inciso incorporado por art. 2° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación) Cuando en el caso del inciso primero de este artículo, mediaren circunstancias extraordinarias de atenuación, el juez podrá aplicar prisión o reclusión de ocho a veinticinco años."
 },
 {
  "id": "CP-81",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 81",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "81 delitos contra las personas la vida",
  "texto": "1º Se impondrá reclusión de tres a seis años, o prisión de uno a tres años:\na) Al que matare a otro, encontrándose en un estado de emoción violenta y que las circunstancias hicieren excusable.\nb) Al que, con el propósito de causar un daño en el cuerpo o en la salud, produjere la muerte de alguna persona, cuando el medio empleado no debía razonablemente ocasionar la muerte.\n2º (Inciso derogado por art. 1° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-82",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 82",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "82 delitos contra las personas la vida",
  "texto": "Cuando en el caso del inciso 1º del artículo 80 concurriese alguna de las circunstancias del inciso 1º del artículo anterior, la pena será de reclusión o prisión de diez a veinticinco años."
 },
 {
  "id": "CP-83",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 83",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "83 delitos contra las personas la vida",
  "texto": "Será reprimido con prisión de uno a cuatro años, el que instigare a otro al suicidio o le ayudare a cometerlo, si el suicidio se hubiese tentado o consumado."
 },
 {
  "id": "CP-84",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 84",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "84 delitos contra las personas la vida",
  "texto": "Será reprimido con prisión de seis meses a cinco años e inhabilitación especial, en su caso, por cinco a diez años el que por imprudencia, negligencia, impericia en su arte o profesión o inobservancia de los reglamentos o de los deberes a su cargo, causare a otro la muerte.\nEl mínimo de la pena se elevará a dos años si fueren más de una las víctimas fatales, o si el hecho hubiese sido ocasionado por la conducción imprudente, negligente, inexperta, o antirreglamentaria de un vehículo automotor.\n(Artículo sustituido por art. 1° de la Ley N° 25.189 28/10/1999)"
 },
 {
  "id": "CP-85",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 85",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "85 delitos contra las personas la vida",
  "texto": "El que causare un aborto será reprimido:\n1º Con reclusión o prisión de tres a diez años, si obrare sin consentimiento de la mujer. Esta pena podrá elevarse hasta quince años, si el hecho fuere seguido de la muerte de la mujer.\n2º Con reclusión o prisión de uno a cuatro años, si obrare con consentimiento de la mujer.\nEl máximum de la pena se elevará a seis años, si el hecho fuere seguido de la muerte de la mujer."
 },
 {
  "id": "CP-86",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 86",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "86 delitos contra las personas la vida",
  "texto": "Incurrirán en las penas establecidas en el artículo anterior y sufrirán, además, inhabilitación especial por doble tiempo que el de la condena, los médicos, cirujanos, parteras o farmacéuticos que abusaren de su ciencia o arte para causar el aborto o cooperaren a causarlo.\nEl aborto practicado por un médico diplomado con el consentimiento de la mujer encinta, no es punible:\n1º Si se ha hecho con el fin de evitar un peligro para la vida o la salud de la madre y si este peligro no puede ser evitado por otros medios.\n2º Si el embarazo proviene de una violación o de un atentado al pudor cometido sobre una mujer idiota o demente. En este caso, el consentimiento de su representante legal deberá ser requerido para el aborto."
 },
 {
  "id": "CP-87",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 87",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "87 delitos contra las personas la vida",
  "texto": "Será reprimido con prisión de seis meses a dos años, el que con violencia causare un aborto sin haber tenido el propósito de causarlo, si el estado de embarazo de la paciente fuere notorio o le constare."
 },
 {
  "id": "CP-88",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 88",
  "titulo": "Delitos contra las personas · Delitos contra la vida",
  "tags": "88 delitos contra las personas la vida",
  "texto": "Será reprimida con prisión de uno a cuatro años, la mujer que causare su propio aborto o consintiere en que otro se lo causare. La tentativa de la mujer no es punible."
 },
 {
  "id": "CP-89",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 89",
  "titulo": "Delitos contra las personas · Lesiones",
  "tags": "89 delitos contra las personas lesiones",
  "texto": "Se impondrá prisión de un mes a un año, al que causare a otro, en el cuerpo o en la salud, un daño que no esté previsto en otra disposición de este código."
 },
 {
  "id": "CP-90",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 90",
  "titulo": "Delitos contra las personas · Lesiones",
  "tags": "90 delitos contra las personas lesiones",
  "texto": "Se impondrá reclusión o prisión de uno a seis años, si la lesión produjere una debilitación permanente de la salud, de un sentido, de un órgano, de un miembro o una dificultad permanente de la palabra o si hubiere puesto en peligro la vida del ofendido, le hubiere inutilizado para el trabajo por más de un mes o le hubiere causado una deformación permanente del rostro."
 },
 {
  "id": "CP-91",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 91",
  "titulo": "Delitos contra las personas · Lesiones",
  "tags": "91 delitos contra las personas lesiones",
  "texto": "Se impondrá reclusión o prisión de tres a diez años, si la lesión produjere una enfermedad mental o corporal, cierta o probablemente incurable, la inutilidad permanente para el trabajo, la pérdida de un sentido, de un órgano, de un miembro, del uso de un órgano o miembro, de la palabra o de la capacidad de engendrar o concebir."
 },
 {
  "id": "CP-92",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 92",
  "titulo": "Delitos contra las personas · Lesiones",
  "tags": "92 delitos contra las personas lesiones",
  "texto": "Si concurriere alguna de las circunstancias enumeradas en el artículo 80, la pena será: en el caso del artículo 89, de seis meses a dos años; en el caso del artículo 90, de tres a diez años; y en el caso del artículo 91, de tres a quince años."
 },
 {
  "id": "CP-93",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 93",
  "titulo": "Delitos contra las personas · Lesiones",
  "tags": "93 delitos contra las personas lesiones",
  "texto": "Si concurriere la circunstancia enunciada en el inciso 1º letra a) del artículo 81, la pena será: en el caso del artículo 89, de quince días a seis meses; en el caso del artículo 90, de seis meses a tres años; y en el caso del artículo 91, de uno a cuatro años."
 },
 {
  "id": "CP-94",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 94",
  "titulo": "Delitos contra las personas · Lesiones",
  "tags": "94 delitos contra las personas lesiones",
  "texto": "Se impondrá prisión de un mes a tres años o multa de mil a quince mil pesos e inhabilitación especial por uno a cuatro años, el que por imprudencia o negligencia, por impericia en su arte o profesión, o por inobservancia de los reglamentos o deberes a su cargo, causare a otro un daño en el cuerpo o en la salud.\nSi las lesiones fueran de las descritas en los artículos 90 ó 91 y concurriera alguna de las circunstancias previstas en el segundo párrafo del artículo 84, el mínimo de la pena prevista en el primer párrafo, será de seis meses o multa de tres mil pesos e inhabilitación especial por dieciocho meses.\n(Artículo sustituido por art. 2° de la Ley N° 25.189 28/10/1999)\n(Multa actualizada por la Ley N° 24.286 B.O. 29/12/1993.)"
 },
 {
  "id": "CP-95",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 95",
  "titulo": "Delitos contra las personas · Homicidio o lesiones en riña",
  "tags": "95 delitos contra las personas homicidio o lesiones en rina",
  "texto": "Cuando en riña o agresión en que tomaren parte más de dos personas, resultare muerte o lesiones de las determinadas en los artículos 90 y 91, sin que constare quiénes las causaron, se tendrá por autores a todos los que ejercieron violencia sobre la persona del ofendido y se aplicará reclusión o prisión de dos a seis años en caso de muerte y de uno a cuatro en caso de lesión."
 },
 {
  "id": "CP-96",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 96",
  "titulo": "Delitos contra las personas · Homicidio o lesiones en riña",
  "tags": "96 delitos contra las personas homicidio o lesiones en rina",
  "texto": "Si las lesiones fueren las previstas en el artículo 89, la pena aplicable será de cuatro a ciento veinte días de prisión."
 },
 {
  "id": "CP-97",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 97",
  "titulo": "Delitos contra las personas · Duelo",
  "tags": "97 delitos contra las personas duelo",
  "texto": "Los que se batieren en duelo, con intervención de dos o más padrinos, mayores de edad, que elijan las armas y arreglen las demás condiciones del desafío, serán reprimidos:\n1º Con prisión de uno a seis meses, al que no infiriere lesión a su adversario o sólo le causare una lesión de las determinadas en el artículo 89.\n2º Con prisión de uno a cuatro años, al que causare la muerte de su adversario o le infiriere lesión de las determinadas en los artículos 90 y 91."
 },
 {
  "id": "CP-98",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 98",
  "titulo": "Delitos contra las personas · Duelo",
  "tags": "98 delitos contra las personas duelo",
  "texto": "Los que se batieren, sin la intervención de padrinos, mayores de edad, que elijan las armas y arreglen las demás condiciones del desafío, serán reprimidos:\n1º El que matare a su adversario, con la pena señalada para el homicida;\n2º El que causare lesiones, con la pena señalada para el autor de lesiones;\n3º El que no causare lesiones, con prisión de un mes a un año."
 },
 {
  "id": "CP-99",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 99",
  "titulo": "Delitos contra las personas · Duelo",
  "tags": "99 delitos contra las personas duelo",
  "texto": "El que instigare a otro a provocar o a aceptar un duelo y el que desacreditare públicamente a otro por no desafiar o por rehusar un desafío, serán reprimidos: 1 Con multa de pesos mil a pesos quince mil si el duelo no se realizare o si realizándose, no se produjere muerte ni lesiones o sólo lesiones de las comprendidas en el artículo 89. (Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993) 2 Con prisión de uno a cuatro años, si se causare muerte o lesiones de las mencionadas en los artículos 90 y 91."
 },
 {
  "id": "CP-100",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 100",
  "titulo": "Delitos contra las personas · Duelo",
  "tags": "100 delitos contra las personas duelo",
  "texto": "El que provocare o diere causa a un desafío, proponiéndose un interés pecuniario u otro objeto inmoral, será reprimido:\n1º Con prisión de uno a cuatro años, si el duelo no se verificare o si efectuándose, no resultare muerte ni lesiones. 2 Con reclusión o prisión de tres a diez años, si el duelo se realizare y resultaren lesiones; 3 Con reclusión o prisión de diez a veinticinco años, si se produjere la muerte."
 },
 {
  "id": "CP-101",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 101",
  "titulo": "Delitos contra las personas · Duelo",
  "tags": "101 delitos contra las personas duelo",
  "texto": "El combatiente que faltare, en daño de su adversario, a las condiciones ajustadas por los padrinos, será reprimido:\n1º Con reclusión o prisión de tres a diez años, si causare lesiones a su adversario.\n2º Con reclusión o prisión de diez a veinticinco años, si le causare la muerte."
 },
 {
  "id": "CP-102",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 102",
  "titulo": "Delitos contra las personas · Duelo",
  "tags": "102 delitos contra las personas duelo",
  "texto": "Los padrinos de un duelo que usaren cualquier género de alevosía en la ejecución del mismo, serán reprimidos con las penas señaladas en el artículo anterior, según fueren las consecuencias que resultaren."
 },
 {
  "id": "CP-103",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 103",
  "titulo": "Delitos contra las personas · Duelo",
  "tags": "103 delitos contra las personas duelo",
  "texto": "Cuando los padrinos concertaren un duelo a muerte o en condiciones tales que de ellas debiere resultar la muerte, serán reprimidos con reclusión o prisión de uno a cuatro años, si se verificare la muerte de alguno de los combatientes. Si no se verificare la muerte de alguno de ellos, la pena será de multa de pesos mil a pesos quince mil.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N°24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-104",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 104",
  "titulo": "Delitos contra las personas · Abuso de armas",
  "tags": "104 delitos contra las personas abuso de armas",
  "texto": "Será reprimido con uno a tres años de prisión, el que disparare un arma de fuego contra una persona sin herirla.\nEsta pena se aplicará aunque se causare herida a que corresponda pena menor, siempre que el hecho no importe un delito más grave.\nSerá reprimida con prisión de quince días a seis meses, la agresión con toda arma, aunque no se causare herida."
 },
 {
  "id": "CP-105",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 105",
  "titulo": "Delitos contra las personas · Abuso de armas",
  "tags": "105 delitos contra las personas abuso de armas",
  "texto": "Si concurriera alguna de las circunstancias previstas en los artículos 80 y 81, inciso 1º, letra a), la pena se aumentará o disminuirá en un tercio respectivamente."
 },
 {
  "id": "CP-106",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 106",
  "titulo": "Delitos contra las personas · Abandono de personas",
  "tags": "106 delitos contra las personas abandono de",
  "texto": "El que pusiere en peligro la vida o la salud de otro, sea colocándolo en situación de desamparo, sea abandonando a su suerte a una persona incapaz de valerse y a la que deba mantener o cuidar o a la que el mismo autor haya incapacitado, será reprimido con prisión de 2 a 6 años.\nLa pena será de reclusión o prisión de 3 a 10 años, si a consecuencia del abandono resultare grave daño en el cuerpo o en la salud de la víctima.\nSi ocurriere la muerte, la pena será de 5 a 15 años de reclusión o prisión.\n(Artículo sustituido por art. 2° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-107",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 107",
  "titulo": "Delitos contra las personas · Abandono de personas",
  "tags": "107 delitos contra las personas abandono de",
  "texto": "El máximum y el mínimum de las penas establecidas en el artículo precedente, serán aumentados en un tercio cuando el delito fuera cometido por los padres contra sus hijos y por éstos contra aquéllos o por el cónyuge..\n(Artículo sustituido por art. 1° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-108",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 108",
  "titulo": "Delitos contra las personas · Abandono de personas",
  "tags": "108 delitos contra las personas abandono de",
  "texto": "Será reprimido con multa de pesos setecientos cincuenta a pesos doce mil quinientos el que encontrando perdido o desamparado a un menor de diez años o a una persona herida o inválida o amenazada de un peligro cualquiera; omitiere prestarle el auxilio necesario, cuando pudiere hacerlo sin riesgo personal o no diere aviso inmediatamente a la autoridad.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-109",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 109",
  "titulo": "Delitos contra el honor",
  "tags": "109 delitos contra el honor",
  "texto": "La calumnia o falsa imputación a una persona física determinada de la comisión de un delito concreto y circunstanciado que dé lugar a la acción pública, será reprimida con multa de pesos tres mil ($ 3.000.-) a pesos treinta mil ($ 30.000.-). En ningún caso configurarán delito de calumnia las expresiones referidas a asuntos de interés público o las que no sean asertivas.\n(Artículo sustituido por art. 1° de la Ley N° 26.551 B.O. 27/11/2009)"
 },
 {
  "id": "CP-110",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 110",
  "titulo": "Delitos contra el honor",
  "tags": "110 delitos contra el honor",
  "texto": "El que intencionalmente deshonrare o desacreditare a una persona física determinada será reprimido con multa de pesos mil quinientos ($ 1.500.-) a pesos veinte mil\n($ 20.000.-). En ningún caso configurarán delito de injurias las expresiones referidas a asuntos de interés público o las que no sean asertivas. Tampoco configurarán delito de injurias los calificativos lesivos del honor cuando guardasen relación con un asunto de interés público.\n(Artículo sustituido por art. 2° de la Ley N° 26.551 B.O. 27/11/2009)\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-111",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 111",
  "titulo": "Delitos contra el honor",
  "tags": "111 delitos contra el honor",
  "texto": "El acusado de injuria, en los casos en los que las expresiones de ningún modo estén vinculadas con asuntos de interés público, no podrá probar la verdad de la imputación salvo en los casos siguientes:\n1) Si el hecho atribuido a la persona ofendida, hubiere dado lugar a un proceso penal.\n2) Si el querellante pidiera la prueba de la imputación dirigida contra él.\nEn estos casos, si se probare la verdad de las imputaciones, el acusado quedará exento de pena.\n(Artículo sustituido por art. 3° de la Ley N° 26.551 B.O. 27/11/2009)"
 },
 {
  "id": "CP-112",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 112",
  "titulo": "Delitos contra el honor",
  "tags": "112 delitos contra el honor",
  "texto": "(Artículo derogado por art. 4° de la Ley N° 26.551 B.O. 27/11/2009)"
 },
 {
  "id": "CP-113",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 113",
  "titulo": "Delitos contra el honor",
  "tags": "113 delitos contra el honor",
  "texto": "El que publicare o reprodujere, por cualquier medio, injurias o calumnias inferidas por otro, será reprimido como autor de las injurias o calumnias de que se trate, siempre que su contenido no fuera atribuido en forma sustancialmente fiel a la fuente pertinente. En ningún caso configurarán delito de calumnia las expresiones referidas a asuntos de interés público o las que no sean asertivas.\n(Artículo sustituido por art. 5° de la Ley N° 26.551 B.O. 27/11/2009)"
 },
 {
  "id": "CP-114",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 114",
  "titulo": "Delitos contra el honor",
  "tags": "114 delitos contra el honor",
  "texto": "Cuando la injuria o calumnia se hubiere propagado por medio de la prensa, en la capital y territorios nacionales, sus autores quedarán sometidos a las sanciones del presente código y el juez o tribunal ordenará, si lo pidiere el ofendido, que los editores inserten en los respectivos impresos o periódicos, a costa del culpable, la sentencia o satisfacción."
 },
 {
  "id": "CP-115",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 115",
  "titulo": "Delitos contra el honor",
  "tags": "115 delitos contra el honor",
  "texto": "Las injurias proferidas por los litigantes, apoderados o defensores, en los escritos, discursos o informes producidos ante los tribunales y no dados a publicidad, quedarán sujetas únicamente a las correcciones disciplinarias correspondientes."
 },
 {
  "id": "CP-116",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 116",
  "titulo": "Delitos contra el honor",
  "tags": "116 delitos contra el honor",
  "texto": "Cuando las injurias fueren recíprocas, el tribunal podrá, según las circunstancias, declarar exentas de pena a las dos partes o a alguna de ellas."
 },
 {
  "id": "CP-117",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 117",
  "titulo": "Delitos contra el honor",
  "tags": "117 delitos contra el honor",
  "texto": "El acusado de injuria o calumnia quedará exento de pena si se retractare públicamente, antes de contestar la querella o en el acto de hacerlo. La retractación no importará para el acusado la aceptación de su culpabilidad.\n(Artículo sustituido por art. 6° de la Ley N° 26.551 B.O. 27/11/2009)"
 },
 {
  "id": "CP-117-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 117 bis",
  "titulo": "Delitos contra el honor",
  "tags": "117 bis delitos contra el honor",
  "texto": "1°. (Inciso derogado por art. 14 de la Ley N° 26.388, B.O. 25/6/2008)\n2°. La pena será de seis meses a tres años, al que proporcionara a un tercero a sabiendas información falsa contenida en un archivo de datos personales.\n3°. La escala penal se aumentará en la mitad del mínimo y del máximo, cuando del hecho se derive perjuicio a alguna persona.\n4°. Cuando el autor o responsable del ilícito sea funcionario público en ejercicio de sus funciones, se le aplicará la accesoria de inhabilitación para el desempeño de cargos públicos por el doble del tiempo que el de la condena.\n(Artículo incorporado por art. 32 de la Ley N° 25.326 B.O. 2/11/2000)"
 },
 {
  "id": "CP-118",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 118",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "118 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "(Artículo derogado por art. 4° de la Ley N°24.453 B.O. 7/3/1995)"
 },
 {
  "id": "CP-119",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 119",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "119 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Será reprimido con reclusión o prisión de seis meses a cuatro años el que abusare sexualmente de persona de uno u otro sexo cuando, ésta fuera menor de trece años o cuando mediare violencia, amenaza, abuso coactivo o intimidatorio de una relación de dependencia, de autoridad, o de poder, o aprovechándose de que la víctima por cualquier causa no haya podido consentir libremente la acción.\nLa pena será de cuatro a diez años de reclusión o prisión cuando el abuso por su duración o circunstancias de su realización, hubiere configurado un sometimiento sexual gravemente ultrajante para la víctima.\nLa pena será de seis a quince años de reclusión o prisión cuando mediando las circunstancias del primer párrafo hubiere acceso carnal por cualquier vía.\nEn los supuestos de los dos párrafos anteriores, la pena será de ocho a veinte años de reclusión o prisión si:\na) Resultare un grave daño en la salud física o mental de la víctima;\nb) El hecho fuere cometido por ascendiente, descendiente, afín en línea recta, hermano, tutor, curador, ministro de algún culto reconocido o no, encargado de la educación o de la guarda;\nc) El autor tuviere conocimiento de ser portador de una enfermedad de transmisión sexual grave, y hubiere existido peligro de contagio;\nd) El hecho fuere cometido por dos o más personas, o con armas;\ne) El hecho fuere cometido por personal perteneciente a las fuerzas policiales o de seguridad, en ocasión de sus funciones;\nf) El hecho fuere cometido contra un menor de dieciocho años, aprovechando la situación de convivencia preexistente con el mismo.\nEn el supuesto del primer párrafo, la pena será de tres a diez años de reclusión o prisión si concurren las circunstancias de los incisos a), b), d), e) o f).\"\n(Artículo sustituido por art. 2° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-120",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 120",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "120 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Será reprimido con prisión o reclusión de tres a seis años el que realizare algunas de las acciones previstas en el segundo o en el tercer párrafo del artículo 119 con una persona menor de dieciséis años, aprovechándose de su inmadurez sexual, en razón de la mayoría de edad del autor, su relación de preeminencia respecto de la víctima, u otra circunstancia equivalente, siempre que no resultare un delito más severamente penado.\nLa pena será de prisión o reclusión de seis a diez años si mediare alguna de las circunstancias previstas en los incisos a), b), c), e) o f) del cuarto párrafo del artículo 119\n(Artículo sustituido por art. 3° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-121",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 121",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "121 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "(Artículo derogado por art. 4° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-122",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 122",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "122 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "(Artículo derogado por art. 4° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-123",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 123",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "123 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "(Artículo derogado por art. 4° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-124",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 124",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "124 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Se impondrá reclusión o prisión perpetua, cuando en los casos de los artículos 119 y 120 resultare la muerte de la persona ofendida.\n(Artículo sustituido por art. 1° de la Ley N° 25.893 B.O. 26/5/2004)"
 },
 {
  "id": "CP-125",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 125",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "125 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "El que promoviere o facilitare la corrupción de menores de dieciocho años, aunque mediare el consentimiento de la víctima será reprimido con reclusión o prisión de tres a diez años.\nLa pena será de seis a quince años de reclusión o prisión cuando la víctima fuera menor de trece años.\nCualquiera que fuese la edad de la víctima, la pena será de reclusión o prisión de diez a quince años, cuando mediare engaño, violencia, amenaza, abuso de autoridad o cualquier otro medio de intimidación o coerción, como también si el autor fuera ascendiente, cónyuge, hermano, tutor o persona conviviente o encargada de su educación o guarda.\n(Artículo sustituido por art. 5° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-125-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 125 bis",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "125 bis delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "El que promoviere o facilitare la prostitución de menores de dieciocho años, aunque mediare el consentimiento de la víctima será reprimido con reclusión o prisión de cuatro a diez años.\nLa pena será de seis a quince años de reclusión o prisión cuando la víctima fuera menor de trece años.\nCualquiera que fuese la edad de la víctima, la pena será de reclusión o prisión de diez a quince años, cuando mediare engaño, violencia, amenaza, abuso de autoridad o cualquier otro medio de intimidación o coerción, como también, si el autor fuera ascendiente, cónyuge, hermano, tutor o persona conviviente o encargada de su educación o guarda.\n(Artículo incorporado por art. 6° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-126",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 126",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "126 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Será reprimido con reclusión o prisión de cuatro a diez años, el que con ánimo de lucro o para satisfacer deseos ajenos promoviere o facilitare la prostitución de mayores de dieciocho años de edad mediando engaño, abuso de una relación de dependencia o de poder, violencia, amenaza o cualquier otro medio de intimidación o coerción.\"\n(Artículo sustituido por art. 7° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-127",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 127",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "127 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Será reprimido con prisión de tres a seis años, el que explotare económicamente el ejercicio de la prostitución de una persona, mediando engaño, abuso coactivo o intimidatorio de una relación de dependencia, de autoridad, de poder, violencia, amenaza o cualquier otro medio de intimidación o coerción.\n(Artículo sustituido por art. 8° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-127-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 127 bis",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "127 bis delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "(Artículo derogado por art. 17 de la Ley N° 26.364, B.O. 30/4/2008)"
 },
 {
  "id": "CP-127-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 127 ter",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "127 ter delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "(Artículo derogado por art. 17 de la Ley N° 26.364, B.O. 30/4/2008)"
 },
 {
  "id": "CP-128",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 128",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "128 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Será reprimido con prisión de seis (6) meses a cuatro (4) años el que produjere, financiare, ofreciere, comerciare, publicare, facilitare, divulgare o distribuyere, por cualquier medio, toda representación de un menor de dieciocho (18) años dedicado a actividades sexuales explícitas o toda representación de sus partes genitales con fines predominantemente sexuales, al igual que el que organizare espectáculos en vivo de representaciones sexuales explícitas en que participaren dichos menores.\nSerá reprimido con prisión de cuatro (4) meses a dos (2) años el que tuviere en su poder representaciones de las descriptas en el párrafo anterior con fines inequívocos de distribución o comercialización.\nSerá reprimido con prisión de un (1) mes a tres (3) años el que facilitare el acceso a espectáculos pornográficos o suministrare material pornográfico a menores de catorce (14) años.\n(Artículo sustituido por art. 2° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-129",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 129",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "129 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Será reprimido con multa de mil a quince mil pesos el que ejecutare o hiciese ejecutar por otros actos de exhibiciones obscenas expuestas a ser vistas involuntariamente por terceros.\nSi los afectados fueren menores de dieciocho años la pena será de prisión de seis meses a cuatro años. Lo mismo valdrá, con independencia de la voluntad del afectado, cuando se tratare de un menor de trece años.\n(Artículo sustituido por art. 10° de la Ley N° 25.087, B.O. 14/5/1999)\n(Nota Infoleg: multa actualizada anteriormente por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-130",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 130",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "130 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Será reprimido con prisión de uno a cuatro años, el que sustrajere o retuviere a una persona por medio de la fuerza, intimidación o fraude, con la intención de menoscabar su integridad sexual.\nLa pena será de seis meses a dos años, si se tratare de una persona menor de dieciséis años, con su consentimiento.\nLa pena será de dos a seis años si se sustrajere o retuviere mediante fuerza, intimidación o fraude a una persona menor de trece años, con el mismo fin.\n(Artículo sustituido por art. 11° de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-131",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 131",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "131 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "(Artículo derogado por art. 12 de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-132",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 132",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "132 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "En los delitos previstos en los artículos 119: 1º, 2º, 3º párrafos, 120: 1º párrafo y 130 la víctima podrá instar el ejercicio de la acción penal pública con el asesoramiento o representación de instituciones oficiales o privadas sin fines de lucro de protección o ayuda a las víctimas. Si ella fuere mayor de dieciséis años podrá proponer un avenimiento con el imputado. El Tribunal podrá excepcionalmente aceptar la propuesta que haya sido libremente formulada y en condiciones de plena igualdad, cuando, en consideración a la especial y comprobada relación afectiva preexistente, considere que es un modo más equitativo de armonizar el conflicto con mejor resguardo del interés de la víctima. En tal caso la acción penal quedará extinguida; o en el mismo supuesto también podrá disponer la aplicación al caso de lo dispuesto por los artículos 76 ter y 76 quáter del Código Penal.\n(Artículo sustituido por art. 15 de la Ley N° 25.087 B.O. 14/5/1999)"
 },
 {
  "id": "CP-133",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 133",
  "titulo": "Delitos contra la integridad sexual (rúbrica del título sustituida por art. 1° de la ley n° 25.087 b.o. 14/5/1999) (nota infoleg: capítulo i y su rúbrica: adulterio, derogados por art. 3° de la ley n° 24.453 b.o. 7/3/1995)",
  "tags": "133 delitos contra la integridad sexual (rubrica del titulo sustituida por art. 1 de ley n 25.087 b.o. 14/5/1999) (nota infoleg: capitulo i y su rubrica: adulterio, derogados 3 24.453 7/3/1995)",
  "texto": "Los ascendientes, descendientes, cónyuges, convivientes, afines en línea recta, hermanos, tutores, curadores y cualesquiera persona que, con abuso de una relación de dependencia, de autoridad, de poder, de confianza o encargo, cooperaren a la perpetración de los delitos comprendidos en este título serán reprimidos con la pena de los autores.\n(Artículo sustituido por art. 13 de la Ley N° 25.087 B.O.14/5/1999)\n(Nota Infoleg: rúbricas de los capítulos II, III, IV y V derogadas por art. 1° de la Ley N°\n25.087 B.O.14/5/1999)"
 },
 {
  "id": "CP-134",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 134",
  "titulo": "Delitos contra el estado civil · Matrimonios ilegales",
  "tags": "134 delitos contra el estado civil matrimonios ilegales",
  "texto": "Serán reprimidos con prisión de uno a cuatro años, los que contrajeren matrimonio sabiendo ambos que existe impedimento que cause su nulidad absoluta."
 },
 {
  "id": "CP-135",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 135",
  "titulo": "Delitos contra el estado civil · Matrimonios ilegales",
  "tags": "135 delitos contra el estado civil matrimonios ilegales",
  "texto": "Serán reprimidos con prisión de dos a seis años:\n1º. El que contrajere matrimonio cuando, sabiendo que existe impedimento que cause su nulidad absoluta, ocultare esta circunstancia al otro contrayente;\n2º. El que engañando a una persona, simulare matrimonio con ella."
 },
 {
  "id": "CP-136",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 136",
  "titulo": "Delitos contra el estado civil · Matrimonios ilegales",
  "tags": "136 delitos contra el estado civil matrimonios ilegales",
  "texto": "El oficial público que a sabiendas autorizare un matrimonio de los comprendidos en los artículos anteriores, sufrirá, en su caso, la pena que en ellos se determina.\nSi lo autorizare sin saberlo, cuando su ignorancia provenga de no haber llenado los requisitos que la ley prescribe para la celebración del matrimonio, la pena será de multa de setecientos cincuenta a pesos doce mil quinientos e inhabilitación especial por seis meses a dos años.\nSufrirá multa de pesos setecientos cincuenta a pesos doce mil quinientos el oficial público que, fuera de los demás casos de este artículo, procediere a la celebración de un matrimonio sin haber observado todas las formalidades exigidas por la ley.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-137",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 137",
  "titulo": "Delitos contra el estado civil · Matrimonios ilegales",
  "tags": "137 delitos contra el estado civil matrimonios ilegales",
  "texto": "En la misma pena incurrirá el representante legítimo de un menor impúber que diere el consentimiento para el matrimonio del mismo."
 },
 {
  "id": "CP-138",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 138",
  "titulo": "Delitos contra el estado civil · Supresión y suposición del estado civil y de la Identidad",
  "tags": "138 delitos contra el estado civil supresion y suposicion del de la identidad",
  "texto": "Se aplicará prisión de 1 a 4 años al que, por un acto cualquiera, hiciere incierto, alterare o suprimiere el estado civil de otro.\n(Artículo sustituido por art. 5° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-139",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 139",
  "titulo": "Delitos contra el estado civil · Supresión y suposición del estado civil y de la Identidad",
  "tags": "139 delitos contra el estado civil supresion y suposicion del de la identidad",
  "texto": "Se impondrá prisión de 2 a 6 años:\n1. A la mujer que fingiere preñez o parto para dar a su supuesto hijo derechos que no le correspondan.\n2. Al que, por un acto cualquiera, hiciere incierto, alterare o suprimiere la identidad de un menor de 10 años, y el que lo retuviere u ocultare.\n(Artículo sustituido por art. 6° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-139-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 139 bis",
  "titulo": "Delitos contra el estado civil · Supresión y suposición del estado civil y de la Identidad",
  "tags": "139 bis delitos contra el estado civil supresion y suposicion del de la identidad",
  "texto": "Será reprimido con reclusión o prisión de 3 a 10 años, el que facilitare, promoviere o de cualquier modo intermediare en la perpetración de los delitos comprendidos en este Capítulo, haya mediado o no precio o promesa remuneratoria o ejercido amenaza o abuso de autoridad.\nIncurrirán en las penas establecidas en el párrafo anterior y sufrirán, además, inhabilitación especial por doble tiempo que el de la condena, el funcionario público o profesional de la salud que cometa alguna de las conductas previstas en este Capítulo.\n(Artículo incorporado por art. 7° de la Ley N° 24.410 B.O. 2/1/1995) DELITOS CONTRA LA LIBERTAD"
 },
 {
  "id": "CP-140",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 140",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "140 delitos contra el estado civil la libertad individual",
  "texto": "Serán reprimidos con reclusión o prisión de tres a quince años, el que redujere a una persona a servidumbre o a otra condición análoga y el que la recibiere en tal condición para mantenerla en ella."
 },
 {
  "id": "CP-141",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 141",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "141 delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con prisión o reclusión de seis meses a tres años; el que ilegalmente privare a otro de su libertad personal."
 },
 {
  "id": "CP-142",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 142",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "142 delitos contra el estado civil la libertad individual",
  "texto": "Se aplicará prisión o reclusión de dos a seis años, al que privare a otro de su libertad personal, cuando concurra alguna de las circunstancias siguientes:\n1. Si el hecho se cometiere con violencias o amenazas o con fines religiosos o de venganza;\n2. Si el hecho se cometiere en la persona de un ascendiente, de un hermano, del cónyuge o de otro individuo a quien se deba respeto particular;\n3. Si resultare grave daño a la persona, a la salud o a los negocios del ofendido, siempre que el hecho no importare otro delito por el cual la ley imponga pena mayor;\n4. Si el hecho se cometiere simulando autoridad pública u orden de autoridad pública;\n5. Si la privación de la libertad durare más de un mes."
 },
 {
  "id": "CP-142-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 142 bis",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "142 bis delitos contra el estado civil la libertad individual",
  "texto": "Se impondrá prisión o reclusión de cinco (5) a quince (15) años, al que sustrajere, retuviere u ocultare a una persona con el fin de obligar a la víctima o a un tercero, a hacer, no hacer, o tolerar algo contra su voluntad. Si el autor lograre su propósito, el mínimo de la pena se elevará a ocho (8) años.\nLa pena será de diez (10) a veinticinco (25) años de prisión o reclusión:\n1. Si la víctima fuese una mujer embarazada; un menor de dieciocho (18) años de edad; o un mayor de setenta (70) años de edad.\n2. Si el hecho se cometiere en la persona de un ascendiente; de un hermano; del cónyuge o conviviente; o de otro individuo a quien se deba respeto particular.\n3. Si se causare a la víctima lesiones graves o gravísimas.\n4. Cuando la víctima sea una persona discapacitada, enferma o que no pueda valerse por sí misma.\n5. Cuando el agente sea funcionario o empleado público o pertenezca o haya pertenecido al momento de comisión del hecho a una fuerza armada, de seguridad u organismo de inteligencia del Estado. (Inciso sustituido por art. 3° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)\n6. Cuando participaran en el hecho tres (3) o más personas.\nLa pena será de quince (15) a veinticinco (25) años de prisión a reclusión si del hecho resultara la muerte de la persona ofendida, como consecuencia no querida por el autor.\nLa pena será de prisión o reclusión perpetua si se causare intencionalmente la muerte de la persona ofendida.\nLa pena del partícipe que, desvinculándose de los otros, se esforzare de modo que la víctima recupere la libertad, sin que tal resultado fuese la consecuencia del logro del propósito del autor, se reducirá de un tercio a la mitad.\n(Artículo sustituido por art. 3° de la Ley N° 25.742 B.O. 20/6/2003)"
 },
 {
  "id": "CP-143",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 143",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "143 delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con reclusión o prisión de uno a tres años e inhabilitación especial por doble tiempo:\n1º. El funcionario que retuviera a un detenido o preso, cuya soltura haya debido decretar o ejecutar;\n2º. El funcionario que prolongare indebidamente la detención de una persona, sin ponerla a disposición del juez competente;\n3º. El funcionario que incomunicare indebidamente a un detenido;\n4º. El jefe de prisión u otro establecimiento penal, o el que lo reemplace, que recibiera algún reo sin testimonio de la sentencia firme en que se le hubiere impuesto la pena o lo colocare en lugares del establecimiento que no sean los señalados al efecto;\n5º. El alcaide o empleado de las cárceles de detenidos y seguridad que recibiere un preso sin orden de autoridad competente, salvo el caso de flagrante delito;\n6º. El funcionario competente que teniendo noticias de una detención ilegal omitiere, retardare o rehusare hacerla cesar o dar cuenta a la autoridad que deba resolver."
 },
 {
  "id": "CP-144",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 144",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "144 delitos contra el estado civil la libertad individual",
  "texto": "Cuando en los casos del artículo anterior concurriere alguna de las circunstancias enumeradas en los incisos 1, 2, 3 y 5 del artículo 142, el máximo de la pena privativa de la libertad se elevará a cinco años."
 },
 {
  "id": "CP-144-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 144 bis",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "144 bis delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con prisión o reclusión de uno a cinco años e inhabilitación especial por doble tiempo:\n1. El funcionario público que, con abuso de sus funciones o sin las formalidades prescriptas por la ley, privase a alguno de su libertad personal;\n2. El funcionario que desempeñando un acto de servicio cometiera cualquier vejación contra las personas o les aplicare apremios ilegales;\n3. El funcionario público que impusiere a los presos que guarde, severidades, vejaciones, o apremios ilegales.\nSi concurriere alguna de las circunstancias enumeradas en los incisos 1, 2, 3 y 5 del artículo 142, la pena privativa de la libertad será de reclusión o prisión de dos a seis años."
 },
 {
  "id": "CP-144-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 144 ter",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "144 ter delitos contra el estado civil la libertad individual",
  "texto": "1. Será reprimido con reclusión o prisión de ocho a veinticinco años e inhabilitación absoluta y perpetua el funcionario público que impusiere a personas, legítima o ilegítimamente privadas de su libertad, cualquier clase de tortura.\nEs indiferente que la víctima se encuentre jurídicamente a cargo del funcionario, bastando que éste tenga sobre aquélla poder de hecho.\nIgual pena se impondrá a particulares que ejecutaren los hechos descritos.\n2. Si con motivo u ocasión de la tortura resultare la muerte de la víctima, la pena privativa de libertad será de reclusión o prisión perpetua. Si se causare alguna de las lesiones previstas en el artículo 91, la pena privativa de libertad será de reclusión o prisión de diez a veinticinco años.\n3. Por tortura se entenderá no solamente los tormentos físicos, sino también la imposición de sufrimientos psíquicos, cuando éstos tengan gravedad suficiente."
 },
 {
  "id": "CP-144-quater",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 144 quater",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "144 quater delitos contra el estado civil la libertad individual",
  "texto": "1º. Se impondrá prisión de tres a diez años al funcionario que omitiese evitar la comisión de alguno de los hechos del artículo anterior, cuando tuviese competencia para ello.\n2º. La pena será de uno a cinco años de prisión para el funcionario que en razón de sus funciones tomase conocimiento de la comisión de alguno de los hechos del artículo anterior y, careciendo de la competencia a que alude el inciso precedente, omitiese denunciar dentro de las veinticuatro horas el hecho ante el funcionario, ministerio público o juez competente. Si el funcionario fuera médico se le impondrá, además, inhabilitación especial para el ejercicio de su profesión por doble tiempo de la pena de prisión.\n3º. Sufrirá la pena prevista en el inciso 1º de este artículo el juez que, tomando conocimiento en razón de su función de alguno de los hechos a que se refiere el artículo anterior, no instruyere sumario o no denunciare el hecho al juez competente dentro de las veinticuatro horas.\n4º. En los casos previstos en este artículo, se impondrá, además, inhabilitación especial perpetua para desempeñarse en cargos públicos. La inhabilitación comprenderá la de tener o portar armas de todo tipo."
 },
 {
  "id": "CP-144-quinto",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 144 quinto",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "144 quinto delitos contra el estado civil la libertad individual",
  "texto": "Si se ejecutase el hecho previsto en el artículo 144 tercero, se impondrá prisión de seis meses a dos años e inhabilitación especial de tres a seis años al funcionario a cargo de la repartición, establecimiento, departamento, dependencia o cualquier otro organismo, si las circunstancias del caso permiten establecer que el hecho no se hubiese cometido de haber mediado la debida vigilancia o adoptado los recaudos necesarios por dicho funcionario."
 },
 {
  "id": "CP-145",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 145",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "145 delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con prisión de dos a seis años, el que condujere a una persona fuera de las fronteras de la República, con el propósito de someterla ilegalmente al poder de otro o de alistarla en un ejército extranjero."
 },
 {
  "id": "CP-145-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 145 bis",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "145 bis delitos contra el estado civil la libertad individual",
  "texto": "El que captare, transportare o trasladare, dentro del país o desde o hacia el exterior, acogiere o recibiere personas mayores de dieciocho años de edad, cuando mediare engaño, fraude, violencia, amenaza o cualquier otro medio de intimidación o coerción, abuso de autoridad o de una situación de vulnerabilidad, concesión o recepción de pagos o beneficios para obtener el consentimiento de una persona que tenga autoridad sobre la víctima, con fines de explotación, será reprimido con prisión de TRES (3) a SEIS (6) años.\nLa pena será de CUATRO (4) a DIEZ (10) años de prisión cuando:\n1. El autor fuere ascendiente, cónyuge, afín en línea recta, hermano, tutor, persona conviviente, curador, encargado de la educación o guarda, ministro de algún culto reconocido o no, o funcionario público;\n2. El hecho fuere cometido por TRES (3) o más personas en forma organizada;\n3. Las víctimas fueren TRES (3) o más.\n(Artículo incorporado por art. 10 de la Ley N° 26.364, B.O. 30/4/2008)"
 },
 {
  "id": "CP-145-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 145 ter",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "145 ter delitos contra el estado civil la libertad individual",
  "texto": "El que ofreciere, captare, transportare o trasladare, dentro del país o desde o hacia el exterior, acogiere o recibiere personas menores de DIECIOCHO (18) años de edad, con fines de explotación, será reprimido con prisión de CUATRO (4) a DIEZ (10) años.\nLa pena será de SEIS (6) a QUINCE (15) años de prisión cuando la víctima fuere menor de TRECE (13) años.\nEn cualquiera de los supuestos anteriores, la pena será de DIEZ (10) a QUINCE (15) años de prisión, cuando:\n1. Mediare engaño, fraude, violencia, amenaza o cualquier otro medio de intimidación o coerción, abuso de autoridad o de una situación de vulnerabilidad, concesión o recepción de pagos o beneficios para obtener el consentimiento de una persona que tenga autoridad sobre la víctima;\n2. El autor fuere ascendiente, cónyuge, afín en línea recta, hermano, tutor, persona conviviente, curador, encargado de la educación o guarda, ministro de algún culto reconocido o no, o funcionario público;\n3. El hecho fuere cometido por TRES (3) o más personas en forma organizada;\n4. Las víctimas fueren TRES (3) o más.\n(Artículo incorporado por art. 11 de la Ley N° 26.364, B.O. 30/4/2008)"
 },
 {
  "id": "CP-146",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 146",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "146 delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con prisión o reclusión de 5 a 15 años, el que sustrajere a un menor de 10 años del poder de sus padres, tutor o persona encargada de él, y el que lo retuviere u ocultare.\n(Artículo sustituido por art. 8° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-147",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 147",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "147 delitos contra el estado civil la libertad individual",
  "texto": "En la misma pena incurrirá el que, hallándose encargado de la persona de un menor de diez años, no lo presentara a los padres o guardadores que lo solicitaren o no diere razón satisfactoria de su desaparición."
 },
 {
  "id": "CP-148",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 148",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "148 delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con prisión de un mes a un año, el que indujere a un mayor de diez años y menor de quince, a fugar de casa de sus padres, guardadores o encargados de su persona."
 },
 {
  "id": "CP-149",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 149",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "149 delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con prisión de un mes a un año, el que ocultare a las investigaciones de la justicia o de la policía, a un menor de quince años que se hubiere substraído a la potestad o guarda a que estaba legalmente sometido.\nLa pena será de seis meses a dos años, si el menor no tuviera diez años."
 },
 {
  "id": "CP-149-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 149 bis",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "149 bis delitos contra el estado civil la libertad individual",
  "texto": "Será reprimido con prisión de seis meses a dos años el que hiciere uso de amenazas para alarmar o amedrentar a una o más personas. En este caso la pena será de uno a tres años de prisión si se emplearen armas o si las amenazas fueren anónimas. Será reprimido con prisión o reclusión de dos a cuatro años el que hiciere uso de amenazas con el propósito de obligar a otro a hacer, no hacer o tolerar algo contra su voluntad."
 },
 {
  "id": "CP-149-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 149 ter",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad individual",
  "tags": "149 ter delitos contra el estado civil la libertad individual",
  "texto": "En el caso del último apartado del artículo anterior, la pena será:\n1) De tres a seis años de prisión o reclusión si se emplearen armas o si las amenazas fueren anónimas; 2) De cinco a diez años de prisión o reclusión en los siguientes casos:\na) Si las amenazas tuvieren como propósito la obtención de alguna medida o concesión por parte de cualquier miembro de los poderes públicos;\nb) Si las amenazas tuvieren como propósito el de compeler a una persona a hacer abandono del país, de una provincia o de los lugares de su residencia habitual o de trabajo."
 },
 {
  "id": "CP-150",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 150",
  "titulo": "Delitos contra el estado civil · Violación de domicilio",
  "tags": "150 delitos contra el estado civil violacion de domicilio",
  "texto": "Será reprimido con prisión de seis meses a dos años, si no resultare otro delito más severamente penado, el que entrare en morada o casa de negocio ajena, en sus dependencias o en el recinto habitado por otro, contra la voluntad expresa o presunta de quien tenga derecho de excluirlo."
 },
 {
  "id": "CP-151",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 151",
  "titulo": "Delitos contra el estado civil · Violación de domicilio",
  "tags": "151 delitos contra el estado civil violacion de domicilio",
  "texto": "Se impondrá la misma pena e inhabilitación especial de seis meses a dos años, al funcionario público o agente de la autoridad que allanare un domicilio sin las formalidades prescriptas por la ley o fuera de los casos que ella determina."
 },
 {
  "id": "CP-152",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 152",
  "titulo": "Delitos contra el estado civil · Violación de domicilio",
  "tags": "152 delitos contra el estado civil violacion de domicilio",
  "texto": "Las disposiciones de los artículos anteriores no se aplicarán al que entrare en los sitios expresados, para evitar un mal grave a sí mismo, a los moradores o a un tercero, ni al que lo hiciere para cumplir un deber de humanidad o prestar auxilio a la justicia.\n(Epígrafe sustituido por art. 3° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-153",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 153",
  "titulo": "Delitos contra el estado civil · Violación de Secretos y de la Privacidad",
  "tags": "153 delitos contra el estado civil violacion de secretos y la privacidad",
  "texto": "Será reprimido con prisión de quince (15) días a seis (6) meses el que abriere o accediere indebidamente a una comunicación electrónica, una carta, un pliego cerrado, un despacho telegráfico, telefónico o de otra naturaleza, que no le esté dirigido; o se apoderare indebidamente de una comunicación electrónica, una carta, un pliego, un despacho u otro papel privado, aunque no esté cerrado; o indebidamente suprimiere o desviare de su destino una correspondencia o una comunicación electrónica que no le esté dirigida.\nEn la misma pena incurrirá el que indebidamente interceptare o captare comunicaciones electrónicas o telecomunicaciones provenientes de cualquier sistema de carácter privado o de acceso restringido.\nLa pena será de prisión de un (1) mes a un (1) año, si el autor además comunicare a otro o publicare el contenido de la carta, escrito, despacho o comunicación electrónica.\nSi el hecho lo cometiere un funcionario público que abusare de sus funciones, sufrirá además, inhabilitación especial por el doble del tiempo de la condena.\n(Artículo sustituido por art. 4° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-153-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 153 bis",
  "titulo": "Delitos contra el estado civil · Violación de Secretos y de la Privacidad",
  "tags": "153 bis delitos contra el estado civil violacion de secretos y la privacidad",
  "texto": "Será reprimido con prisión de quince (15) días a seis (6) meses, si no resultare un delito más severamente penado, el que a sabiendas accediere por cualquier medio, sin la debida autorización o excediendo la que posea, a un sistema o dato informático de acceso restringido.\nLa pena será de un (1) mes a un (1) año de prisión cuando el acceso fuese en perjuicio de un sistema o dato informático de un organismo público estatal o de un proveedor de servicios públicos o de servicios financieros.\n(Artículo incorporado por art. 5° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-154",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 154",
  "titulo": "Delitos contra el estado civil · Violación de Secretos y de la Privacidad",
  "tags": "154 delitos contra el estado civil violacion de secretos y la privacidad",
  "texto": "Será reprimido con prisión de uno a cuatro años, el empleado de correos o telégrafos que, abusando de su empleo, se apoderare de una carta, de un pliego, de un telegrama o de otra pieza de correspondencia, se impusiere de su contenido, la entregare o comunicare a otro que no sea el destinatario, la suprimiere, la ocultare o cambiare su texto."
 },
 {
  "id": "CP-155",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 155",
  "titulo": "Delitos contra el estado civil · Violación de Secretos y de la Privacidad",
  "tags": "155 delitos contra el estado civil violacion de secretos y la privacidad",
  "texto": "Será reprimido con multa de pesos un mil quinientos ($ 1.500) a pesos cien mil ($ 100.000), el que hallándose en posesión de una correspondencia, una comunicación electrónica, un pliego cerrado, un despacho telegráfico, telefónico o de otra naturaleza, no destinados a la publicidad, los hiciere publicar indebidamente, si el hecho causare o pudiere causar perjuicios a terceros.\nEstá exento de responsabilidad penal el que hubiere obrado con el propósito inequívoco de proteger un interés público.\n(Artículo sustituido por art. 6° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-156",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 156",
  "titulo": "Delitos contra el estado civil · Violación de Secretos y de la Privacidad",
  "tags": "156 delitos contra el estado civil violacion de secretos y la privacidad",
  "texto": "Será reprimido con multa de pesos mil quinientos a pesos noventa mil e inhabilitación especial, en su caso, por seis meses a tres años, el que teniendo noticia, por razón de su estado, oficio, empleo, profesión o arte, de un secreto cuya divulgación pueda causar daño, lo revelare sin justa causa.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-157",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 157",
  "titulo": "Delitos contra el estado civil · Violación de Secretos y de la Privacidad",
  "tags": "157 delitos contra el estado civil violacion de secretos y la privacidad",
  "texto": "Será reprimido con prisión de un (1) mes a dos (2) años e inhabilitación especial de un (1) a cuatro (4) años, el funcionario público que revelare hechos, actuaciones, documentos o datos, que por ley deben ser secretos.\n(Artículo sustituido por art. 7° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-157-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 157 bis",
  "titulo": "Delitos contra el estado civil · Violación de Secretos y de la Privacidad",
  "tags": "157 bis delitos contra el estado civil violacion de secretos y la privacidad",
  "texto": "Será reprimido con la pena de prisión de un (1) mes a dos (2) años el que:\n1. A sabiendas e ilegítimamente, o violando sistemas de confidencialidad y seguridad de datos, accediere, de cualquier forma, a un banco de datos personales;\n2. Ilegítimamente proporcionare o revelare a otro información registrada en un archivo o en un banco de datos personales cuyo secreto estuviere obligado a preservar por disposición de la ley.\n3. Ilegítimamente insertare o hiciere insertar datos en un archivo de datos personales.\nCuando el autor sea funcionario público sufrirá, además, pena de inhabilitación especial de un\n(1) a cuatro (4) años.\n(Artículo sustituido por art. 8° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-158",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 158",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad de trabajo y asociación",
  "tags": "158 delitos contra el estado civil la libertad de trabajo y asociacion",
  "texto": "Será reprimido con prisión de un mes a un año; el obrero que ejerciere violencia sobre otro para compelerlo a tomar parte en una huelga o boycott. La misma pena sufrirá el patrón, empresario o empleado que, por sí o por cuenta de alguien, ejerciere coacción para obligar a otro a tomar parte en un lock-out y a abandonar o ingresar a una sociedad obrera o patronal determinada."
 },
 {
  "id": "CP-159",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 159",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad de trabajo y asociación",
  "tags": "159 delitos contra el estado civil la libertad de trabajo y asociacion",
  "texto": "Será reprimido con multa de pesos dos mil quinientos a pesos treinta mil, el que, por maquinaciones fraudulentas, sospechas malévolas o cualquier medio de propaganda desleal, tratare de desviar, en su provecho, la clientela de un establecimiento comercial o industrial.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-160",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 160",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad de reunión",
  "tags": "160 delitos contra el estado civil la libertad de reunion",
  "texto": "Será reprimido con prisión de quince días a tres meses, el que impidiere materialmente o turbare una reunión lícita, con insultos o amenazas al orador o a la institución organizadora del acto."
 },
 {
  "id": "CP-161",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 161",
  "titulo": "Delitos contra el estado civil · Delitos contra la libertad de prensa",
  "tags": "161 delitos contra el estado civil la libertad de prensa",
  "texto": "Sufrirá prisión de uno a seis meses, el que impidiere o estorbare la libre circulación de un libro o periódico."
 },
 {
  "id": "CP-162",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 162",
  "titulo": "Delitos contra la propiedad · Hurto",
  "tags": "162 delitos contra la propiedad hurto",
  "texto": "Será reprimido con prisión de un mes a dos años, el que se apoderare ilegítimamente de una cosa mueble, total o parcialmente ajena.ARTICULO 163. - Se aplicará prisión de uno a seis años en los casos siguientes:\n1º Cuando el hurto fuere de productos separados del suelo o de máquinas, instrumentos de trabajo o de productos agroquímicos, fertilizantes u otros insumos similares, dejados en el campo, o de alambres u otros elementos de los cercos.\n(Inciso sustituido por art. 2° de la Ley N° 25.890 B.O.21/5/2004)\n2º Cuando el hurto se cometiere con ocasión de un incendio, explosión, inundación, naufragio, accidente de ferrocarril, asonada o motín o aprovechando las facilidades provenientes de cualquier otro desastre o conmoción pública o de un infortunio particular del damnificado;\n3º Cuando se hiciere uso de ganzúa, llave falsa u otro instrumento semejante o de llave verdadera que hubiere sido substraída, hallada o retenida; (Inciso sustituido por art. 1° de la Ley N° 24.721 B.O. 18/11/1996)\n4º Cuando se perpetrare con escalamiento.\n5º Cuando el hurto fuese de mercaderías u otras cosas muebles transportadas por cualquier medio y se cometiere entre el momento de su carga y el de su destino o entrega, o durante las escalas que se realizaren. . (Inciso incorporado por art. 1° de la Ley N° 23.468 B.O. 26/1/1987)\n6º Cuando el hurto fuere de vehículos dejados en la vía pública o en lugares de acceso público. . (Inciso incorporado por art. 1° de la Ley N° 24.721 B.O. 18/11/1996)"
 },
 {
  "id": "CP-163-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 163 bis",
  "titulo": "Delitos contra la propiedad · Hurto",
  "tags": "163 bis delitos contra la propiedad hurto",
  "texto": "En los casos enunciados en el presente Capítulo, la pena se aumentará en un tercio en su mínimo y en su máximo, cuando quien ejecutare el delito fuere miembro integrante de las fuerzas de seguridad, policiales o del servicio penitenciario.\n(Artículo incorporado por art. 2° de la Ley N° 25.816 B.O.9/12/2003)"
 },
 {
  "id": "CP-164",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 164",
  "titulo": "Delitos contra la propiedad · Robo",
  "tags": "164 delitos contra la propiedad robo",
  "texto": "Será reprimido con prisión de un mes a seis años, el que se apoderare ilegítimamente de una cosa mueble, total o parcialmente ajena, con fuerza en las cosas o con violencia física en las personas, sea que la violencia tenga lugar antes del robo para facilitarlo, en el acto de cometerlo o después de cometido para procurar su impunidad."
 },
 {
  "id": "CP-165",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 165",
  "titulo": "Delitos contra la propiedad · Robo",
  "tags": "165 delitos contra la propiedad robo",
  "texto": "Se impondrá reclusión o prisión de diez a veinticinco años, si con motivo u ocasión del robo resultare un homicidio."
 },
 {
  "id": "CP-166",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 166",
  "titulo": "Delitos contra la propiedad · Robo",
  "tags": "166 delitos contra la propiedad robo",
  "texto": "Se aplicará reclusión o prisión de CINCO a QUINCE años:\n1. Si por las violencias ejercidas para realizar el robo, se causare alguna de las lesiones previstas en los artículos 90 y 91.\n2. Si el robo se cometiere con armas, o en despoblado y en banda.\nSi el arma utilizada fuera de fuego, la escala penal prevista se elevará en un tercio en su mínimo y en su máximo.\nSi se cometiere el robo con un arma de fuego cuya aptitud para el disparo no pudiera tenerse de ningún modo por acreditada, o con un arma de utilería, la pena será de TRES a DIEZ años de reclusión o prisión.\n(Artículo sustituido por art. 1° de la Ley N° 25.882 B.O. 26/4/2004)"
 },
 {
  "id": "CP-167",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 167",
  "titulo": "Delitos contra la propiedad · Robo",
  "tags": "167 delitos contra la propiedad robo",
  "texto": "Se aplicará reclusión o prisión de tres a diez años:\n1º. Si se cometiere el robo en despoblado;\n2º. Si se cometiere en lugares poblados y en banda;\n3º. Si se perpetrare el robo con perforación o fractura de pared, cerco, techo o piso, puerta o ventana de un lugar habitado o sus dependencias inmediatas;\n4º. Si concurriere alguna de las circunstancias enumeradas en el artículo 163."
 },
 {
  "id": "CP-167-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 167 bis",
  "titulo": "Delitos contra la propiedad · Robo",
  "tags": "167 bis delitos contra la propiedad robo",
  "texto": "En los casos enunciados en el presente Capítulo, la pena se aumentará en un tercio en su mínimo y en su máximo, cuando quien ejecutare el delito fuere miembro integrante de las fuerzas de seguridad, policiales o del servicio penitenciario.\n(Artículo incorporado por art. 3° de la Ley N° 25.816 B.O.9/12/2003)"
 },
 {
  "id": "CP-167-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 167 ter",
  "titulo": "Delitos contra la propiedad · (Capítulo incorporado por art",
  "tags": "167 ter delitos contra la propiedad (capitulo incorporado por art",
  "texto": "Será reprimido con prisión de DOS (2) a SEIS (6) años el que se apoderare ilegítimamente de UNA (1) o más cabezas de ganado mayor o menor, total o parcialmente ajeno, que se encontrare en establecimientos rurales o, en ocasión de su transporte, desde el momento de su carga hasta el de su destino o entrega, incluyendo las escalas que se realicen durante el trayecto.\nLa pena será de TRES (3) a OCHO (8) años de prisión si el abigeato fuere de CINCO (5) o más cabezas de ganado mayor o menor y se utilizare un medio motorizado para su transporte.\n(Artículo incorporado por art. 3° de la Ley N° 25.890 B.O.21/5/2004)"
 },
 {
  "id": "CP-167-quater",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 167 quater",
  "titulo": "Delitos contra la propiedad · (Capítulo incorporado por art",
  "tags": "167 quater delitos contra la propiedad (capitulo incorporado por art",
  "texto": "Se aplicará reclusión o prisión de CUATRO (4) a DIEZ (10) años cuando en el abigeato concurriere alguna de las siguientes circunstancias:\n1.- El apoderamiento se realizare en las condiciones previstas en el artículo 164.\n2.- Se alteraren, suprimieren o falsificaren marcas o señales utilizadas para la identificación del animal.\n3.- Se falsificaren o se utilizaren certificados de adquisición, guías de tránsito, boletos de marca o señal, o documentación equivalente, falsos.\n4.- Participare en el hecho una persona que se dedique a la crianza, cuidado, faena, elaboración, comercialización o transporte de ganado o de productos o subproductos de origen animal.\n5.- Participare en el hecho un funcionario público quien, violando los deberes a su cargo o abusando de sus funciones, facilitare directa o indirectamente su comisión.\n6.- Participaren en el hecho TRES (3) o más personas.\n(Artículo incorporado por art. 3° de la Ley N° 25.890 B.O.21/5/2004)"
 },
 {
  "id": "CP-167-quinque",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 167 quinque",
  "titulo": "Delitos contra la propiedad · (Capítulo incorporado por art",
  "tags": "167 quinque delitos contra la propiedad (capitulo incorporado por art",
  "texto": "En caso de condena por un delito previsto en este Capítulo, el culpable, si fuere funcionario público o reuniere las condiciones personales descriptas en el artículo 167 quater inciso 4, sufrirá, además, inhabilitación especial por el doble del tiempo de la condena.\nEn todos los casos antes previstos también se impondrá conjuntamente una multa equivalente de DOS (2) a DIEZ (10) veces del valor del ganado sustraído\".\n(Artículo incorporado por art. 3° de la Ley N° 25.890 B.O.21/5/2004)"
 },
 {
  "id": "CP-168",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 168",
  "titulo": "Delitos contra la propiedad · Extorsión",
  "tags": "168 delitos contra la propiedad extorsion",
  "texto": "Será reprimido con reclusión o prisión de cinco a diez años, el que con intimidación o simulando autoridad pública o falsa orden de la misma, obligue a otro a entregar, enviar, depositar o poner a su disposición o a la de un tercero, cosas, dinero o documentos que produzcan efectos jurídicos.\nIncurrirá en la misma pena el que por los mismos medios o con violencia, obligue a otro a suscribir o destruir documentos de obligación o de crédito."
 },
 {
  "id": "CP-169",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 169",
  "titulo": "Delitos contra la propiedad · Extorsión",
  "tags": "169 delitos contra la propiedad extorsion",
  "texto": "Será reprimido con prisión o reclusión de tres a ocho años, el que, por amenaza de imputaciones contra el honor o de violación de secretos, cometiere alguno de los hechos expresados en el artículo precedente."
 },
 {
  "id": "CP-170",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 170",
  "titulo": "Delitos contra la propiedad · Extorsión",
  "tags": "170 delitos contra la propiedad extorsion",
  "texto": "Se impondrá reclusión o prisión de cinco (5) a quince (15) años, al que sustrajere, retuviere u ocultare a una persona para sacar rescate. Si el autor lograre su propósito, el mínimo de la pena se elevará a ocho (8) años.\nLa pena será de diez (10) a veinticinco (25) años de prisión o reclusión:\n1. Si la víctima fuese una mujer embarazada; un menor de dieciocho (18) años de edad o un mayor de setenta (70) años de edad.\n2. Si el hecho se cometiere en la persona de un ascendiente; de un hermano; del cónyuge o conviviente; o de otro individuo a quien se deba respeto particular.\n3. Si se causare a la víctima lesiones graves o gravísimas.\n4. Cuando la víctima sea una persona discapacitada; enferma; o que no pueda valerse por sí misma.\n5. Cuando el agente sea funcionario o empleado público; o pertenezca o haya pertenecido a alguna fuerza de seguridad u organismo de inteligencia del Estado.\n6. Cuando participaran en el hecho tres (3) o más personas.\nLa pena será de quince (15) a veinticinco (25) años de prisión o reclusión si del hecho resultare la muerte de la persona ofendida, como consecuencia no querida por el autor.\nLa pena será de prisión o reclusión perpetua si se causara intencionalmente la muerte de la persona ofendida.\nLa pena del partícipe que, desvinculándose de los otros, se esforzare de modo que la víctima recupere la libertad, sin que tal resultado fuese la consecuencia del pago del precio de la libertad, se reducirá de un tercio a la mitad.\n(Artículo sustituido por art. 4° de la Ley N° 25.742 B.O. 20/6/2003)"
 },
 {
  "id": "CP-171",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 171",
  "titulo": "Delitos contra la propiedad · Extorsión",
  "tags": "171 delitos contra la propiedad extorsion",
  "texto": "Sufrirá prisión de dos a seis años, el que substrajere un cadáver para hacerse pagar su devolución."
 },
 {
  "id": "CP-172",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 172",
  "titulo": "Delitos contra la propiedad · Estafas y otras defraudaciones",
  "tags": "172 delitos contra la propiedad estafas y otras defraudaciones",
  "texto": "Será reprimido con prisión de un mes a seis años, el que defraudare a otro con nombre supuesto, calidad simulada, falsos títulos, influencia mentida, abuso de confianza o aparentando bienes, crédito, comisión, empresa o negociación o valiéndose de cualquier otro ardid o engaño."
 },
 {
  "id": "CP-173",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 173",
  "titulo": "Delitos contra la propiedad · Estafas y otras defraudaciones",
  "tags": "173 delitos contra la propiedad estafas y otras defraudaciones",
  "texto": "Sin perjuicio de la disposición general del artículo precedente, se considerarán casos especiales de defraudación y sufrirán la pena que él establece:\n1. El que defraudare a otro en la substancia, calidad o cantidad de las cosas que le entregue en virtud de contrato o de un título obligatorio;\n2. El que con perjuicio de otro se negare a restituir o no restituyere a su debido tiempo, dinero, efectos o cualquier otra cosa mueble que se le haya dado en depósito, comisión, administración u otro título que produzca obligación de entregar o devolver;\n3. El que defraudare, haciendo suscribir con engaño algún documento;\n4. El que cometiere alguna defraudación abusando de firma en blanco, extendiendo con ella algún documento en perjuicio del mismo que la dio o de tercero;\n5. El dueño de una cosa mueble que la sustrajere de quien la tenga legítimamente en su poder, con perjuicio del mismo o de tercero;\n6. El que otorgare en perjuicio de otro, un contrato simulado o falsos recibidos;\n7. El que, por disposición de la ley, de la autoridad o por un acto jurídico, tuviera a su cargo el manejo, la administración o el cuidado de bienes o intereses pecuniarios ajenos, y con el fin de procurar para sí o para un tercero un lucro indebido o para causar daño, violando sus deberes perjudicare los intereses confiados u obligare abusivamente al titular de éstos;\n8. El que cometiere defraudación, substituyendo, ocultando o mutilando algún proceso, expediente, documento u otro papel importante;\n9. El que vendiere o gravare como bienes libres, los que fueren litigiosos o estuvieren embargados o gravados; y el que vendiere, gravare o arrendare como propios, bienes ajenos;\n10. El que defraudare, con pretexto de supuesta remuneración a los jueces u otros empleados públicos;\n11. El que tornare imposible, incierto o litigioso el derecho sobre un bien o el cumplimiento, en las condiciones pactadas, de una obligación referente al mismo, sea mediante cualquier acto jurídico relativo al mismo bien, aunque no importe enajenación, sea removiéndolo, reteniéndolo, ocultándolo o dañándolo, siempre que el derecho o la obligación hubieran sido acordados a otro por un precio o como garantía;\n12. El titular fiduciario, el administrador de fondos comunes de inversión o el dador de un contrado de leasing, que en beneficio propio o de un tercero dispusiere, gravare o perjudicare los bienes y de esta manera defraudare los derechos de los cocontratantes; (Inciso incorporado por art. 82 de la Ley N° 24.441 B.O. 16/1/1995)\n13. El que encontrándose autorizado para ejecutar extrajudicialmente un inmueble lo ejecutara en perjuicio del deudor, a sabiendas de que el mismo no se encuentra en mora, o maliciosamente omitiera cumplimentar los recaudos establecidos para la subasta mediante dicho procedimiento especial; (Inciso incorporado por art. 82 de la Ley N° 24.441 B.O. 16/1/1995)\n14. El tenedor de letras hipotecarias que en perjuicio del deudor o de terceros omitiera consignar en el título los pagos recibidos. (Inciso incorporado por art. 82 de la Ley N° 24.441 B.O. 16/1/1995)\n15. El que defraudare mediante el uso de una tarjeta de compra, crédito o débito, cuando la misma hubiere sido falsificada, adulterada, hurtada, robada, perdida u obtenida del legítimo emisor mediante ardid o engaño, o mediante el uso no autorizado de sus datos, aunque lo hiciere por medio de una operación automática. (Inciso incorporado por art. 1° de la Ley N°\n25.930 B.O. 21/9/2004)\n16. El que defraudare a otro mediante cualquier técnica de manipulación informática que altere el normal funcionamiento de un sistema informático o la transmisión de datos. (Inciso incorporado por art. 9° de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-174",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 174",
  "titulo": "Delitos contra la propiedad · Estafas y otras defraudaciones",
  "tags": "174 delitos contra la propiedad estafas y otras defraudaciones",
  "texto": "Sufrirá prisión de dos a seis años:\n1º. El que para procurarse a sí mismo o procurar a otro un provecho ilegal en perjuicio de un asegurador o de un dador de préstamo a la gruesa, incendiare o destruyere una cosa asegurada o una nave asegurada o cuya carga o flete estén asegurados o sobre la cual se haya efectuado un préstamo a la gruesa;\n2º El que abusare de las necesidades, pasiones o inexperiencia de un menor o de un incapaz, declarado o no declarado tal, para hacerle firmar un documento que importe cualquier efecto jurídico, en daño de él o de otro, aunque el acto sea civilmente nulo;\n3º. El que defraudare usando de pesas o medidas falsas;\n4º. El empresario o constructor de una obra cualquiera o el vendedor de materiales de construcción que cometiere, en la ejecución de la obra o en la entrega de los materiales, un acto fraudulento capaz de poner en peligro la seguridad de las personas, de los bienes o del Estado;\n5º. El que cometiere fraude en perjuicio de alguna administración pública.6°.- El que maliciosamente afectare el normal desenvolvimiento de un establecimiento o explotación comercial, industrial, agropecuaria, minera o destinado a la prestación de servicios; destruyere, dañare, hiciere desaparecer, ocultare o fraudulentamente disminuyere el valor de materias primas, productos de cualquier naturaleza, máquinas, equipos u otros bienes de capital. (Inciso incorporado por art. 2° de la Ley N° 25.602 B.O.20/6/2002) En los casos de los tres incisos precedentes, el culpable, si fuere funcionario o empleado público, sufrirá además inhabilitación especial perpetua. (Párrafo sustituido por art. 3° de la Ley N° 25.602 B.O.20/6/2002)\n(Nota Infoleg: Por art. 4° de la Ley N° 25.602 B.O. 20/6/2002 se incorporó el art. 174 bis pero fue vetado por Decreto N° 1059/2002 B.O. 20/6/2002)"
 },
 {
  "id": "CP-175",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 175",
  "titulo": "Delitos contra la propiedad · Estafas y otras defraudaciones",
  "tags": "175 delitos contra la propiedad estafas y otras defraudaciones",
  "texto": "Será reprimido con multa de Será reprimido con multa de mil pesos a quince mil pesos:\n1º. El que encontrare perdida una cosa que no le pertenezca o un tesoro y se apropiare la cosa o la parte del tesoro correspondiente al propietario del suelo, sin observar las prescripciones del Código Civil;\n2º. El que se apropiare una cosa ajena, en cuya tenencia hubiere entrado a consecuencia de un error o de un caso fortuito;\n3º. El que vendiere la prenda sobre que prestó dinero o se la apropiare o dispusiere de ella, sin las formalidades legales;\n4º. El acreedor que a sabiendas exija o acepte de su deudor, a título de documento, crédito o garantía por una obligación no vencida, un cheque o giro de fecha posterior o en blanco.(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-175-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 175 bis",
  "titulo": "Delitos contra la propiedad · Usura",
  "tags": "175 bis delitos contra la propiedad usura",
  "texto": "El que, aprovechando la necesidad, la ligereza o la inexperiencia de una persona le hiciere dar o prometer, en cualquier forma, para sí o para otro, intereses u otras ventajas pecuniarias evidentemente desproporcionadas con su prestación, u otorgar recaudos o garantías de carácter extorsivo, será reprimido con prisión de uno a tres años y con multa de pesos tres mil a pesos treinta mil.\nLa misma pena será aplicable al que a sabiendas adquiriere, transfiriere o hiciere valer un crédito usurario.\nLa pena de prisión será de tres a seis años, y la multa de pesos quince mil a pesos ciento cincuenta mil, si el autor fuere prestamista o comisionista usurario profesional o habitual.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-176",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 176",
  "titulo": "Delitos contra la propiedad · Quebrados y otros deudores punibles",
  "tags": "176 delitos contra la propiedad quebrados y otros deudores punibles",
  "texto": "Será reprimido, como quebrado fraudulento, con prisión de dos a seis años e inhabilitación especial de tres a diez años, el comerciante declarado en quiebra que, en fraude de sus acreedores, hubiere incurrido en algunos de los hechos siguientes:\n1º Simular o suponer deudas, enajenaciones, gastos o pérdidas;\n2º No justificar la salida o existencia de bienes que debiera tener; substraer u ocultar alguna cosa que correspondiere a la masa;\n3º Conceder ventajas indebidas a cualquier acreedor."
 },
 {
  "id": "CP-177",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 177",
  "titulo": "Delitos contra la propiedad · Quebrados y otros deudores punibles",
  "tags": "177 delitos contra la propiedad quebrados y otros deudores punibles",
  "texto": "Será reprimido, como quebrado culpable, con prisión de un mes a un año e inhabilitación especial de dos a cinco años, el comerciante que hubiere causado su propia quiebra y perjudicado a sus acreedores, por sus gastos excesivos con relación al capital y al número de personas de su familia, especulaciones ruinosas, juego, abandono de sus negocios o cualquier otro acto de negligencia o imprudencia manifiesta."
 },
 {
  "id": "CP-178",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 178",
  "titulo": "Delitos contra la propiedad · Quebrados y otros deudores punibles",
  "tags": "178 delitos contra la propiedad quebrados y otros deudores punibles",
  "texto": "Cuando se tratare de la quiebra de una sociedad comercial o de una persona jurídica que ejerza el comercio, o se hubiere abierto el procedimiento de liquidación sin quiebra de un banco u otra entidad financiera, todo director, síndico, administrador, miembro de la comisión fiscalizadora o gerente de la sociedad o establecimiento fallido o del banco o entidad financiera en liquidación sin quiebra, o contador o tenedor de libros de los mismos, que hubiere cooperado a la ejecución de alguno de los actos a que se refieren los artículos anteriores, será reprimido con la pena de la quiebra fraudulenta o culpable, en su caso. Con la misma pena será reprimido el miembro del consejo de administración o directivo, síndico, miembro de la junta fiscalizadora o de vigilancia, o gerente, tratándose de una sociedad cooperativa o mutual."
 },
 {
  "id": "CP-179",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 179",
  "titulo": "Delitos contra la propiedad · Quebrados y otros deudores punibles",
  "tags": "179 delitos contra la propiedad quebrados y otros deudores punibles",
  "texto": "Será reprimido con prisión de uno a cuatro años, el deudor no comerciante concursado civilmente que, para defraudar a sus acreedores, hubiere cometido o cometiere alguno de los actos mencionados en el artículo 176.\nSerá reprimido con prisión de seis meses a tres años, el que durante el curso de un proceso o después de una sentencia condenatoria, maliciosamente destruyere, inutilizare, dañare, ocultare o hiciere desaparecer bienes de su patrimonio o fraudulentamente disminuyere su valor, y de esta manera frustrare, en todo o en parte, el cumplimiento de las correspondientes obligaciones civiles."
 },
 {
  "id": "CP-180",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 180",
  "titulo": "Delitos contra la propiedad · Quebrados y otros deudores punibles",
  "tags": "180 delitos contra la propiedad quebrados y otros deudores punibles",
  "texto": "Será reprimido con prisión de un mes a un año, el acreedor que consintiere en un concordato, convenio o transacción judicial, en virtud de una connivencia con el deudor o con un tercero, por la cual hubiere estipulado ventajas especiales para el caso de aceptación del concordato, convenio o transacción.\nLa misma pena sufrirá, en su caso, todo deudor o director, gerente o administrador de una sociedad anónima o cooperativa o de una persona jurídica de otra índole, en estado de quiebra o de concurso judicial de bienes, que concluyere un convenio de este género."
 },
 {
  "id": "CP-181",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 181",
  "titulo": "Delitos contra la propiedad · Usurpación",
  "tags": "181 delitos contra la propiedad usurpacion",
  "texto": "Será reprimido con prisión de seis meses a tres años:\n1º el que por violencia, amenazas, engaños, abusos de confianza o clandestinidad despojare a otro, total o parcialmente, de la posesión o tenencia de un inmueble o del ejercicio de un derecho real constituido sobre él, sea que el despojo se produzca invadiendo el inmueble, manteniéndose en él o expulsando a los ocupantes;\n2º el que, para apoderarse de todo o parte de un inmueble, destruyere o alterare los términos o límites del mismo;\n3º el que, con violencias o amenazas, turbare la posesión o tenencia de un inmueble.\n(Artículo sustituido por art. 2° Ley N° 24.454 B.O. 7/3/1995)"
 },
 {
  "id": "CP-182",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 182",
  "titulo": "Delitos contra la propiedad · Usurpación",
  "tags": "182 delitos contra la propiedad usurpacion",
  "texto": "Será reprimido con prisión de quince días a un año:\n1º El que ilícitamente y con el propósito de causar perjuicio a otro sacare aguas de represas, estanques u otros depósitos, ríos, arroyos, fuentes, canales o acueductos o las sacare en mayor cantidad que aquella a que tenga derecho;\n2º El que estorbare el ejercicio de los derechos que un tercero tuviere sobre dichas aguas;\n3º El que ilícitamente y con el propósito de causar perjuicio a otro represare, desviare o detuviere las aguas de los ríos, arroyos, canales o fuentes o usurpare un derecho cualquiera referente al curso de ellas.\nLa pena se aumentará hasta dos años, si para cometer los delitos expresados en los números anteriores, se rompieren o alteraren diques, esclusas, compuertas u otras obras semejantes hechas en los ríos, arroyos, fuentes, depósitos, canales o acueductos."
 },
 {
  "id": "CP-183",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 183",
  "titulo": "Delitos contra la propiedad · Daños",
  "tags": "183 delitos contra la propiedad danos",
  "texto": "Será reprimido con prisión de quince días a un año, el que destruyere, inutilizare, hiciere desaparecer o de cualquier modo dañare una cosa mueble o inmueble o un animal, total o parcialmente ajeno, siempre que el hecho no constituya otro delito más severamente penado.\nEn la misma pena incurrirá el que alterare, destruyere o inutilizare datos, documentos, programas o sistemas informáticos; o vendiere, distribuyere, hiciere circular o introdujere en un sistema informático, cualquier programa destinado a causar daños. (Párrafo incorporado por art. 10 de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-184",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 184",
  "titulo": "Delitos contra la propiedad · Daños",
  "tags": "184 delitos contra la propiedad danos",
  "texto": "La pena será de tres (3) meses a cuatro (4) años de prisión, si mediare cualquiera de las circunstancias siguientes:\n1. Ejecutar el hecho con el fin de impedir el libre ejercicio de la autoridad o en venganza de sus determinaciones;\n2. Producir infección o contagio en aves u otros animales domésticos;\n3. Emplear substancias venenosas o corrosivas;\n4. Cometer el delito en despoblado y en banda;\n5. Ejecutarlo en archivos, registros, bibliotecas, museos o en puentes, caminos, paseos u otros bienes de uso público; o en tumbas, signos conmemorativos, monumentos, estatuas, cuadros u otros objetos de arte colocados en edificios o lugares públicos; o en datos, documentos, programas o sistemas informáticos públicos;\n6. Ejecutarlo en sistemas informáticos destinados a la prestación de servicios de salud, de comunicaciones, de provisión o transporte de energía, de medios de transporte u otro servicio público.\n(Artículo sustituido por art. 11 de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-185",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 185",
  "titulo": "Delitos contra la propiedad · Disposiciones generales",
  "tags": "185 delitos contra la propiedad disposiciones generales",
  "texto": "Están exentos de responsabilidad criminal, sin perjuicio de la civil, por los hurtos, defraudaciones o daños que recíprocamente se causaren:\n1. Los cónyuges, ascendientes, descendientes y afines en la línea recta;\n2. El consorte viudo, respecto de las cosas de la pertenencia de su difunto cónyuge, mientras no hayan pasado a poder de otro;\n3. Los hermanos y cuñados, si viviesen juntos.\nLa excepción establecida en el párrafo anterior, no es aplicable a los extraños que participen del delito."
 },
 {
  "id": "CP-186",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 186",
  "titulo": "Delitos contra la seguridad publica · Incendios y otros estragos",
  "tags": "186 delitos contra la seguridad publica incendios y otros estragos",
  "texto": "El que causare incendio, explosión o inundación, será reprimido:\n1º Con reclusión o prisión de tres a diez años, si hubiere peligro común para los bienes;\n2º Con reclusión o prisión de tres a diez años el que causare incendio o destrucción por cualquier otro medio:\na) De cereales en parva, gavillas o bolsas, o de los mismos todavía no cosechados;\nb) De bosques, viñas, olivares, cañaverales, algodonales, yerbatales o cualquiera otra plantación de árboles o arbustos en explotación, ya sea con sus frutos en pie o cosechados;\nc) De ganado en los campos o de sus productos amontonados en el campo o depositados;\nd) De la leña o carbón de leña, apilados o amontonados en los campos de su explotación y destinados al comercio;\ne) De alfalfares o cualquier otro cultivo de forrajes, ya sea en pie o emparvados, engavillados, ensilados o enfardados;\nf) De los mismos productos mencionados en los párrafos anteriores, cargados, parados o en movimiento;\n3º Con reclusión o prisión de tres a quince años, si hubiere peligro para un archivo público, biblioteca, museo, arsenal, astillero, fábrica de pólvora o de pirotecnia militar o parque de artillería;\n4º Con reclusión o prisión de tres a quince años, si hubiere peligro de muerte para alguna persona;\n5º Con reclusión o prisión de ocho a veinte años, si el hecho fuere causa inmediata de la muerte de alguna persona."
 },
 {
  "id": "CP-187",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 187",
  "titulo": "Delitos contra la seguridad publica · Incendios y otros estragos",
  "tags": "187 delitos contra la seguridad publica incendios y otros estragos",
  "texto": "Incurrirá, según los casos, en las penas señaladas en el artículo precedente, el que causare estrago por medio de sumersión o varamiento de nave, derrumbe de un edificio, inundación, de una mina o cualquier otro medio poderoso de destrucción."
 },
 {
  "id": "CP-188",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 188",
  "titulo": "Delitos contra la seguridad publica · Incendios y otros estragos",
  "tags": "188 delitos contra la seguridad publica incendios y otros estragos",
  "texto": "Será reprimido con prisión de uno a seis años el que, destruyendo o inutilizando diques u otras obras destinadas a la defensa común contra las inundaciones u otros desastres, hiciere surgir el peligro de que éstos se produzcan.\nLa misma pena se aplicará al que, para impedir la extinción de un incendio o las obras de defensa contra una inundación, sumersión, naufragio u otro desastre, substrajere, ocultare o hiciere inservibles, materiales, instrumentos u otros medios destinados a la extinción o a la defensa referida."
 },
 {
  "id": "CP-189",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 189",
  "titulo": "Delitos contra la seguridad publica · Incendios y otros estragos",
  "tags": "189 delitos contra la seguridad publica incendios y otros estragos",
  "texto": "Será reprimido con prisión de un mes a un año, el que, por imprudencia o negligencia, por impericia en su arte o profesión o por inobservancia de los reglamentos u ordenanzas, causare un incendio u otros estragos.\nSi el hecho u omisión culpable pusiere en peligro de muerte a alguna persona o causare la muerte de alguna persona, el máximo de la pena podrá elevarse hasta cinco años.\n(Artículo sustituido por art. 3° de la Ley N° 25.189 B.O. 28/10/1999)"
 },
 {
  "id": "CP-189-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 189 bis",
  "titulo": "Delitos contra la seguridad publica · Incendios y otros estragos",
  "tags": "189 bis delitos contra la seguridad publica incendios y otros estragos",
  "texto": "(1) El que, con el fin de contribuir a la comisión de delitos contra la seguridad común o causar daños en las máquinas o en la elaboración de productos, adquiriere, fabricare, suministrare, sustrajere o tuviere en su poder bombas, materiales o aparatos capaces de liberar energía nuclear, materiales radiactivos o sustancias nucleares, o sus desechos, isótopos radiactivos, materiales explosivos, inflamables, asfixiantes, tóxicos o biológicamente peligrosos, o sustancias o materiales destinados a su preparación, será reprimido con reclusión o prisión de CINCO (5) a QUINCE (15) años.\nLa misma pena se impondrá al que, sabiendo o debiendo saber que contribuye a la comisión de delitos contra la seguridad común o destinados a causar daños en las máquinas o en la elaboración de productos, diere instrucciones para la preparación de sustancias o materiales mencionados en el párrafo anterior.\nLa simple tenencia de los materiales a los que se refiere el párrafo que antecede, sin la debida autorización legal, o que no pudiere justificarse por razones de su uso doméstico o industrial, será reprimida con prisión de TRES (3) a SEIS (6) años.\n(2) La simple tenencia de armas de fuego de uso civil, sin la debida autorización legal, será reprimida con prisión de 6 (SEIS) meses a 2 (DOS) años y multa de MIL PESOS ($ 1.000.-) a DIEZ MIL PESOS ($ 10.000.-).\nSi las armas fueren de guerra, la pena será de DOS (2) a SEIS (6) años de prisión.\nLa portación de armas de fuego de uso civil, sin la debida autorización legal, será reprimida con prisión de UN (1) año a CUATRO (4) años.\nSi las armas fueren de guerra, la pena será de TRES (3) años y SEIS (6) meses a OCHO (8) años y SEIS (6) meses de reclusión o prisión.\nSi el portador de las armas a las cuales se refieren los dos párrafos que anteceden, fuere tenedor autorizado del arma de que se trate, la escala penal correspondiente se reducirá en un tercio del mínimo y del máximo.\nLa misma reducción prevista en el párrafo anterior podrá practicarse cuando, por las circunstancias del hecho y las condiciones personales del autor, resultare evidente la falta de intención de utilizar las armas portadas con fines ilícitos.\nEn los dos casos precedentes, se impondrá, además, inhabilitación especial por el doble del tiempo de la condena.\nEl que registrare antecedentes penales por delito doloso contra las personas o con el uso de armas, o se encontrare gozando de una excarcelación o exención de prisión anterior y portare un arma de fuego de cualquier calibre, será reprimido con prisión de CUATRO (4) a DIEZ (10) años.\n(Nota Infoleg: Por art. 4° de la Ley N° 25.886 B.O. 5/5/2004, se establece que el primer párrafo del punto 2 del artículo 189 bis entrará en vigencia a partir del término del plazo establecido de SEIS MESES, en el cual el Poder Ejecutivo Nacional dispondrá, las medidas pertinentes para facilitar el registro gratuito y sencillo de las armas de fuego de uso civil o uso civil condicionado. Asimismo, en el mismo término, se arbitrarán en todo el territorio de la Nación, con contralor de la máxima autoridad judicial que en cada jurisdicción se designe, los medios para recepcionar de parte de la población, la entrega voluntaria de toda arma de fuego que su propietario o tenedor decida realizar.)\n(3) El acopio de armas de fuego, piezas o municiones de éstas, o la tenencia de instrumental para producirlas, sin la debida autorización, será reprimido con reclusión o prisión de CUATRO\n(4) a DIEZ (10) años.\nEl que hiciere de la fabricación ilegal de armas de fuego una actividad habitual será reprimido con reclusión o prisión de CINCO (5) a DIEZ (10) años.\n(4) Será reprimido con prisión de UN (1) año a SEIS (6) años el que entregare un arma de fuego, por cualquier título, a quien no acreditare su condición de legítimo usuario.\nLa pena será de TRES (3) años y SEIS (6) meses a DIEZ (10) años de prisión si el arma fuera entregada a un menor de DIECIOCHO (18) años.\nSi el autor hiciere de la provisión ilegal de armas de fuego una actividad habitual, la pena será de CUATRO (4) a QUINCE (15) años de reclusión o prisión.\nSi el culpable de cualquiera de las conductas contempladas en los tres párrafos anteriores contare con autorización para la venta de armas de fuego, se le impondrá, además, inhabilitación especial absoluta y perpetua, y multa de DIEZ MIL PESOS ($ 10.000.-).\n(5) Será reprimido con prisión de TRES (3) a OCHO (8) años e inhabilitación especial por el doble del tiempo de la condena el que, contando con la debida autorización legal para fabricar armas, omitiere su número o grabado conforme a la normativa vigente, o asignare a DOS (2) o más armas idénticos números o grabados.\nEn la misma pena incurrirá el que adulterare o suprimiere el número o el grabado de un arma de fuego.\n(Artículo sustituido por art. 1° de la Ley N° 25.886 B.O. 5/5/2004.)"
 },
 {
  "id": "CP-189-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 189 ter",
  "titulo": "Delitos contra la seguridad publica · Incendios y otros estragos",
  "tags": "189 ter delitos contra la seguridad publica incendios y otros estragos",
  "texto": "(Artículo derogado por art. 2° de la Ley N° 25.886 B.O. 5/5/2004.)\n(Denominación sustituida por art. 1° de la Ley N° 26.362, B.O. 16/4/2008)"
 },
 {
  "id": "CP-190",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 190",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "190 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "Será reprimido con prisión de dos a ocho años, el que a sabiendas ejecutare cualquier acto que ponga en peligro la seguridad de una nave, construcción flotante o aeronave.\nSi el hecho produjere naufragio, varamiento o desastre aéreo, la pena será de seis a quince años de reclusión o prisión.\nSi el hecho causare lesión a alguna persona, la pena será de seis a quince años de reclusión o prisión, y si ocasionare la muerte, de diez a veinticinco años de reclusión o prisión.\nLas disposiciones precedentes se aplicarán aunque la acción recaiga sobre una cosa propia, si del hecho deriva peligro para la seguridad común."
 },
 {
  "id": "CP-191",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 191",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "191 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "El que empleare cualquier medio para detener o entorpecer la marcha de un tren o para hacerle descarrilar, será reprimido:\n1º Con prisión de seis meses a tres años, si no se produjere descarrilamiento u otro accidente;\n2º Con prisión de dos a seis años, si se produjere descarrilamiento u otro accidente;\n3º Con reclusión o prisión de tres a diez años, si a consecuencia del accidente, resultare lesionada alguna persona;\n4º Con reclusión o prisión de diez a veinticinco años, si resultare la muerte de alguna persona."
 },
 {
  "id": "CP-192",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 192",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "192 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "Será reprimido con las penas establecidas en el artículo anterior en sus casos respectivos, el que ejecutare cualquier acto tendiente a interrumpir el funcionamiento de un telégrafo o teléfono destinado al servicio de un ferrocarril."
 },
 {
  "id": "CP-193",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 193",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "193 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "Será reprimido con prisión de un mes a un año, si el hecho no importare un delito más severamente penado, el que arrojare cuerpos contundentes o proyectiles contra un tren o tranvía en marcha."
 },
 {
  "id": "CP-193-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 193 bis",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "193 bis delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "Será reprimido con prisión de SEIS (6) meses a TRES (3) años e inhabilitación especial para conducir por el doble del tiempo de la condena, el conductor que creare una situación de peligro para la vida o la integridad física de las personas, mediante la participación en una prueba de velocidad o de destreza con un vehículo automotor, realizada sin la debida autorización de la autoridad competente.\nLa misma pena se aplicará a quien organizare o promocionare la conducta prevista en el presente artículo, y a quien posibilitare su realización por un tercero mediante la entrega de un vehículo de su propiedad o confiado a su custodia, sabiendo que será utilizado para ese fin.\n(Artículo incorporado por art. 2° de la Ley N° 26.362, B.O. 16/4/2008)"
 },
 {
  "id": "CP-194",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 194",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "194 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "El que, sin crear una situación de peligro común, impidiere, estorbare o entorpeciere el normal funcionamiento de los transportes por tierra, agua o aire o los servicios públicos de comunicación, de provisión de agua, de electricidad o de sustancias energéticas, será reprimido con prisión de tres meses a dos años."
 },
 {
  "id": "CP-195",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 195",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "195 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "Serán reprimidos con prisión de un mes a un año, si el hecho no importare un delito más severamente penado, los conductores, capitanes, pilotos, mecánicos y demás empleados de un tren o de un buque, que abandonaren sus puestos durante sus servicios respectivos antes de llegar a puerto o al término del viaje ferroviario."
 },
 {
  "id": "CP-196",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 196",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "196 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "Será reprimido con prisión de seis meses a tres años el que por imprudencia o negligencia o por impericia en su arte o profesión o por inobservancia de los reglamentos u ordenanzas, causare un descarrilamiento, naufragio u otro accidente previsto en este capítulo.\nSi del hecho resultare lesionada o muerta alguna persona, se impondrá prisión de uno a cinco años.\n(Artículo sustituido por art. 4° de la Ley N° 25.189 28/10/1999)"
 },
 {
  "id": "CP-197",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 197",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la seguridad del tránsito y de los medios de transporte y de comunicación",
  "tags": "197 delitos contra la seguridad publica del transito y de los medios transporte comunicacion",
  "texto": "Será reprimido con prisión de seis (6) meses a dos (2) años, el que interrumpiere o entorpeciere la comunicación telegráfica, telefónica o de otra naturaleza o resistiere violentamente el restablecimiento de la comunicación interrumpida.\n(Artículo sustituido por art. 12 de la Ley N° 26.388, B.O. 25/6/2008)"
 },
 {
  "id": "CP-198",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 198",
  "titulo": "Delitos contra la seguridad publica · Piratería",
  "tags": "198 delitos contra la seguridad publica pirateria",
  "texto": "Será reprimido con reclusión o prisión de tres a quince años:\n1º El que practicare en el mar o en ríos navegables, algún acto de depredación o violencia contra un buque o contra personas o cosas que en él se encuentren, sin estar autorizado por alguna potencia beligerante o excediendo los límites de una autorización legítimamente concedida;\n2º El que practicare algún acto de depredación o violencia contra una aeronave en vuelo o mientras realiza las operaciones inmediatamente anteriores al vuelo, o contra personas o cosas que en ellas se encuentren, sin estar autorizado por alguna potencia beligerante o excediendo los límites de una autorización legítimamente concedida;\n3º El que mediante violencia, intimidación o engaño, usurpare la autoridad de un buque o aeronave, con el fin de apoderarse de él o de disponer de las cosas o de las personas que lleva;\n4º El que, en connivencia con piratas, les entregare un buque o aeronave, su carga o lo que perteneciere a su pasaje o tripulación;\n5º El que, con amenazas o violencia, se opusiere a que el comandante o la tripulación defiendan el buque o aeronave atacado por piratas;\n6º El que, por cuenta propia o ajena, equipare un buque o aeronave destinados a la piratería;\n7º El que, desde el territorio de la República, a sabiendas traficare con piratas o les suministrare auxilio."
 },
 {
  "id": "CP-199",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 199",
  "titulo": "Delitos contra la seguridad publica · Piratería",
  "tags": "199 delitos contra la seguridad publica pirateria",
  "texto": "Si los actos de violencia u hostilidad mencionados en el artículo anterior, fueren seguidos de la muerte de alguna persona que se encontrare en el buque o aeronave atacados, la pena será de diez a veinticinco años de reclusión o prisión."
 },
 {
  "id": "CP-200",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 200",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "200 delitos contra la seguridad publica salud",
  "texto": "Será reprimido con reclusión o prisión de TRES (3) a DIEZ (10) años y multa de PESOS DIEZ MIL ($ 10.000) a PESOS DOSCIENTOS MIL ($ 200.000), el que envenenare, adulterare o falsificare de un modo peligroso para la salud, aguas potables o sustancias alimenticias o medicinales destinadas al uso público o al consumo de una colectividad de personas.\n(Artículo sustituido por art. 1° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-201",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 201",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "201 delitos contra la seguridad publica salud",
  "texto": "Las penas del artículo precedente se aplicarán al que vendiere, pusiere en venta, suministrare, distribuyere o almacenare con fines de comercialización aguas potables, sustancias alimenticias o medicinales o mercaderías peligrosas para la salud, disimulando su carácter nocivo.\n(Artículo sustituido por art. 2° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-201-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 201 bis",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "201 bis delitos contra la seguridad publica salud",
  "texto": "Si como consecuencia del envenenamiento, adulteración o falsificación de aguas potables o sustancias alimenticias o medicinales, resultare la muerte de alguna persona, la pena será de DIEZ (10) a VEINTICINCO (25) años de reclusión o prisión; si resultaren lesiones gravísimas, la pena será de TRES (3) a QUINCE (15) años de reclusión o prisión; si resultaren lesiones graves, la pena será de TRES (3) a DIEZ (10) años de reclusión o prisión.\nEn todos los casos se aplicará además multa de PESOS DIEZ MIL ($ 10.000) a PESOS DOSCIENTOS MIL ($ 200.000).\n(Artículo incorporado por art. 3° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-202",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 202",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "202 delitos contra la seguridad publica salud",
  "texto": "Será reprimido con reclusión o prisión de tres a quince años, el que propagare una enfermedad peligrosa y contagiosa para las personas."
 },
 {
  "id": "CP-203",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 203",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "203 delitos contra la seguridad publica salud",
  "texto": "Cuando alguno de los hechos previstos en los artículos anteriores fuere cometido por imprudencia, negligencia, impericia en su arte o profesión o por inobservancia de los deberes a su cargo, se impondrá multa de PESOS CINCO MIL ($ 5.000) a PESOS CIEN MIL\n($ 100.000); si tuviere como resultado enfermedad o muerte se aplicará prisión de SEIS (6) meses a CINCO (5) años.\n(Artículo sustituido por art. 4° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-204",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 204",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "204 delitos contra la seguridad publica salud",
  "texto": "Será reprimido con prisión de SEIS (6) meses a TRES (3) años el que estando autorizado para la venta de sustancias medicinales, las suministrare en especie, calidad o cantidad no correspondiente a la receta médica, o diversa de la declarada o convenida, o excediendo las reglamentaciones para el reemplazo de sustancias medicinales, o sin la presentación y archivo de la receta de aquellos productos que, según las reglamentaciones vigentes, no pueden ser comercializados sin ese requisito.\n(Artículo sustituido por art. 5° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-204-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 204 bis",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "204 bis delitos contra la seguridad publica salud",
  "texto": "Cuando el delito previsto en el artículo anterior se cometiere por negligencia, la pena será de multa de PESOS CINCO MIL ($ 5.000) a PESOS CIEN MIL ($\n100.000).\n(Artículo sustituido por art. 6° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-204-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 204 ter",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "204 ter delitos contra la seguridad publica salud",
  "texto": "Será reprimido con prisión de UNO (1) a CUATRO (4) años y multa de PESOS DIEZ MIL ($ 10.000) a PESOS DOSCIENTOS MIL ($ 200.000), el que produjere o fabricare sustancias medicinales en establecimientos no autorizados.\n(Artículo sustituido por art. 7° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-204-quater",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 204 quater",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "204 quater delitos contra la seguridad publica salud",
  "texto": "Será reprimido con multa de PESOS DIEZ MIL ($ 10.000) a PESOS DOSCIENTOS MIL ($ 200.000), el que teniendo a su cargo la dirección, administración, control o vigilancia de un establecimiento destinado al expendio, almacenamiento, distribución, producción o fabricación de sustancias medicinales, a sabiendas, incumpliere con los deberes a su cargo posibilitando la comisión de alguno de los hechos previstos en el artículo 204.\n(Artículo sustituido por art. 8° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-204-quinquies",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 204 quinquies",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "204 quinquies delitos contra la seguridad publica salud",
  "texto": ": Será reprimido con prisión de SEIS (6) meses a TRES (3) años el que sin autorización vendiere sustancias medicinales que requieran receta médica para su comercialización.\n(Artículo incorporado por art. 9° de la Ley N° 26.524 B.O. 5/11/2009)"
 },
 {
  "id": "CP-205",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 205",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "205 delitos contra la seguridad publica salud",
  "texto": "Será reprimido con prisión de seis meses a dos años, el que violare las medidas adoptadas por las autoridades competentes, para impedir la introducción o propagación de una epidemia."
 },
 {
  "id": "CP-206",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 206",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "206 delitos contra la seguridad publica salud",
  "texto": "Será reprimido con prisión de UNO (1) a SEIS (6) meses el que violare las reglas establecidas por las leyes de policía sanitaria animal.\n(Artículo sustituido por art. 4° de la Ley N° 25.890 B.O. 21/5/2004)"
 },
 {
  "id": "CP-207",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 207",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "207 delitos contra la seguridad publica salud",
  "texto": "En el caso de condenación por un delito previsto en este Capítulo, el culpable, si fuere funcionario público o ejerciere alguna profesión o arte, sufrirá, además, inhabilitación especial por doble tiempo del de la condena. Si la pena impuesta fuere la de multa, la inhabilitación especial durará de un mes a un año."
 },
 {
  "id": "CP-208",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 208",
  "titulo": "Delitos contra la seguridad publica · Delitos contra la salud pública",
  "tags": "208 delitos contra la seguridad publica salud",
  "texto": "Será reprimido con prisión de quince días a un año:\n1º El que, sin título ni autorización para el ejercicio de un arte de curar o excediendo los límites de su autorización, anunciare, prescribiere, administrare o aplicare habitualmente medicamentos, aguas, electricidad, hipnotismo o cualquier medio destinado al tratamiento de las enfermedades de las personas, aun a título gratuito;\n2º El que, con título o autorización para el ejercicio de un arte de curar, anunciare o prometiere la curación de enfermedades a término fijo o por medios secretos o infalibles;\n3º El que, con título o autorización para el ejercicio de un arte de curar, prestare su nombre a otro que no tuviere título o autorización, para que ejerza los actos a que se refiere el inciso 1º de este artículo."
 },
 {
  "id": "CP-209",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 209",
  "titulo": "Delitos contra el orden publico · Instigación a cometer delitos",
  "tags": "209 delitos contra el orden publico instigacion a cometer",
  "texto": "El que públicamente instigare a cometer un delito determinado contra una persona o institución, será reprimido, por la sola instigación, con prisión de dos a seis años, según la gravedad del delito y las demás circunstancias establecidas en el artículo 41."
 },
 {
  "id": "CP-209-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 209 bis",
  "titulo": "Delitos contra el orden publico · Instigación a cometer delitos",
  "tags": "209 bis delitos contra el orden publico instigacion a cometer",
  "texto": "En igual pena incurrirá quien en tiempo de conflicto armado incite públicamente a la sustracción al servicio militar legalmente impuesto o asumido. Si el autor fuese un militar, el máximo de la pena se elevará a diez (10) años. (Artículo incorporado por art. 4° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-210",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 210",
  "titulo": "Delitos contra el orden publico · Asociación ilícita",
  "tags": "210 delitos contra el orden publico asociacion ilicita",
  "texto": "Será reprimido con prisión o reclusión de tres a diez años, el que tomare parte en una asociación o banda de tres o más personas destinada a cometer delitos por el solo hecho de ser miembro de la asociación. Para los jefes u organizadores de la asociación el mínimo de la pena será de cinco años de prisión o reclusión."
 },
 {
  "id": "CP-210-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 210 bis",
  "titulo": "Delitos contra el orden publico · Asociación ilícita",
  "tags": "210 bis delitos contra el orden publico asociacion ilicita",
  "texto": "Se impondrá reclusión o prisión de cinco a veinte años al que tomare parte, cooperare o ayudare a la formación o al mantenimiento de una asociación ilícita destinada a cometer delitos cuando la acción contribuya a poner en peligro la vigencia de la Constitución Nacional, siempre que ella reúna por lo menos dos de las siguientes características:\na) Estar integrada por diez o más individuos;\nb) Poseer una organización militar o de tipo militar;\nc) Tener estructura celular;\nd) Disponer de armas de guerra o explosivos de gran poder ofensivo;\ne) Operar en más de una de las jurisdicciones políticas del país;\nf) Estar compuesta por uno o más oficiales o suboficiales de las fuerzas armadas o de seguridad;\ng) Tener notorias conexiones con otras organizaciones similares existentes en el país o en el exterior;\nh) Recibir algún apoyo, ayuda o dirección de funcionarios públicos."
 },
 {
  "id": "CP-211",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 211",
  "titulo": "Delitos contra el orden publico · Intimidación pública",
  "tags": "211 delitos contra el orden publico intimidacion publica",
  "texto": "Será reprimido con prisión de dos a seis años, el que, para infundir un temor público o suscitar tumultos o desórdenes, hiciere señales, diere voces de alarma, amenazare con la comisión de un delito de peligro común, o empleare otros medios materiales normalmente idóneos para producir tales efectos.\nCuando para ello se empleare explosivos, agresivos químicos o materias afines, siempre que el hecho no constituya delito contra la seguridad pública, la pena será de prisión de tres a diez años."
 },
 {
  "id": "CP-212",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 212",
  "titulo": "Delitos contra el orden publico · Intimidación pública",
  "tags": "212 delitos contra el orden publico intimidacion publica",
  "texto": "Será reprimido con prisión de tres a seis años el que públicamente incitare a la violencia colectiva contra grupos de personas o instituciones, por la sola incitación."
 },
 {
  "id": "CP-213",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 213",
  "titulo": "Delitos contra el orden publico · Apología del crimen",
  "tags": "213 delitos contra el orden publico apologia del crimen",
  "texto": "Será reprimido con prisión de un mes a un año, el que hiciere públicamente y por cualquier medio la apología de un delito o de un condenado por delito."
 },
 {
  "id": "CP-213-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 213 bis",
  "titulo": "Delitos contra el orden publico · Otros atentados contra el orden público",
  "tags": "213 bis delitos contra el orden publico otros atentados",
  "texto": "Será reprimido con reclusión o prisión de tres a ocho años el que organizare o tomare parte en agrupaciones permanentes o transitorias que, sin estar comprendidas en el artículo 210 de este código, tuvieren por objeto principal o accesorios imponer sus ideas o combatir las ajenas por la fuerza o el temor, por el solo hecho de ser miembro de la asociación.\nCapítulo VI. Asociaciones ilícitas terroristas y financiación del terrorismo\n(Capítulo incorporado por art. 1° de la Ley N° 26.268 B.O. 5/7/2007) Artículo 213 ter.- Se impondrá reclusión o prisión de CINCO (5) a VEINTE (20) años al que tomare parte de una asociación ilícita cuyo propósito sea, mediante la comisión de delitos, aterrorizar a la población u obligar a un gobierno o a una organización internacional a realizar un acto o abstenerse de hacerlo, siempre que ella reúna las siguientes características:\na) Tener un plan de acción destinado a la propagación del odio étnico, religioso o político;\nb) Estar organizada en redes operativas internacionales;\nc) Disponer de armas de guerra, explosivos, agentes químicos o bacteriológicos o cualquier otro medio idóneo para poner en peligro la vida o la integridad de un número indeterminado de personas.\nPara los fundadores o jefes de la asociación el mínimo de la pena será de DIEZ (10) años de reclusión o prisión.\n(Artículo incorporado por art. 2° de la Ley N° 26.268 B.O. 5/7/2007) Artículo 213 quáter.- Será reprimido con reclusión o prisión de CINCO (5) a QUINCE (15) años, salvo que correspondiere una pena mayor por aplicación de las reglas de los artículos 45 y 48, el que recolectare o proveyere bienes o dinero, con conocimiento de que serán utilizados, en todo o en parte, para financiar a una asociación ilícita terrorista de las descriptas en el artículo 213 ter, o a un miembro de éstas para la comisión de cualquiera de los delitos que constituyen su objeto, independientemente de su acaecimiento.\n(Artículo incorporado por art. 3° de la Ley N° 26.268 B.O. 5/7/2007)"
 },
 {
  "id": "CP-214",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 214",
  "titulo": "Delitos contra la seguridad de la nacion · Traición",
  "tags": "214 delitos contra la seguridad de nacion traicion",
  "texto": "Será reprimido con reclusión o prisión de diez a veinticinco años o reclusión o prisión perpetua y en uno u otro caso, inhabilitación absoluta perpetua, siempre que el hecho no se halle comprendido en otra disposición de este código, todo argentino o toda persona que deba obediencia a la Nación por razón de su empleo o función pública, que tomare las armas contra ésta, se uniere a sus enemigos o les prestare cualquier ayuda o socorro."
 },
 {
  "id": "CP-215",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 215",
  "titulo": "Delitos contra la seguridad de la nacion · Traición",
  "tags": "215 delitos contra la seguridad de nacion traicion",
  "texto": "Será reprimido con reclusión o prisión perpetua, el que cometiere el delito previsto en el artículo precedente, en los casos siguientes:\n1º Si ejecutare un hecho dirigido a someter total o parcialmente la Nación al dominio extranjero o a menoscabar su independencia o integridad;\n2º Si indujere o decidiere a una potencia extranjera a hacer la guerra contra la República.\n3° Si perteneciere a las fuerzas armadas. (Inciso incorporado por art. 5° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-216",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 216",
  "titulo": "Delitos contra la seguridad de la nacion · Traición",
  "tags": "216 delitos contra la seguridad de nacion traicion",
  "texto": "Será reprimido con reclusión o prisión de uno a ocho años, el que tomare parte en una conspiración de dos o más personas, para cometer el delito de traición, en cualquiera de los casos comprendidos en los artículos precedentes, si la conspiración fuere descubierta antes de empezar su ejecución."
 },
 {
  "id": "CP-217",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 217",
  "titulo": "Delitos contra la seguridad de la nacion · Traición",
  "tags": "217 delitos contra la seguridad de nacion traicion",
  "texto": "Quedará eximido de pena el que revelare la conspiración a la autoridad, antes de haberse comenzado el procedimiento."
 },
 {
  "id": "CP-218",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 218",
  "titulo": "Delitos contra la seguridad de la nacion · Traición",
  "tags": "218 delitos contra la seguridad de nacion traicion",
  "texto": "Las penas establecidas en los artículos anteriores se aplicarán, también, cuando los hechos previstos en ellos fueren cometidos contra una potencia aliada de la República, en guerra contra un enemigo común.\nSe aplicarán asimismo a los extranjeros residentes en territorio argentino, salvo lo establecido por los tratados o por el derecho de gentes, acerca de los funcionarios diplomáticos y de los nacionales de los países en conflicto. En este caso se aplicará la pena disminuida conforme a lo dispuesto por el artículo 44."
 },
 {
  "id": "CP-219",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 219",
  "titulo": "Delitos contra la seguridad de la nacion · Delitos que comprometen la paz y la dignidad de la Nación",
  "tags": "219 delitos contra la seguridad de nacion que comprometen paz y dignidad",
  "texto": "Será reprimido con prisión de uno a seis años, el que por actos materiales hostiles no aprobados por el gobierno nacional, diere motivos al peligro de una declaración de guerra contra la Nación, expusiere a sus habitantes a experimentar vejaciones o represalias en sus personas o en sus bienes o alterare las relaciones amistosas del gobierno argentino con un gobierno extranjero. Si de dichos actos resultaren hostilidades o la guerra, la pena será de tres a quince años de reclusión o prisión.\nCuando los actos precedentes fuesen cometidos por un militar, los mínimos de las penas previstas en este artículo se elevarán a tres (3) y diez (10) años respectivamente. Asimismo, los máximos de las penas previstas en este artículo se elevarán respectivamente a diez (10) y veinte (20) años. (Párrafo incorporado por art. 6° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-220",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 220",
  "titulo": "Delitos contra la seguridad de la nacion · Delitos que comprometen la paz y la dignidad de la Nación",
  "tags": "220 delitos contra la seguridad de nacion que comprometen paz y dignidad",
  "texto": "Se impondrá prisión de seis (6) meses a dos (2) años, al que violare los tratados concluidos con naciones extranjeras, las treguas y armisticios acordados entre la República y una potencia enemiga o entre sus fuerzas beligerantes o los salvoconductos debidamente expedidos.\nSi el hecho fuese cometido por un militar el mínimo de la pena se elevará a un (1) año y el máximo de la pena se elevará a cinco (5) años.\n(Artículo sustituido por art. 7° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-221",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 221",
  "titulo": "Delitos contra la seguridad de la nacion · Delitos que comprometen la paz y la dignidad de la Nación",
  "tags": "221 delitos contra la seguridad de nacion que comprometen paz y dignidad",
  "texto": "Será reprimido con prisión de seis meses a dos años, el que violare las inmunidades del jefe de un Estado o del representante de una potencia extranjera."
 },
 {
  "id": "CP-222",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 222",
  "titulo": "Delitos contra la seguridad de la nacion · Delitos que comprometen la paz y la dignidad de la Nación",
  "tags": "222 delitos contra la seguridad de nacion que comprometen paz y dignidad",
  "texto": "Será reprimido con reclusión o prisión de uno (1) a seis (6) años, el que revelare secretos políticos, industriales, tecnológicos o militares concernientes a la seguridad, a los medios de defensa o a las relaciones exteriores de la Nación. (Párrafo sustituido por art.\n8° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS\n(6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación) En la misma pena incurrirá el que obtuviere la revelación del secreto. Será reprimido con prisión de uno a cuatro años el que públicamente ultrajare la bandera, el escudo o el himno de la Nación o los emblemas de una provincia argentina.\nSi la revelación u obtención fuese cometida por un militar, en el ejercicio de sus funciones el mínimo de la pena se elevará a tres (3) años y el máximo de la pena se elevará a diez (10) años. (Párrafo incorporado por art. 9° del Anexo I de la Ley N° 26.394 B.O. 29/8/2008.\nVigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-223",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 223",
  "titulo": "Delitos contra la seguridad de la nacion · Delitos que comprometen la paz y la dignidad de la Nación",
  "tags": "223 delitos contra la seguridad de nacion que comprometen paz y dignidad",
  "texto": "Será reprimido con prisión de un mes a un año e inhabilitación especial por doble tiempo, el que por imprudencia o negligencia diere a conocer los secretos mencionados en el artículo precedente, de los que se hallare en posesión en virtud de su empleo u oficio."
 },
 {
  "id": "CP-224",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 224",
  "titulo": "Delitos contra la seguridad de la nacion · Delitos que comprometen la paz y la dignidad de la Nación",
  "tags": "224 delitos contra la seguridad de nacion que comprometen paz y dignidad",
  "texto": "Será reprimido con prisión de seis meses a dos años, el que indebidamente levantare planos de fortificaciones, buques, establecimientos, vías u otras obras militares o se introdujere con tal fin, clandestina o engañosamente en dichos lugares, cuando su acceso estuviere prohibido al público."
 },
 {
  "id": "CP-225",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 225",
  "titulo": "Delitos contra la seguridad de la nacion · Delitos que comprometen la paz y la dignidad de la Nación",
  "tags": "225 delitos contra la seguridad de nacion que comprometen paz y dignidad",
  "texto": "Será reprimido con reclusión o prisión de tres a diez años, el que, encargado por el gobierno argentino de una negociación con un estado extranjero, la condujere de un modo perjudicial a la Nación, apartándose de sus instrucciones.\nDELITOS CONTRA LOS PODERES PUBLICOS Y EL ORDEN CONSTITUCIONAL"
 },
 {
  "id": "CP-226",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 226",
  "titulo": "Delitos contra la seguridad de la nacion · Atentados al orden constitucional y a la vida democrática",
  "tags": "226 delitos contra la seguridad de nacion atentados al orden constitucional y a vida democratica",
  "texto": "Serán reprimidos con prisión de cinco a quince años los que se alzaren en armas para cambiar la Constitución, deponer alguno de los poderes públicos del gobierno nacional, arrancarle alguna medida o concesión o impedir, aunque sea temporariamente, el libre ejercicio de sus facultades constitucionales o su formación o renovación en los términos y formas legales. Si el hecho descripto en el párrafo anterior fuese perpetrado con el fin de cambiar de modo permanente el sistema democrático de gobierno, suprimir la organización federal, eliminar la división de poderes, abrogar los derechos fundamentales de la persona humana o suprimir o menoscabar, aunque sea temporariamente, la independencia económica de la Nación, la pena será de ocho a veinticinco años de prisión. Cuando el hecho fuere perpetrado por personas que tuvieren estado, empleo o asimilación militar, el mínimo de las penas se incrementará en un tercio."
 },
 {
  "id": "CP-226-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 226 bis",
  "titulo": "Delitos contra la seguridad de la nacion · Atentados al orden constitucional y a la vida democrática",
  "tags": "226 bis delitos contra la seguridad de nacion atentados al orden constitucional y a vida democratica",
  "texto": "El que amenazare pública e idóneamente con la comisión de alguna de las conductas previstas en el artículo 226, será reprimido con prisión de uno a cuatro años."
 },
 {
  "id": "CP-227",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 227",
  "titulo": "Delitos contra la seguridad de la nacion · Atentados al orden constitucional y a la vida democrática",
  "tags": "227 delitos contra la seguridad de nacion atentados al orden constitucional y a vida democratica",
  "texto": "Serán reprimidos con las penas establecidas en el artículo 215 para los traidores a la patria, los miembros del Congreso que concedieren al Poder Ejecutivo Nacional y los miembros de las legislaturas provinciales que concedieren a los Gobernadores de provincia, facultades extraordinarias, la suma del poder público o sumisiones o supremacías, por las que la vida, el honor o la fortuna de los argentinos queden a merced de algún gobierno o de alguna persona (artículo 29 de la Constitución Nacional)."
 },
 {
  "id": "CP-227-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 227 bis",
  "titulo": "Delitos contra la seguridad de la nacion · Atentados al orden constitucional y a la vida democrática",
  "tags": "227 bis delitos contra la seguridad de nacion atentados al orden constitucional y a vida democratica",
  "texto": "Serán reprimidos con las penas establecidas en el artículo 215 para los traidores a la patria, con la disminución del artículo 46, los miembros de alguno de los tres poderes del Estado nacional o de las provincias que consintieran la consumación de los hechos descriptos en el artículo 226, continuando en sus funciones o asumiéndolas luego de modificada por la fuerza la Constitución o depuesto alguno de los poderes públicos, o haciendo cumplir las medidas dispuestas por quienes usurpen tales poderes. Se aplicará de uno a ocho años de prisión o reclusión e inhabilitación absoluta por el doble de la condena, a quienes, en los casos previstos en el párrafo anterior, aceptaren colaborar continuando en funciones o asumiéndolas, con las autoridades de facto, en algunos de los siguientes cargos: ministros, secretarios de Estado, subsecretarios, directores generales o nacionales o de jerarquía equivalente en el orden nacional, provincial o municipal, presidente, vicepresidente, vocales o miembros de directorios de organismos descentralizados o autárquicos o de bancos oficiales o de empresas del Estado; sociedades del Estado, sociedades de economía mixta, o de sociedades anónimas con participación estatal mayoritaria, o de entes públicos equivalentes a los enumerados en el orden nacional, provincial o municipal, embajadores, rectores o decanos de universidades nacionales o provinciales, miembros de las fuerzas armadas o de policía o de organismos de seguridad en grados de jefes o equivalentes, intendentes municipales, o miembros del ministerio público fiscal de cualquier jerarquía o fuero, personal jerárquico del Parlamento Nacional y de las legislaturas provinciales. Si las autoridades de facto crearen diferentes jerarquías administrativas o cambiaren las denominaciones de las funciones señaladas en el párrafo anterior, la pena se aplicará a quienes las desempeñen, atendiendo a la análoga naturaleza y contenido de los cargos con relación a los actuales."
 },
 {
  "id": "CP-227-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 227 ter",
  "titulo": "Delitos contra la seguridad de la nacion · Atentados al orden constitucional y a la vida democrática",
  "tags": "227 ter delitos contra la seguridad de nacion atentados al orden constitucional y a vida democratica",
  "texto": "El máximo de la pena establecida para cualquier delito será aumentado en un medio, cuando la acción contribuya a poner en peligro la vigencia de la Constitución Nacional. Esta disposición no será aplicable cuando las circunstancias mencionadas en ella se encuentren contempladas como elemento constitutivo o calificante del delito de que se trate."
 },
 {
  "id": "CP-228",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 228",
  "titulo": "Delitos contra la seguridad de la nacion · Atentados al orden constitucional y a la vida democrática",
  "tags": "228 delitos contra la seguridad de nacion atentados al orden constitucional y a vida democratica",
  "texto": "Se impondrá prisión de seis meses a dos años al que ejecutare o mandare ejecutar decretos de los concilios, bulas, breves y rescriptos del Papa que, para su cumplimiento, necesiten del pase del gobierno, sin haberlo obtenido; y de uno a seis años de la misma pena, al que los ejecutare o mandare ejecutar, a pesar de haber sido denegado dicho pase."
 },
 {
  "id": "CP-229",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 229",
  "titulo": "Delitos contra la seguridad de la nacion · Sedición",
  "tags": "229 delitos contra la seguridad de nacion sedicion",
  "texto": "Serán reprimidos con prisión de uno a seis años, los que, sin rebelarse contra el gobierno nacional, armaren una provincia contra otra, se alzaren en armas para cambiar la Constitución local, deponer alguno de los poderes públicos de una provincia o territorio federal, arrancarle alguna medida o concesión o impedir, aunque sea temporalmente, el libre ejercicio de sus facultades legales o su formación o renovación en los términos y formas establecidas en la ley."
 },
 {
  "id": "CP-230",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 230",
  "titulo": "Delitos contra la seguridad de la nacion · Sedición",
  "tags": "230 delitos contra la seguridad de nacion sedicion",
  "texto": "Serán reprimidos con prisión de uno a cuatro años:\n1. Los individuos de una fuerza armada o reunión de personas, que se atribuyeren los derechos del pueblo y peticionaren a nombre de éste (art. 22 de la Constitución Nacional);\n2. Los que se alzaren públicamente para impedir la ejecución de las leyes nacionales o provinciales o de las resoluciones de los funcionarios públicos nacionales o provinciales, cuando el hecho no constituya delito más severamente penado por este código."
 },
 {
  "id": "CP-231",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 231",
  "titulo": "Delitos contra la seguridad de la nacion · Disposiciones comunes a los Capítulos precedentes",
  "tags": "231 delitos contra la seguridad de nacion disposiciones comunes a los capitulos precedentes",
  "texto": "Luego que se manifieste la rebelión o sedición, la autoridad nacional más próxima intimará hasta dos veces a los sublevados que inmediatamente se disuelvan o retiren, dejando pasar entre una y otra intimación el tiempo necesario para ello. Si los sublevados no se retiraren inmediatamente después de la segunda intimación, la autoridad hará uso de la fuerza para disolverlos. No serán necesarias, respectivamente, la primera y segunda intimación, desde que los sublevados hicieren uso de las armas."
 },
 {
  "id": "CP-232",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 232",
  "titulo": "Delitos contra la seguridad de la nacion · Disposiciones comunes a los Capítulos precedentes",
  "tags": "232 delitos contra la seguridad de nacion disposiciones comunes a los capitulos precedentes",
  "texto": "En caso de disolverse el tumulto sin haber causado otro mal que la perturbación momentánea del orden, sólo serán enjuiciados los promotores o directores, a quienes se reprimirá con la mitad de la pena señalada para el delito."
 },
 {
  "id": "CP-233",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 233",
  "titulo": "Delitos contra la seguridad de la nacion · Disposiciones comunes a los Capítulos precedentes",
  "tags": "233 delitos contra la seguridad de nacion disposiciones comunes a los capitulos precedentes",
  "texto": "El que tomare parte como promotor o director, en una conspiración de dos o más personas para cometer los delitos de rebelión o sedición, será reprimido, si la conspiración fuere descubierta antes de ponerse en ejecución, con la cuarta parte de la pena correspondiente al delito que se trataba de perpetrar."
 },
 {
  "id": "CP-234",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 234",
  "titulo": "Delitos contra la seguridad de la nacion · Disposiciones comunes a los Capítulos precedentes",
  "tags": "234 delitos contra la seguridad de nacion disposiciones comunes a los capitulos precedentes",
  "texto": "El que sedujere tropas o usurpare el mando de ellas, de un buque de guerra, de una plaza fuerte o de un puesto de guardia o retuviere ilegalmente un mando político o militar para cometer una rebelión o una sedición, será reprimido con la mitad de la pena correspondiente al delito que trataba de perpetrar. Si llegare a tener efecto la rebelión o la sedición, la pena será la establecida para los autores de la rebelión o de la sedición en los casos respectivos."
 },
 {
  "id": "CP-235",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 235",
  "titulo": "Delitos contra la seguridad de la nacion · Disposiciones comunes a los Capítulos precedentes",
  "tags": "235 delitos contra la seguridad de nacion disposiciones comunes a los capitulos precedentes",
  "texto": "Los funcionarios públicos que hubieren promovido o ejecutado alguno de los delitos previstos en este Título, sufrirán además inhabilitación especial por un tiempo doble del de la condena.- Los funcionarios que no hubieren resistido una rebelión o sedición por todos los medios a su alcance, sufrirán inhabilitación especial de uno a seis años.- Auméntase al doble el máximo de la pena establecida para los delitos previstos en este Título, para los jefes y agentes de la fuerza pública que incurran en ellos usando u ostentando las armas y demás materiales ofensivos que se les hayan confiado en tal calidad."
 },
 {
  "id": "CP-236",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 236",
  "titulo": "Delitos contra la seguridad de la nacion · Disposiciones comunes a los Capítulos precedentes",
  "tags": "236 delitos contra la seguridad de nacion disposiciones comunes a los capitulos precedentes",
  "texto": "Cuando al ejecutar los delitos previstos en este Título, el culpable cometiere algún otro, se observarán las reglas establecidas para el concurso de hechos punibles."
 },
 {
  "id": "CP-237",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 237",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "237 delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "Será reprimido con prisión de un mes a un año, el que empleare intimidación o fuerza contra un funcionario público o contra la persona que le prestare asistencia a requerimiento de aquél o en virtud de un deber legal, para exigirle la ejecución u omisión de un acto propio de sus funciones."
 },
 {
  "id": "CP-238",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 238",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "238 delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "La prisión será de seis meses a dos años: 1 Si el hecho se cometiere a mano armada; 2 Si el hecho se cometiere por una reunión de más de tres personas; 3 Si el culpable fuere funcionario público; 4 Si el delincuente pusiere manos en la autoridad.\nEn el caso de ser funcionario público, el reo sufrirá además inhabilitación especial por doble tiempo del de la condena."
 },
 {
  "id": "CP-238-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 238 bis",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "238 bis delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "El militar que pusiere manos en el superior, sin lesionarlo o causándole lesiones leves, será penado con prisión de uno (1) a tres (3) años.\nSi el hecho tuviere lugar frente al enemigo o a tropa formada con armas, o si se cometiere en número de seis (6) o más, el máximo de la pena será de seis (6) años.\n(Artículo incorporado por art. 10 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-238-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 238 ter",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "238 ter delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "El militar que resistiere o desobedeciere una orden de servicio legalmente impartida por el superior, frente al enemigo o en situación de peligro inminente de naufragio, incendio u otro estrago, será penado con prisión de uno (1) a cinco (5) años. La misma pena se impondrá si resistiere a una patrulla que proceda en cumplimiento de una consigna en zona de conflicto armado u operaciones o de catástrofe. Si en razón de la resistencia o de la desobediencia se sufrieren pérdidas militares o se impidiese o dificultase la salvación de vidas en supuesto de catástrofe el mínimo de la pena se elevará a cuatro (4) años y el máximo de la pena se elevará a doce (12) años. En cualquier caso se impondrán las penas aquí previstas siempre que no resultare un delito más severamente penado.\n(Artículo incorporado por art. 11 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-239",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 239",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "239 delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "Será reprimido con prisión de quince días a un año, el que resistiere o desobedeciere a un funcionario público en el ejercicio legítimo de sus funciones o a la persona que le prestare asistencia a requerimiento de aquél o en virtud de una obligación legal."
 },
 {
  "id": "CP-240",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 240",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "240 delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "Para los efectos de los dos artículos precedentes, se reputará funcionario público al particular que tratare de aprehender o hubiere aprehendido a un delincuente en flagrante delito."
 },
 {
  "id": "CP-240-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 240 bis",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "240 bis delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "El que violare las normas instrucciones a la población emitidas por la autoridad militar competente en tiempo de conflicto armado para las zonas de combate, será penado con prisión de uno (1) a cuatro (4) años si no resultare un delito más severamente penado.\n(Artículo incorporado por art. 12 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-241",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 241",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "241 delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "Será reprimido con prisión de quince días a seis meses: 1 El que perturbare el orden en las sesiones de los cuerpos legislativos nacionales o provinciales, en las audiencias de los tribunales de justicia o dondequiera que una autoridad esté ejerciendo sus funciones; 2 El que sin estar comprendido en el artículo 237, impidiere o estorbare a un funcionario público cumplir un acto propio de sus funciones."
 },
 {
  "id": "CP-241-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 241 bis",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "241 bis delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "Se impondrá prisión de tres (3) a diez (10) años a los militares que:\n1. Tumultuosamente peticionaren o se atribuyeren la representación de una fuerza armada.\n2. Tomaren armas o hicieren uso de éstas, de naves o aeronaves o extrajeren fuerzas armadas de sus asientos naturales, contra las órdenes de sus superiores.\n3. Hicieren uso del personal de la fuerza, de la nave o de la aeronave bajo su mando contra sus superiores u omitieren resistir o contener a éstas, estando en condiciones de hacerlo.\n4. Será penado con prisión de uno (1) a cinco (5) años la conspiración para cometer los delitos de este artículo. No será penado por conspiración quien la denunciare en tiempo para evitar la comisión del hecho.\n5. Si en razón de los hechos previstos en este artículo resultare la muerte de una o más personas, se sufrieren pérdidas militares o se impidiere o dificultare la salvación de vidas en supuesto de catástrofe, el máximo de la pena se elevará a veinticinco (25) años. En cualquier caso se impondrán las penas aquí previstas siempre que no resultare un delito más severamente penado. (Artículo incorporado por art. 12 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-242",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 242",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "242 delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "Será reprimido con multa de pesos setecientos cincuenta a pesos diez mil e inhabilitación especial de uno a cinco años, el funcionario público que, en el arresto o formación de causa contra un miembro de los poderes públicos nacionales o provinciales, de una convención constituyente o de un colegio electoral, no guardare la forma prescripta en las constituciones o leyes respectivas.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-243",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 243",
  "titulo": "Delitos contra la administracion publica · Atentado y resistencia contra la autoridad",
  "tags": "243 delitos contra la administracion publica atentado y resistencia autoridad",
  "texto": "Será reprimido con prisión de quince días a un mes, el que siendo legalmente citado como testigo, perito o intérprete, se abstuviere de comparecer o de prestar la declaración o exposición respectiva. En el caso del perito o intérprete, se impondrá, además, al reo, inhabilitación especial de un mes a un año."
 },
 {
  "id": "CP-244",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 244",
  "titulo": "Delitos contra la administracion publica · Falsa Denuncia",
  "tags": "244 delitos contra la administracion publica falsa denuncia",
  "texto": "(Artículo derogado por art. 2° de la Ley N° 24.198 B.O. 3/6/1993)."
 },
 {
  "id": "CP-245",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 245",
  "titulo": "Delitos contra la administracion publica · Falsa Denuncia",
  "tags": "245 delitos contra la administracion publica falsa denuncia",
  "texto": "Se impondrá prisión de dos meses a un año o multa de pesos setecientos cincuenta a pesos doce mil quinientos al que denunciare falsamente un delito ante la autoridad.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-246",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 246",
  "titulo": "Delitos contra la administracion publica · Usurpación de autoridad, títulos u honores",
  "tags": "246 delitos contra la administracion publica usurpacion de autoridad, titulos u honores",
  "texto": "Será reprimido con prisión de un mes a un año e inhabilitación especial por doble tiempo: 1 El que asumiere o ejerciere funciones públicas, sin título o nombramiento expedido por autoridad competente; 2 El que después de haber cesado por ministerio de la ley en el desempeño de un cargo público o después de haber recibido de la autoridad competente comunicación oficial de la resolución que ordenó la cesantía o suspensión de sus funciones, continuare ejerciéndolas; 3 El funcionario público que ejerciere funciones correspondientes a otro cargo.\nEl militar que ejerciere o retuviere un mando sin autorización será penado con prisión de uno\n(1) a cuatro (4) años y, en tiempo de conflicto armado de dos (2) a seis (6) años, siempre que no resultare un delito más severamente penado. (Párrafo incorporado por art. 14 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-247",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 247",
  "titulo": "Delitos contra la administracion publica · Usurpación de autoridad, títulos u honores",
  "tags": "247 delitos contra la administracion publica usurpacion de autoridad, titulos u honores",
  "texto": "Será reprimido con prisión de quince días a un año el que ejerciere actos propios de una profesión para la que se requiere una habilitación especial, sin poseer el título o la autorización correspondiente.\nSerá reprimido con multa de setecientos cincuenta a doce mil quinientos pesos, el que públicamente llevare insignias o distintivos de un cargo que no ejerciere o se arrogare grados académicos, títulos profesionales u honores que no le correspondieren. (Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)\n(Artículo sustituido por Ley N° 24.527 B.O.8/9/1995)"
 },
 {
  "id": "CP-248",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 248",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "248 delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será reprimido con prisión de un mes a dos años e inhabilitación especial por doble tiempo, el funcionario público que dictare resoluciones u órdenes contrarias a las constituciones o leyes nacionales o provinciales o ejecutare las órdenes o resoluciones de esta clase existentes o no ejecutare las leyes cuyo cumplimiento le incumbiere."
 },
 {
  "id": "CP-248-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 248 bis",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "248 bis delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será reprimido con inhabilitación absoluta de SEIS (6) meses a DOS (2) años el funcionario público que, debiendo fiscalizar el cumplimiento de las normas de comercialización de ganado, productos y subproductos de origen animal, omitiere inspeccionar conforme los reglamentos a su cargo, establecimientos tales como mercados de hacienda, ferias y remates de animales, mataderos, frigoríficos, saladeros, barracas, graserías, tambos u otros establecimientos o locales afines con la elaboración, manipulación, transformación o comercialización de productos de origen animal y vehículos de transporte de hacienda, productos o subproductos de ese origen.\n(Artículo incorporado por art. 5° de la Ley N° 25.890 B.O. 21/5/2004)"
 },
 {
  "id": "CP-249",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 249",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "249 delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será reprimido con multa de pesos setecientos cincuenta a pesos doce mil quinientos e inhabilitación especial de un mes a un año, el funcionario público que ilegalmente omitiere, rehusare hacer o retardare algún acto de su oficio.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-249-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 249 bis",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "249 bis delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "El militar que en sus funciones y prevalido de su autoridad, arbitrariamente perjudicare o maltratare de cualquier forma a un inferior, será penado con prisión de seis (6) meses a dos (2) años, si no resultare un delito más severamente penado.\n(Artículo incorporado por art. 15 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-250",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 250",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "250 delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será reprimido con prisión de un mes a dos años e inhabilitación especial por doble tiempo, el jefe o agente de la fuerza pública, que rehusare, omitiere o retardare, sin causa justificada, la prestación de un auxilio legalmente requerido por la autoridad civil competente."
 },
 {
  "id": "CP-250-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 250 bis",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "250 bis delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será penado con prisión de cuatro (4) a diez (10) años, siempre que no resultare otro delito más severamente penado, el militar que en tiempo de conflicto armado:\n1. Abandonare sus funciones de control, vigilancia, comunicaciones o la atención de los instrumentos que tuviese a su cargo para esos fines, las descuidase o se incapacitase para su cumplimiento.\n2. Observare cualquier dato significativo para la defensa y no lo informase o tomase las medidas del caso.\n(Artículo incorporado por art. 16 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-251",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 251",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "251 delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será reprimido con prisión de un mes a cuatro años e inhabilitación especial por doble tiempo, el funcionario público que requiriere la asistencia de la fuerza pública contra la ejecución de disposiciones u órdenes legales de la autoridad o de sentencias o de mandatos judiciales."
 },
 {
  "id": "CP-252",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 252",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "252 delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será reprimido con multa de pesos setecientos cincuenta a pesos doce mil quinientos e inhabilitación especial de un mes a un año, el funcionario público que, sin habérsele admitido la renuncia de su destino, lo abandonare con daño del servicio público.\nEl militar que abandonare su servicio, su destino o que desertare en tiempo de conflicto armado o zona de catástrofe, será penado con prisión de uno (1) a seis (6) años. Si como consecuencia de su conducta resultare la muerte de una o más personas, se sufrieren pérdidas militares o se impidiese o dificultase la salvación de vidas en supuesto de catástrofe, el máximo de la pena se elevará a doce (12) años. En cualquier caso se impondrán las penas aquí previstas siempre que no resultare un delito con pena más grave. (Párrafo incorporado por art. 17 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-253",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 253",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "253 delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será reprimido con multa de pesos setecientos cincuenta a pesos doce mil quinientos e inhabilitación especial de seis meses a dos años, el funcionario público que propusiere o nombrare para cargo público, a persona en quien no concurrieren los requisitos legales. En la misma pena incurrirá el que aceptare un cargo para el cual no tenga los requisitos legales.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-253-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 253 bis",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "253 bis delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "El militar que sin orden ni necesidad emprendiere una operación militar, o en sus funciones usare armas sin las formalidades y requerimientos del caso, sometiere a la población civil a restricciones arbitrarias u ordenare o ejerciere cualquier tipo de violencia innecesaria contra cualquier persona, será penado con prisión de uno (1) a cuatro (4) años si no resultare un delito más severamente penado.\n(Artículo incorporado por art. 18 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-253-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 253 ter",
  "titulo": "Delitos contra la administracion publica · Abuso de autoridad y violación de los deberes de los funcionarios públicos",
  "tags": "253 ter delitos contra la administracion publica abuso de autoridad y violacion los deberes funcionarios publicos",
  "texto": "Será penado con prisión de dos (2) a ocho (8) años el militar que por imprudencia o negligencia, impericia en el arte militar o inobservancia de los reglamentos o deberes a su cargo, en el curso de conflicto armado o de asistencia o salvación en situación de catástrofe, causare o no impidiere, la muerte de una o más personas o pérdidas militares, si no resultare un delito más severamente penado.\n(Artículo incorporado por art. 19 del Anexo I de la Ley N° 26.394 B.O. 29/8/2008. Vigencia: comenzará a regir a los SEIS (6) meses de su promulgación. Durante dicho período se llevará a cabo en las áreas pertinentes un programa de divulgación y capacitación sobre su contenido y aplicación)"
 },
 {
  "id": "CP-254",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 254",
  "titulo": "Delitos contra la administracion publica · Violación de sellos y documentos",
  "tags": "254 delitos contra la administracion publica violacion de sellos y documentos",
  "texto": "Será reprimido con prisión de seis meses a dos años, el que violare los sellos puestos por la autoridad para asegurar la conservación o la identidad de una cosa. Si el culpable fuere funcionario público y hubiere cometido el hecho con abuso de su cargo, sufrirá además inhabilitación especial por doble tiempo. Si el hecho se hubiere cometido por imprudencia o negligencia del funcionario público, la pena será de multa de pesos setecientos cincuenta a pesos doce mil quinientos.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-255",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 255",
  "titulo": "Delitos contra la administracion publica · Violación de sellos y documentos",
  "tags": "255 delitos contra la administracion publica violacion de sellos y documentos",
  "texto": "Será reprimido con prisión de un (1) mes a cuatro (4) años, el que sustrajere, alterare, ocultare, destruyere o inutilizare en todo o en parte objetos destinados a servir de prueba ante la autoridad competente, registros o documentos confiados a la custodia de un funcionario público o de otra persona en el interés del servicio público. Si el autor fuere el mismo depositario, sufrirá además inhabilitación especial por doble tiempo.\nSi el hecho se cometiere por imprudencia o negligencia del depositario, éste será reprimido con multa de pesos setecientos cincuenta ($ 750) a pesos doce mil quinientos ($ 12.500).\n(Artículo sustituido por art. 13 de la Ley N° 26.388, B.O. 25/6/2008)\n(Título del capítulo sustituido por art. 30 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-256",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 256",
  "titulo": "Delitos contra la administracion publica · Cohecho y tráfico de influencias",
  "tags": "256 delitos contra la administracion publica cohecho y trafico de influencias",
  "texto": "Será reprimido con reclusión o prisión de uno a seis años e inhabilitación especial perpetua, el funcionario público que por sí o por persona interpuesta, recibiere dinero o cualquier otra dádiva o aceptare una promesa directa o indirecta, para hacer, retardar o dejar de hacer algo relativo a sus funciones\n(Artículo sustituido por art. 31 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-256-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 256 bis",
  "titulo": "Delitos contra la administracion publica · Cohecho y tráfico de influencias",
  "tags": "256 bis delitos contra la administracion publica cohecho y trafico de influencias",
  "texto": "Será reprimido con reclusión o prisión de uno a seis años e inhabilitación especial perpetua para ejercer la función pública, el que por sí o por persona interpuesta solicitare o recibiere dinero o cualquier otra dádiva o aceptare una promesa directa o indirecta, para hacer valer indebidamente su influencia ante un funcionario público, a fin de que éste haga, retarde o deje de hacer algo relativo a sus funciones.\nSi aquella conducta estuviera destinada a hacer valer indebidamente una influencia ante un magistrado del Poder Judicial o del Ministerio Público, a fin de obtener la emisión, dictado, demora u omisión de un dictamen, resolución o fallo en asuntos sometidos a su competencia, el máximo de la pena de prisión o reclusión se elevará a doce años.\n(Artículo incorporado por art. 32 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-257",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 257",
  "titulo": "Delitos contra la administracion publica · Cohecho y tráfico de influencias",
  "tags": "257 delitos contra la administracion publica cohecho y trafico de influencias",
  "texto": "Será reprimido con prisión o reclusión de cuatro a doce años e inhabilitación especial perpetua, el magistrado del Poder Judicial o del Ministerio Público que por sí o por persona interpuesta, recibiere dinero o cualquier otra dádiva o aceptare una promesa directa o indirecta para emitir, dictar, retardar u omitir dictar una resolución, fallo o dictamen, en asuntos sometidos a su competencia\n(Artículo sustituido por art. 33 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-258",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 258",
  "titulo": "Delitos contra la administracion publica · Cohecho y tráfico de influencias",
  "tags": "258 delitos contra la administracion publica cohecho y trafico de influencias",
  "texto": "Será reprimido con prisión de uno a seis años, el que directa o indirectamente diere u ofreciere dádivas en procura de alguna de las conductas reprimidas por los artículos 256 y 256 bis, primer párrafo. Si la dádiva se hiciere u ofreciere con el fin de obtener alguna de las conductas tipificadas en los artículos 256 bis, segundo párrafo y 257, la pena será de reclusión o prisión de dos a seis años. Si el culpable fuere funcionario público, sufrirá además inhabilitación especial de dos a seis años en el primer caso y de tres a diez años en el segundo.\n(Artículo sustituido por art. 34 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-258-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 258 bis",
  "titulo": "Delitos contra la administracion publica · Cohecho y tráfico de influencias",
  "tags": "258 bis delitos contra la administracion publica cohecho y trafico de influencias",
  "texto": "Será reprimido con reclusión de uno (1) a seis (6) años e inhabilitación especial perpetua para ejercer la función pública el que, directa o indirectamente, ofreciere u otorgare a un funcionario público de otro Estado o de una organización pública internacional, ya sea en su beneficio o de un tercero, sumas de dinero o cualquier objeto de valor pecuniario u otras compensaciones, tales como dádivas, favores, promesas o ventajas, a cambio de que dicho funcionario realice u omita realizar un acto relacionado con el ejercicio de sus funciones públicas, o para que haga valer la influencia derivada de su cargo, en un asunto vinculado a una transacción de naturaleza económica, financiera o comercial.\n(Artículo sustituido por art. 1° de la Ley N° 25.825 B.O. 11/12/2003)"
 },
 {
  "id": "CP-259",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 259",
  "titulo": "Delitos contra la administracion publica · Cohecho y tráfico de influencias",
  "tags": "259 delitos contra la administracion publica cohecho y trafico de influencias",
  "texto": "Será reprimido con prisión de un mes a dos años e inhabilitación absoluta de uno a seis años, el funcionario público que admitiere dádivas, que fueran entregadas en consideración a su oficio, mientras permanezca en el ejercicio del cargo. El que presentare u ofreciere la dádiva será reprimido con prisión de un mes a un año."
 },
 {
  "id": "CP-260",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 260",
  "titulo": "Delitos contra la administracion publica · Malversación de caudales públicos",
  "tags": "260 delitos contra la administracion publica malversacion de caudales publicos",
  "texto": "Será reprimido con inhabilitación especial de un mes a tres años, el funcionario público que diere a los caudales o efectos que administrare una aplicación diferente de aquella a que estuvieren destinados. Si de ello resultare daño o entorpecimiento del servicio a que estuvieren destinados, se impondrá además al culpable, multa del veinte al cincuenta por ciento de la cantidad distraída."
 },
 {
  "id": "CP-261",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 261",
  "titulo": "Delitos contra la administracion publica · Malversación de caudales públicos",
  "tags": "261 delitos contra la administracion publica malversacion de caudales publicos",
  "texto": "Será reprimido con reclusión o prisión de dos a diez años e inhabilitación absoluta perpetua, el funcionario público que sustrajere caudales o efectos cuya administración, percepción o custodia le haya sido confiada por razón de su cargo. Será reprimido con la misma pena el funcionario que empleare en provecho propio o de un tercero, trabajos o servicios pagados por una administración pública."
 },
 {
  "id": "CP-262",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 262",
  "titulo": "Delitos contra la administracion publica · Malversación de caudales públicos",
  "tags": "262 delitos contra la administracion publica malversacion de caudales publicos",
  "texto": "Será reprimido con multa del veinte al sesenta por ciento del valor substraído, el funcionario público que, por imprudencia o negligencia o por inobservancia de los reglamentos o deberes de su cargo, diere ocasión a que se efectuare por otra persona la substracción de caudales o efectos de que se trata en el artículo anterior."
 },
 {
  "id": "CP-263",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 263",
  "titulo": "Delitos contra la administracion publica · Malversación de caudales públicos",
  "tags": "263 delitos contra la administracion publica malversacion de caudales publicos",
  "texto": "Quedan sujetos a las disposiciones anteriores los que administraren o custodiaren bienes pertenecientes a establecimientos de instrucción pública o de beneficencia, así como los administradores y depositarios de caudales embargados, secuestrados o depositados por autoridad competente, aunque pertenezcan a particulares."
 },
 {
  "id": "CP-264",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 264",
  "titulo": "Delitos contra la administracion publica · Malversación de caudales públicos",
  "tags": "264 delitos contra la administracion publica malversacion de caudales publicos",
  "texto": "Será reprimido con inhabilitación especial por uno a seis meses, el funcionario público que, teniendo fondos expeditos, demorare injustificadamente un pago ordinario o decretado por autoridad competente. En la misma pena incurrirá el funcionario público que, requerido por la autoridad competente, rehusare entregar una cantidad o efecto depositado o puesto bajo su custodia o administración."
 },
 {
  "id": "CP-265",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 265",
  "titulo": "Delitos contra la administracion publica · Negociaciones incompatibles con el ejercicio de funciones públicas",
  "tags": "265 delitos contra la administracion publica negociaciones incompatibles con el ejercicio de funciones publicas",
  "texto": "Será reprimido con reclusión o prisión de uno a seis años e inhabilitación especial perpetua, el funcionario público que, directamente, por persona interpuesta o por acto simulado, se interesare en miras de un beneficio propio o de un tercero, en cualquier contrato u operación en que intervenga en razón de su cargo.\nEsta disposición será aplicable a los árbitros, amigables componedores, peritos, contadores, tutores, curadores, albaceas, síndicos y liquidadores, con respecto a las funciones cumplidas en el carácter de tales.\n(Artículo sustituido por art. 35 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-266",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 266",
  "titulo": "Delitos contra la administracion publica · Exacciones ilegales",
  "tags": "266 delitos contra la administracion publica exacciones ilegales",
  "texto": "Será reprimido con prisión de uno a cuatro años e inhabilitación especial de uno a cinco años, el funcionario público que, abusando de su cargo, solicitare, exigiere o hiciere pagar o entregar indebidamente, por sí o por interpuesta persona, una contribución, un derecho o una dádiva o cobrase mayores derechos que los que corresponden.\n(Artículo sustituido por art. 37 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-267",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 267",
  "titulo": "Delitos contra la administracion publica · Exacciones ilegales",
  "tags": "267 delitos contra la administracion publica exacciones ilegales",
  "texto": "Si se empleare intimidación o se invocare orden superior, comisión, mandamiento judicial u otra autorización legítima, podrá elevarse la prisión hasta cuatro años y la inhabilitación hasta seis años."
 },
 {
  "id": "CP-268",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 268",
  "titulo": "Delitos contra la administracion publica · Exacciones ilegales",
  "tags": "268 delitos contra la administracion publica exacciones ilegales",
  "texto": "Será reprimido con prisión de dos a seis años e inhabilitación absoluta perpetua, el funcionario público que convirtiere en provecho propio o de tercero las exacciones expresadas en los artículos anteriores."
 },
 {
  "id": "CP-268-(1)",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 268 (1)",
  "titulo": "Delitos contra la administracion publica · Enriquecimiento ilícito de funcionarios y empleados",
  "tags": "268 (1) delitos contra la administracion publica enriquecimiento ilicito de funcionarios y empleados",
  "texto": "Será reprimido con la pena del artículo 256, el funcionario público que con fines de lucro utilizare para sí o para un tercero informaciones o datos de carácter reservado de los que haya tomado conocimiento en razón de su cargo."
 },
 {
  "id": "CP-268-(2)",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 268 (2)",
  "titulo": "Delitos contra la administracion publica · Enriquecimiento ilícito de funcionarios y empleados",
  "tags": "268 (2) delitos contra la administracion publica enriquecimiento ilicito de funcionarios y empleados",
  "texto": "Será reprimido con reclusión o prisión de dos a seis años, multa del cincuenta por ciento al ciento por ciento del valor del enriquecimiento e inhabilitación absoluta perpetua, el que al ser debidamente requerido, no justificare la procedencia de un enriquecimiento patrimonial apreciable suyo o de persona interpuesta para disimularlo, ocurrido con posterioridad a la asunción de un cargo o empleo público y hasta dos años después de haber cesado en su desempeño.\nSe entenderá que hubo enriquecimiento no sólo cuando el patrimonio se hubiese incrementado con dinero, cosas o bienes, sino también cuando se hubiesen cancelado deudas o extinguido obligaciones que lo afectaban.\nLa persona interpuesta para disimular el enriquecimiento será reprimida con la misma pena que el autor del hecho.\n(Artículo sustituido por art. 38 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-268-(3)",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 268 (3)",
  "titulo": "Delitos contra la administracion publica · Enriquecimiento ilícito de funcionarios y empleados",
  "tags": "268 (3) delitos contra la administracion publica enriquecimiento ilicito de funcionarios y empleados",
  "texto": "Será reprimido con prisión de quince días a dos años e inhabilitación especial perpetua el que, en razón de su cargo, estuviere obligado por ley a presentar una declaración jurada patrimonial y omitiere maliciosamente hacerlo.\nEl delito se configurará cuando mediando notificación fehaciente de la intimación respectiva, el sujeto obligado no hubiere dado cumplimiento a los deberes aludidos dentro de los plazos que fije la ley cuya aplicación corresponda.\nEn la misma pena incurrirá el que maliciosamente, falseare u omitiere insertar los datos que las referidas declaraciones juradas deban contener de conformidad con las leyes y reglamentos aplicables.\n(Artículo incorporado por art. 39 de la Ley N° 25.188 B.O. 1/11/1999. Vigencia: a los ocho días desde su publicación.)"
 },
 {
  "id": "CP-269",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 269",
  "titulo": "Delitos contra la administracion publica · Prevaricato",
  "tags": "269 delitos contra la administracion publica prevaricato",
  "texto": "Sufrirá multa de pesos tres mil a pesos setenta y cinco mil e inhabilitación absoluta perpetua el juez que dictare resoluciones contrarias a la ley expresa invocada por las partes o por el mismo o citare, para fundarlas, hechos o resoluciones falsas.\nSi la sentencia fuere condenatoria en causa criminal, la pena será de tres a quince años de reclusión o prisión e inhabilitación absoluta perpetua.\nLo dispuesto en el párrafo primero de este artículo, será aplicable, en su caso, a los árbitros y arbitradores amigables componedores.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-270",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 270",
  "titulo": "Delitos contra la administracion publica · Prevaricato",
  "tags": "270 delitos contra la administracion publica prevaricato",
  "texto": "Será reprimido con multa de pesos dos mil quinientos a pesos treinta mil e inhabilitación absoluta de uno a seis años, el juez que decretare prisión preventiva por delito en virtud del cual no proceda o que prolongare la prisión preventiva que, computada en la forma establecida en el artículo 24, hubiere agotado la pena máxima que podría corresponder al procesado por el delito imputado.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-271",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 271",
  "titulo": "Delitos contra la administracion publica · Prevaricato",
  "tags": "271 delitos contra la administracion publica prevaricato",
  "texto": "Será reprimido con multa de pesos dos mil quinientos a pesos treinta mil, e inhabilitación especial de uno a seis años, el abogado o mandatario judicial que defendiere o representare partes contrarias en el mismo juicio, simultánea o sucesivamente o que de cualquier otro modo, perjudicare deliberadamente la causa que le estuviere confiada.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-272",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 272",
  "titulo": "Delitos contra la administracion publica · Prevaricato",
  "tags": "272 delitos contra la administracion publica prevaricato",
  "texto": "La disposición del artículo anterior será aplicable a los fiscales, asesores y demás funcionarios encargados de emitir su dictamen ante las autoridades."
 },
 {
  "id": "CP-273",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 273",
  "titulo": "Delitos contra la administracion publica · Denegación y retardo de justicia",
  "tags": "273 delitos contra la administracion publica denegacion y retardo de justicia",
  "texto": "Será reprimido con inhabilitación absoluta de uno a cuatro años, el juez que se negare a juzgar so pretexto de obscuridad, insuficiencia o silencio de la ley.\nEn la misma pena incurrirá el juez que retardare maliciosamente la administración de justicia después de requerido por las partes y de vencidos los términos legales."
 },
 {
  "id": "CP-274",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 274",
  "titulo": "Delitos contra la administracion publica · Denegación y retardo de justicia",
  "tags": "274 delitos contra la administracion publica denegacion y retardo de justicia",
  "texto": "El funcionario público que, faltando a la obligación de su cargo, dejare de promover la persecución y represión de los delincuentes, será reprimido con inhabilitación absoluta de seis meses a dos años, a menos que pruebe que su omisión provino de un inconveniente insuperable."
 },
 {
  "id": "CP-275",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 275",
  "titulo": "Delitos contra la administracion publica · Falso testimonio",
  "tags": "275 delitos contra la administracion publica falso testimonio",
  "texto": "Será reprimido con prisión de un mes a cuatro años, el testigo, perito o intérprete que afirmare una falsedad o negare o callare la verdad, en todo o en parte, en su deposición, informe, traducción o interpretación, hecha ante la autoridad competente.\nSi el falso testimonio se cometiere en una causa criminal, en perjuicio del inculpado, la pena será de uno a diez años de reclusión o prisión.\nEn todos los casos se impondrá al reo, además, inhabilitación absoluta por doble tiempo del de la condena."
 },
 {
  "id": "CP-276",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 276",
  "titulo": "Delitos contra la administracion publica · Falso testimonio",
  "tags": "276 delitos contra la administracion publica falso testimonio",
  "texto": "La pena del testigo, perito o intérprete falso, cuya declaración fuere prestada mediante cohecho, se agravará con una multa igual al duplo de la cantidad ofrecida o recibida.\nEl sobornante sufrirá la pena del simple testigo falso."
 },
 {
  "id": "CP-277",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 277",
  "titulo": "Delitos contra la administracion publica · Encubrimiento y Lavado de Activos de origen delictivo",
  "tags": "277 delitos contra la administracion publica encubrimiento y lavado de activos origen delictivo",
  "texto": "1.- Será reprimido con prisión de seis (6) meses a tres (3) años el que, tras la comisión de un delito ejecutado por otro, en el que no hubiera participado:\na) Ayudare a alguien a eludir las investigaciones de la autoridad o a sustraerse a la acción de ésta.\nb) Ocultare, alterare o hiciere desaparecer los rastros, pruebas o instrumentos del delito, o ayudare al autor o partícipe a ocultarlos, alterarlos o hacerlos desaparecer.\nc) Adquiriere, recibiere u ocultare dinero, cosas o efectos provenientes de un delito.\nd) No denunciare la perpetración de un delito o no individualizare al autor o partícipe de un delito ya conocido, cuando estuviere obligado a promover la persecución penal de un delito de esa índole.\ne) Asegurare o ayudare al autor o partícipe a asegurar el producto o provecho del delito.\n2.- En el caso del inciso 1, c), precedente, la pena mínima será de un (1) mes de prisión, si, de acuerdo con las circunstancias, el autor podía sospechar que provenían de un delito.\n3.- La escala penal será aumentada al doble de su mínimo y máximo, cuando:\na) El hecho precedente fuera un delito especialmente grave, siendo tal aquel cuya pena mínima fuera superior a tres (3) años de prisión.\nb) El autor actuare con ánimo de lucro.\nc) El autor se dedicare con habitualidad a la comisión de hechos de encubrimiento.\nd) El autor fuere funcionario público.\nLa agravación de la escala penal, prevista en este inciso sólo operará una vez, aun cuando concurrieren más de una de sus circunstancias calificantes. En este caso, el tribunal podrá tomar en cuenta la pluralidad de causales al individualizar la pena.\n4.- Están exentos de responsabilidad criminal los que hubieren obrado en favor del cónyuge, de un pariente cuyo vínculo no excediere del cuarto grado de consanguinidad o segundo de afinidad o de un amigo íntimo o persona a la que se debiese especial gratitud. La exención no rige respecto de los casos del inciso 1, e) y del inciso 3, b) y c). (Inciso sustituido por Art. 4º de la Ley Nº 26.087, B.O. 24/04/2006.)\n(Artículo sustituido por art. 2° de la Ley N° 25.815 B.O. 1/12/2003)"
 },
 {
  "id": "CP-277-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 277 bis",
  "titulo": "Delitos contra la administracion publica · Encubrimiento y Lavado de Activos de origen delictivo",
  "tags": "277 bis delitos contra la administracion publica encubrimiento y lavado de activos origen delictivo",
  "texto": "Se aplicará prisión de TRES (3) a SEIS (6) años e inhabilitación especial de TRES (3) a DIEZ (10) años al funcionario público que, tras la comisión del delito de abigeato en el que no hubiera participado, violando los deberes a su cargo o abusando de sus funciones, intervenga o facilite el transporte, faena, comercialización o mantenimiento de ganado, sus despojos o los productos obtenidos, conociendo su origen ilícito.\n(Artículo incorporado por art. 6° de la Ley N° 25.890 B.O. 21/572004)"
 },
 {
  "id": "CP-277-ter",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 277 ter",
  "titulo": "Delitos contra la administracion publica · Encubrimiento y Lavado de Activos de origen delictivo",
  "tags": "277 ter delitos contra la administracion publica encubrimiento y lavado de activos origen delictivo",
  "texto": "Se impondrá prisión de SEIS (6) meses a TRES (3) años al que reuniendo las condiciones personales descriptas en el artículo 167 quater inciso 4, por imprudencia o negligencia, intervenga en algunas de las acciones prevista en el artículo precedente, omitiendo adoptar las medidas necesarias para cerciorarse de la procedencia legítima del ganado.\n(Artículo incorporado por art. 7° de la Ley N° 25.890 B.O. 21/572004)"
 },
 {
  "id": "CP-278",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 278",
  "titulo": "Delitos contra la administracion publica · Encubrimiento y Lavado de Activos de origen delictivo",
  "tags": "278 delitos contra la administracion publica encubrimiento y lavado de activos origen delictivo",
  "texto": "1) a) Será reprimido con prisión de dos a diez años y multa de dos a diez veces del monto de la operación el que convirtiere, transfiriere, administrare, vendiere, gravare o aplicare de cualquier otro modo dinero u otra clase de bienes provenientes de un delito en el que no hubiera participado, con la consecuencia posible de que los bienes originarios o los subrogantes adquieran la apariencia de un origen lícito y siempre que su valor supere la suma de cincuenta mil pesos ($ 50.000), sea en un solo acto o por la reiteración de hechos diversos vinculados entre sí;\nb) El mínimo de la escala penal será de cinco (5) años de prisión, cuando el autor realizare el hecho con habitualidad o como miembro de una asociación o banda formada para la comisión continuada de hechos de esta naturaleza;\nc) Si el valor de los bienes no superare la suma indicada en este inciso, letra a, el autor será reprimido, en su caso, conforme a las reglas del artículo 277;\n2) (Inciso vetado por Decreto N° 370/2000 B.O. 10/5/2000)\n3) El que recibiere dinero u otros bienes de origen delictivo, con el fin de hacerlos aplicar en una operación que les dé la apariencia posible de un origen lícito, será reprimido conforme a las reglas del artículo 277;\n4) Los objetos a los que se refiere el delito de los incisos 1, 2 ó 3 de este artículo podrán ser decomisados\n5) La exención establecida en el inciso 4 del artículo 277 no será de aplicación a ninguno de los supuestos contemplados por el presente artículo. (Inciso incorporado por Art. 5º de la Ley Nº 26.087, B.O. 24/04/2006.)\n(Artículo sustituido por art. 1° de la Ley N°25.246 B.O. 10/5/2000. Nota Infoleg: inciso 2) vetado por Decreto N°370/2000 B.O. 10/5/2000: \"2) El que por temeridad o imprudencia grave cometiere alguno de los hechos descriptos en el inciso anterior, primera oración, será reprimido con multa del veinte por ciento (20%) al ciento cincuenta por ciento (150%) del valor de los bienes objeto del delito\")"
 },
 {
  "id": "CP-279",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 279",
  "titulo": "Delitos contra la administracion publica · Encubrimiento y Lavado de Activos de origen delictivo",
  "tags": "279 delitos contra la administracion publica encubrimiento y lavado de activos origen delictivo",
  "texto": "1. Si la escala penal prevista para el delito precedente fuera menor que la establecida en las disposiciones de este Capítulo, será aplicable al caso la escala penal del delito precedente;\n2. Si el delito precedente no estuviere amenazado con pena privativa de libertad, se aplicará a su encubrimiento multa de mil pesos ($ 1.000) a veinte mil pesos ($ 20.000) o la escala penal del delito precedente, si ésta fuera menor. (Frase \"No será punible el encubrimiento de un delito de esa índole, cuando se cometiere por imprudencia, en el sentido del artículo 278, inciso 2;\" vetada por Decreto N°370/2000 B.O. 10/5/2000) 3 Cuando el autor de alguno de los hechos descriptos en el artículo 277, incisos 1 ó 3, o en el artículo 278, inciso 1, fuera funcionario público que hubiera cometido el hecho en ejercicio u ocasión de sus funciones sufrirá además pena de inhabilitación especial de tres (3) a diez (10) años. La misma pena sufrirá el que hubiera actuado en ejercicio u ocasión de una profesión u oficio que requirieran habilitación especial. (Inciso sustituido por art. 3° de la Ley N°25.815 B.O. 1/12/2003)\n4. Las disposiciones de este Capítulo regirán aun cuando el delito precedente hubiera sido cometido fuera del ámbito de aplicación especial de este Código, en tanto el hecho precedente también hubiera estado amenazado con pena en el lugar de su comisión.\n(Artículo sustituido por art. de la Ley N°25.246 B.O.10/5/2000. Vetada parcialmente por Decreto N°370/2000 B.O.10/5/2000)\n(Rúbrica del capítulo sustituida por art. 3° de la Ley N° 23.487 B.O. 26/1/1987)"
 },
 {
  "id": "CP-280",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 280",
  "titulo": "Delitos contra la administracion publica · Evasión y quebrantamiento de pena",
  "tags": "280 delitos contra la administracion publica evasion y quebrantamiento de pena",
  "texto": "Será reprimido con prisión de un mes a un año, el que hallándose legalmente detenido se evadiere por medio de violencia en las personas o fuerza en las cosas."
 },
 {
  "id": "CP-281",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 281",
  "titulo": "Delitos contra la administracion publica · Evasión y quebrantamiento de pena",
  "tags": "281 delitos contra la administracion publica evasion y quebrantamiento de pena",
  "texto": "Será reprimido con prisión de un mes a cuatro años, el que favoreciere la evasión de algún detenido o condenado, y si fuere funcionario público, sufrirá, además, inhabilitación absoluta por triple tiempo.\nSi la evasión se produjere por negligencia de un funcionario público, éste será reprimido con multa de pesos argentinos mil a pesos argentinos quince mil.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-281-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 281 bis",
  "titulo": "Delitos contra la administracion publica · Evasión y quebrantamiento de pena",
  "tags": "281 bis delitos contra la administracion publica evasion y quebrantamiento de pena",
  "texto": "El que quebrantare una inhabilitación judicialmente impuesta será reprimido con prisión de dos meses a dos años.\n(Artículo incorporado por art.4° de la Ley N° 23.487 B.O. 26/1/1987)"
 },
 {
  "id": "CP-282",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 282",
  "titulo": "Delitos contra la fe publica · Falsificación de moneda, billetes de banco, títulos al portador y documentos de crédito",
  "tags": "282 delitos contra la fe publica falsificacion de moneda, billetes banco, titulos al portador y documentos credito",
  "texto": "Serán reprimidos con reclusión o prisión de tres a quince años, el que falsificare moneda que tenga curso legal en la República y el que la introdujere, expendiere o pusiere en circulación.ARTICULO 283. - Será reprimido con reclusión o prisión de uno a cinco años, el que cercenare o alterare moneda de curso legal y el que introdujere, expendiere o pusiere en circulación moneda cercenada o alterada.\nSi la alteración consistiere en cambiar el color de la moneda, la pena será de seis meses a tres años de prisión."
 },
 {
  "id": "CP-284",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 284",
  "titulo": "Delitos contra la fe publica · Falsificación de moneda, billetes de banco, títulos al portador y documentos de crédito",
  "tags": "284 delitos contra la fe publica falsificacion de moneda, billetes banco, titulos al portador y documentos credito",
  "texto": "Si la moneda falsa, cercenada o alterada se hubiere recibido de buena fe y se expendiere o circulare con conocimiento de la falsedad, cercenamiento o alteración, la pena será de pesos argentinos mil a pesos argentinos quince mil.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-285",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 285",
  "titulo": "Delitos contra la fe publica · Falsificación de moneda, billetes de banco, títulos al portador y documentos de crédito",
  "tags": "285 delitos contra la fe publica falsificacion de moneda, billetes banco, titulos al portador y documentos credito",
  "texto": "Para los efectos de los artículos anteriores quedan equiparados a la moneda nacional, la moneda extranjera, los títulos de la deuda nacional, provincial o municipal y sus cupones, los bonos o libranzas de los tesoros nacional, provinciales y municipales, los billetes de banco, títulos, cédulas, acciones, valores negociables y tarjetas de compra, crédito o débito, legalmente emitidos por entidades nacionales o extranjeras autorizadas para ello, y los cheques de todo tipo, incluidos los de viajero, cualquiera que fuere la sede del banco girado.\n(Artículo sustituido por art. 2° de la Ley N° 25.930 B.O. 21/9/2004)"
 },
 {
  "id": "CP-286",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 286",
  "titulo": "Delitos contra la fe publica · Falsificación de moneda, billetes de banco, títulos al portador y documentos de crédito",
  "tags": "286 delitos contra la fe publica falsificacion de moneda, billetes banco, titulos al portador y documentos credito",
  "texto": "(Artículo derogado por art. 3° de la Ley N° 25.930 B.O. 21/9/2004)"
 },
 {
  "id": "CP-287",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 287",
  "titulo": "Delitos contra la fe publica · Falsificación de moneda, billetes de banco, títulos al portador y documentos de crédito",
  "tags": "287 delitos contra la fe publica falsificacion de moneda, billetes banco, titulos al portador y documentos credito",
  "texto": "Serán reprimidos con reclusión o prisión de uno a seis años e inhabilitación absoluta por doble tiempo, el funcionario público y el director o administrador de un banco o de una compañía que fabricare o emitiere o autorizare la fabricación o emisión de moneda, con título o peso inferiores al de la ley, billetes de banco o cualesquiera títulos, cédulas o acciones al portador, en cantidad superior a la autorizada."
 },
 {
  "id": "CP-288",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 288",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "288 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Será reprimido con reclusión o prisión de uno a seis años:\n1º. El que falsificare sellos oficiales;\n2º. El que falsificare papel sellado, sellos de correos o telégrafos o cualquiera otra clase de efectos timbrados cuya emisión esté reservada a la autoridad o tenga por objeto el cobro de impuestos.- En estos casos, así como en los de los artículos siguientes, se considerará falsificación la impresión fraudulenta del sello verdadero."
 },
 {
  "id": "CP-289",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 289",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "289 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Será reprimido con prisión de seis meses a tres años:\n1. El que falsificare marcas, contraseñas o firmas oficialmente usadas o legalmente requeridas para contrastar pesas o medidas, identificar cualquier objeto o certificar su calidad, cantidad o contenido, y el que las aplicare a objetos distintos de aquellos a que debían ser aplicados.\n2. El que falsificare billetes de empresas públicas de transporte.\n3. El que falsificare, alterare o suprimiere la numeración de un objeto registrada de acuerdo con la ley.\n(Artículo sustituido por art. 1° de la Ley N° 24.721 B.O. 18/11/1996)"
 },
 {
  "id": "CP-290",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 290",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "290 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Será reprimido con prisión de quince días a un año, el que hiciere desaparecer de cualquiera de los sellos, timbres, marcas o contraseñas, a que se refieren los artículos anteriores, el signo que indique haber ya servido o sido inutilizado para el objeto de su expedición.El que a sabiendas usare, hiciere usar o pusiere en venta estos sellos, timbres, etc., inutilizados, será reprimido con multa de pesos setecientos cincuenta a pesos doce mil quinientos.\n(Nota Infoleg: multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993)"
 },
 {
  "id": "CP-291",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 291",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "291 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Cuando el culpable de alguno de los delitos comprendidos en los artículos anteriores, fuere funcionario público y cometiere el hecho abusando de su cargo, sufrirá, además, inhabilitación absoluta por doble tiempo del de la condena.Capítulo III Falsificación de documentos en general"
 },
 {
  "id": "CP-292",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 292",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "292 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "El que hiciere en todo o en parte un documento falso o adultere uno verdadero, de modo que pueda resultar perjuicio, será reprimido con reclusión o prisión de uno a seis años, si se tratare de un instrumento público y con prisión de seis meses a dos años, si se tratare de un instrumento privado.\nSi el documento falsificado o adulterado fuere de los destinados a acreditar la identidad de las personas o la titularidad del dominio o habilitación para circular de vehículos automotores, la pena será de tres a ocho años.\nPara los efectos del párrafo anterior están equiparados a los documentos destinados a acreditar la identidad de las personas, aquellos que a tal fin se dieren a los integrantes de las fuerzas armadas, de seguridad, policiales o penitenciarias, las cédulas de identidad expedidas por autoridad pública competente, las libretas cívicas o de enrolamiento, y los pasaportes, así como también los certificados de parto y de nacimiento.\n(Artículo sustituido por art. 9° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-293",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 293",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "293 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Será reprimido con reclusión o prisión de uno a seis años, el que insertare o hiciere insertar en un instrumento público declaraciones falsas, concernientes a un hecho que el documento deba probar, de modo que pueda resultar perjuicio.\nSi se tratase de los documentos o certificados mencionados en el último párrafo del artículo anterior, la pena será de 3 a 8 años. (Párrafo sustituido por art. 10° de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-293-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 293 bis",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "293 bis delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Se impondrá prisión de UNO (1) a TRES (3) años al funcionario público que, por imprudencia o negligencia, intervenga en la expedición de guías de tránsito de ganado o en el visado o legalización de certificados de adquisición u otros documentos que acrediten la propiedad del semoviente, omitiendo adoptar las medidas necesarias para cerciorarse de su procedencia legítima.\n(Artículo incorporado por art. 8° de la Ley N° 25.890 B.O. 21/5/2004)"
 },
 {
  "id": "CP-294",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 294",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "294 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "El que suprimiere o destruyere, en todo o en parte, un documento de modo que pueda resultar perjuicio, incurrirá en las penas señaladas en los artículos anteriores, en los casos respectivos."
 },
 {
  "id": "CP-295",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 295",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "295 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Sufrirá prisión de un mes a un año, el médico que diere por escrito un certificado falso, concerniente a la existencia o inexistencia, presente o pasada, de alguna enfermedad o lesión cuando de ello resulte perjuicio.\nLa pena será de uno a cuatro años, si el falso certificado debiera tener por consecuencia que una persona sana fuera detenida en un manicomio, lazareto u otro hospital."
 },
 {
  "id": "CP-296",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 296",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "296 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "El que hiciere uso de un documento o certificado falso o adulterado, será reprimido como si fuere autor de la falsedad."
 },
 {
  "id": "CP-297",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 297",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "297 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Para los efectos de este Capítulo, quedan equiparados a los instrumentos públicos los testamentos ológrafos o cerrados, los certificados de parto o de nacimiento, las letras de cambio y los títulos de crédito transmisibles por endoso o al portador, no comprendidos en el artículo 285.\n(Artículo sustituido por art. 11 de la Ley N° 24.410 B.O. 2/1/1995)"
 },
 {
  "id": "CP-298",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 298",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "298 delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Cuando alguno de los delitos previstos en este Capítulo, fuere ejecutado por un funcionario público con abuso de sus funciones, el culpable sufrirá, además, inhabilitación absoluta por doble tiempo del de la condena."
 },
 {
  "id": "CP-298-bis",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 298 bis",
  "titulo": "Delitos contra la fe publica · Falsificación de sellos, timbres y marcas",
  "tags": "298 bis delitos contra la fe publica falsificacion de sellos, timbres y marcas",
  "texto": "Quienes emitan o acepten facturas de crédito que no correspondan a compraventa, locación de cosas muebles, locación de servicios o locación de obra realmente contratadas, serán sancionados con la pena prevista en el artículo 293 de este Código. Igual pena les corresponderá a quienes injustificadamente rechacen o eludan la aceptación de factura de crédito, cuando el servicio ya hubiese sido prestado en forma debida, o reteniendo la mercadería que se le hubiere entregado.\n(Artículo sustituido por art. 3° de la Ley N° 24.760 B.O.13/1/1997)"
 },
 {
  "id": "CP-299",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 299",
  "titulo": "Delitos contra la fe publica · Disposiciones comunes a los Capítulos precedentes",
  "tags": "299 delitos contra la fe publica disposiciones comunes a los capitulos precedentes",
  "texto": "Sufrirá prisión de un mes a un año, el que fabricare, introdujere en el país o conservare en su poder, materias o instrumentos conocidamente destinados a cometer alguna de las falsificaciones legisladas en este Título.Capítulo V De los fraudes al comercio y a la industria"
 },
 {
  "id": "CP-300",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 300",
  "titulo": "Delitos contra la fe publica · Disposiciones comunes a los Capítulos precedentes",
  "tags": "300 delitos contra la fe publica disposiciones comunes a los capitulos precedentes",
  "texto": "Serán reprimidos con prisión de seis meses a dos años:\n1º. El que hiciere alzar o bajar el precio de las mercaderías, fondos públicos o valores, por medio de noticias falsas, negociaciones fingidas o por reunión o coalición entre los principales tenedores de una mercancía o género, con el fin de no venderla o de no venderla sino a un precio determinado;\n2º. El que ofreciere fondos públicos o acciones u obligaciones de alguna sociedad o persona jurídica, disimulando u ocultando hechos o circunstancias verdaderas o afirmando o haciendo entrever hechos o circunstancias falsas;\n3º. El fundador, director, administrador, liquidador o síndico de una sociedad anónima o cooperativa o de otra persona colectiva, que a sabiendas publicare, certificare o autorizare un inventario, un balance, una cuenta de ganancias y pérdidas o los correspondientes informes, actas o memorias, falsos o incompletos o informare a la asamblea o reunión de socios, con falsedad o reticencia, sobre hechos importantes para apreciar la situación económica de la empresa, cualquiera que hubiere sido el propósito perseguido al verificarlo.ARTICULO 301. - Será reprimido con prisión de seis meses a dos años, el director, gerente, administrador o liquidador de una sociedad anónima, o cooperativa o de otra persona colectiva que a sabiendas prestare su concurso o consentimiento a actos contrarios a la ley o a los estatutos, de los cuales pueda derivar algún perjuicio. Si el acto importare emisión de acciones o de cuotas de capital, el máximo de la pena se elevará a tres años de prisión, siempre que el hecho no importare un delito más gravemente penado.ARTICULO 301 bis.-(Artículo derogado por art. 10 de la Ley N° 24.064 B.O. 17/1/1992)"
 },
 {
  "id": "CP-302",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 302",
  "titulo": "Delitos contra la fe publica · Del pago con cheques sin provisión de fondos",
  "tags": "302 delitos contra la fe publica del pago con cheques sin provision de fondos",
  "texto": "Será reprimido con prisión de seis meses a cuatro años e inhabilitación especial de uno a cinco años, siempre que no concurran las circunstancias del artículo 172:\n1º. El que dé en pago o entregue por cualquier concepto a un tercero un cheque sin tener provisión de fondos o autorización expresa para girar en descubierto, y no lo abonare en moneda nacional dentro de las veinticuatro horas de habérsele comunicado la falta de pago mediante aviso bancario, comunicación del tenedor o cualquier otra forma documentada de interpelación;\n2º. El que dé en pago o entregue, por cualquier concepto a un tercero un cheque, a sabiendas de que al tiempo de su presentación no podrá legalmente ser pagado;\n3º. El que librare un cheque y diera contraorden para el pago, fuera de los casos en que la ley autoriza a hacerlo, o frustrare maliciosamente su pago;\n4º. El que librare un cheque en formulario ajeno sin autorización.\nDISPOSICIONES COMPLEMENTARIAS"
 },
 {
  "id": "CP-303",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 303",
  "titulo": "Delitos contra la fe publica · Del pago con cheques sin provisión de fondos",
  "tags": "303 delitos contra la fe publica del pago con cheques sin provision de fondos",
  "texto": "El presente código regirá como ley de la Nación seis meses después de su promulgación."
 },
 {
  "id": "CP-304",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 304",
  "titulo": "Delitos contra la fe publica · Del pago con cheques sin provisión de fondos",
  "tags": "304 delitos contra la fe publica del pago con cheques sin provision de fondos",
  "texto": "El Poder Ejecutivo dispondrá la edición oficial del código conjuntamente con la exposición de motivos que lo acompaña. Los gastos que origine la publicación se imputarán a esta ley."
 },
 {
  "id": "CP-305",
  "cuerpo": "CP",
  "etiqueta": "Código Penal · Art. 305",
  "titulo": "Delitos contra la fe publica · Del pago con cheques sin provisión de fondos",
  "tags": "305 delitos contra la fe publica del pago con cheques sin provision de fondos",
  "texto": "Quedan derogadas las leyes números 49, 1920, 3335, 3900, 3972, 4189, 7029, 9077 y 9143, lo mismo que las demás en cuanto se opusieran a este código. Las penas de presidio y penitenciaría que establecen las leyes especiales no derogadas por este código, quedan reemplazadas por la de reclusión y las de prisión y arresto por la de prisión.\nAntecedentes Normativos\n- Artículo 41 ter, incorporado por art. 2° de la Ley N° 25.742 B.O. 20/6/2003;\n- Artículo 24, último párrafo incorporado por art. 1° de la Ley N°25. 742 B.O. 20/6/2003;\n- Artículo 206, párrafos incorporados por art. 1° de la Ley N° 25.528 B.O. 9/1/2002;\n- Artículo 78 bis, incorporado por art. 51 de la Ley N° 25.506 B.O. 14/12/2001;\n- Artículo 277, sustituido por art. 1° de la Ley N° 25.246 10/5/2000;\n- Artículo 157 bis, incorporado por art. 32 de la Ley N° 25.326 B.O. 2/11/2000;\n- Artículo 203 sustituido por art. 5° de la Ley N° 25.189 28/10/1999;\n- Artículo 128, sustituido por art. 9° de la Ley N° 25.087 B.O. 14/5/1999;\n- Artículo127 ter, incorporado por art. 17 de la Ley N° 25.087 B.O. 14/5/1999;\n- Artículo 127 bis, sustituido por art. 16 de la Ley N° 25.087 B.O. 14/5/1999;\n- Artículo 23, sustituido por art. 26 de la Ley N° 25.188 B.O. 1/11/1999;\n- Artículo 258 bis, incorporado por art. 36 de la Ley N° 25.188 B.O. 1/11/1999;\n- Artículo 189 bis, sustituido por art. 2° de la Ley N° 25.086 B.O. 14/5/1999. Frase \"o de uso civil condicionado\" vetada por Decreto N° 496/1999;\n- Artículo 189 ter, incorporado por art. 3° de la Ley N° 25.086 B.O. 14/5/1999;\n- Nota Infoleg: Artículo 204 ter, multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993;\n- Nota Infoleg, Artículo 204 bis, multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993;\n- Nota Infoleg: Artículo 203, multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993;\n- Nota Infoleg: Artículo 155, multa actualizada por art. 1° de la Ley N°24.286 B.O. 29/12/1993;\n- Nota Infoleg: Artículo 255, multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993;\n- Artículo 286, multa actualizada por art. 1° de la Ley N° 24.286 B.O. 29/12/1993;\n- Artículo 72, inc. 3) incorporado por art. 4° de la Ley N° 24.270 B.O. 26/11/1993;\n- Artículo 298 bis, sustituido por art.9° de la Ley N° 24.064 B.O.17/1/1992;\n- Artículo 204 sustituido por art. 1° de la Ley N° 23.737, B.O. 11/10/1989;\n- Artículo 204 bis incorporado por Ley N° 23.737 B.O.11/10/1989;\n- Artículo 204 ter incorporado por Ley N°23.737 B.O.11/10/1989;\n- Artículo 204 quater incorporado por Ley N° 23.737 B.O.11/10/1989;\n- Artículo 163, inciso 1, sustituido por Ley N° 23.588 B.O.24/8/1988;\n- Actualización montos de las multas: Ley N° 23.479 B.O.26/1/1987, Ley N° 23.974 B.O.17/9/1991 y la Ley N° 24.286 B.O. 29/12/1993;\n- Artículo 72 sustituido por art. 1° de la Ley N° 23.487 B.O. 26/1/1987;\n- Rúbrica del Capítulo III, Título III del Libro Segundo, sustituida por art. 2° de la Ley N°23.487 B.O. 26/1/1987;\n- Artículo 277, sustituido por art. 1° de la Ley N° 23.468 26/1/1987;\n- Artículo 204, monto actualizado por art. 1° de la Ley N° 23.479, 16/1/1987;\n- Artículo 279, sustituido por art. 1° de la Ley N° 23.468 26/1/1987."
 }
